using KnExchange;

Console.OutputEncoding = System.Text.Encoding.UTF8;

// 言語: --lang ja|en、無ければ環境変数 KN_EXCHANGE_LANG、それも無ければ Windows の表示言語
var lang = Environment.GetEnvironmentVariable("KN_EXCHANGE_LANG");
var langAt = Array.IndexOf(args, "--lang");
if (langAt >= 0)
{
    if (langAt + 1 >= args.Length) return Fail(Lang.T("--lang に値がありません。", "--lang needs a value."));
    lang = args[langAt + 1];
    args = args.Where((_, i) => i != langAt && i != langAt + 1).ToArray();
}
Lang.Japanese = string.IsNullOrWhiteSpace(lang)
    ? System.Globalization.CultureInfo.CurrentUICulture.TwoLetterISOLanguageName == "ja"
    : lang.Trim().StartsWith("ja", StringComparison.OrdinalIgnoreCase);

if (args.Length == 0 || args[0] is "-h" or "--help" or "help")
{
    PrintUsage();
    return 0;
}

try
{
    return args[0] switch
    {
        "convert" => RunConvert(args[1..]),
        "inspect" => RunInspect(args[1..]),
        "prompt" => RunPrompt(args[1..]),
        "--version" or "version" => Print($"kn_exchange {ModConverter.Version}"),
        _ => Fail(Lang.T($"不明なコマンドです: {args[0]}", $"Unknown command: {args[0]}")),
    };
}
catch (Exception ex) when (ex is InvalidOperationException or ArgumentException
    or FileNotFoundException or NotSupportedException or InvalidDataException or IOException)
{
    Console.Error.WriteLine(Lang.T("エラー: ", "Error: ") + ex.Message);
    return 1;
}

static void PrintUsage()
{
    if (Lang.Japanese)
    {
        Console.WriteLine($"""
            kn_exchange {ModConverter.Version} — シングルプレイヤー用 mod を FiveM リソースへ変換する

            使い方:
              kn_exchange convert <書庫|フォルダ|rpf> [-o <出力先>] [--name <名前>] [--variant <文字列>] [--force]
                                [--vanilla <フォルダ>] [--replace] [--base <モデル名>] [--gender male|female] [--lang ja|en]
              kn_exchange inspect <書庫|フォルダ|rpf>
              kn_exchange prompt [変換のオプション]     入力を 1 行ずつ聞いて、続けて変換する（convert.bat が使う）

            オプション:
              -o, --out      出力先フォルダ（既定: .\out）。この下にリソース名のフォルダを作る
              --name         リソース名を指定する（出力が 1 つのときだけ有効）
              --variant      Legacy / Enhanced など複数系統があるとき、パスにこの文字列を含むものを使う
              --force        出力先に既存ファイルがあっても書き込む
              --lang         表示の言語（ja / en）。既定は Windows の表示言語。環境変数 KN_EXCHANGE_LANG でも可

            置き換え型の mod（バニラの車を差し替えるもの）:
              既定では別名の車として追加する形へ作り直す。元の車の定義を写すので、バニラの vehicles.meta が要る。
              --vanilla      バニラの vehicles.meta（と carvariations）を置いたフォルダ。環境変数 KN_EXCHANGE_VANILLA でも可
              --name         新しいモデル名（未指定なら書庫名から作る）
              --base         複数の車を含む mod で、変換する 1 台（置き換え先のモデル名）
              --replace      別名にせず、バニラの車を上書きする形のまま出す

            ped:
              定義（peds.meta）を持たない配布物には、既定の定義を作って添える。
              --gender       male（既定）か female。歩き方や体格の設定に使う
              バニラの ped を置き換えるものは、--vanilla のフォルダに peds.meta があれば別名の ped にする。
            """);
        return;
    }

    Console.WriteLine($"""
        kn_exchange {ModConverter.Version} — converts single-player mods into FiveM resources

        Usage:
          kn_exchange convert <archive|folder|rpf> [-o <output>] [--name <name>] [--variant <text>] [--force]
                            [--vanilla <folder>] [--replace] [--base <model>] [--gender male|female] [--lang ja|en]
          kn_exchange inspect <archive|folder|rpf>
          kn_exchange prompt [convert options]     asks for inputs one line at a time and converts each (used by convert.bat)

        Options:
          -o, --out      Output folder (default: .\out). A folder named after the resource is created inside it
          --name         Resource name (only when there is a single output)
          --variant      When several builds exist (Legacy / Enhanced), use the one whose path contains this text
          --force        Write even if the output folder already has files
          --lang         Message language (ja / en). Defaults to the Windows display language. Also KN_EXCHANGE_LANG

        Replace-type mods (those that swap out a vanilla vehicle):
          By default they are rebuilt as an added vehicle with its own name. The original vehicle's definition
          is copied, so the vanilla vehicles.meta is needed.
          --vanilla      Folder holding the vanilla vehicles.meta (and carvariations). Also KN_EXCHANGE_VANILLA
          --name         New model name (derived from the archive name when omitted)
          --base         For mods with several vehicles, the one to convert (the model it replaces)
          --replace      Keep it as a replacement of the vanilla vehicle instead of renaming it

        Peds:
          Releases without a definition (peds.meta) get a default one.
          --gender       male (default) or female. Used for the walk style and build
          Replacements of a vanilla ped are renamed when the --vanilla folder holds peds.meta.
        """);
}

static int RunConvert(string[] a)
{
    var options = new ConvertOptions { OutputDir = "out" };

    for (var i = 0; i < a.Length; i++)
    {
        switch (a[i])
        {
            case "-o" or "--out": options.OutputDir = Next(a, ref i); break;
            case "--name": options.Name = Next(a, ref i); break;
            case "--variant": options.Variant = Next(a, ref i); break;
            case "--force": options.Force = true; break;
            case "--vanilla": options.Vanilla = Next(a, ref i); break;
            case "--replace": options.Replace = true; break;
            case "--base": options.BaseModel = Next(a, ref i); break;
            case "--gender": options.Gender = Next(a, ref i); break;
            default:
                if (a[i].StartsWith('-')) return Fail(Lang.T($"不明なオプションです: {a[i]}", $"Unknown option: {a[i]}"));
                if (options.Input != null) return Fail(Lang.T("入力は 1 つだけ指定してください。", "Give exactly one input."));
                options.Input = a[i];
                break;
        }
    }

    if (options.Input == null) return Fail(Lang.T("入力が指定されていません。", "No input was given."));

    var reports = ModConverter.Convert(options, Console.WriteLine);

    foreach (var r in reports)
        ModInspector.Describe(r, Console.WriteLine);

    return 0;
}

/// <summary>入力を 1 行ずつ受け取って変換する。ウィンドウへ書庫を落として使う。</summary>
static int RunPrompt(string[] options)
{
    Console.WriteLine(Lang.T(
        $"kn_exchange {ModConverter.Version} — シングルプレイヤー用 mod を FiveM リソースへ変換します。",
        $"kn_exchange {ModConverter.Version} — converts single-player mods into FiveM resources."));

    while (true)
    {
        Console.WriteLine();
        Console.WriteLine(Lang.T(
            "書庫（.zip / .rar / .7z）かフォルダをこのウィンドウへドラッグ&ドロップして、Enter を押してください。",
            "Drag and drop an archive (.zip / .rar / .7z) or a folder onto this window, then press Enter."));
        Console.WriteLine(Lang.T("何も入れずに Enter で終了します。", "Press Enter on an empty line to quit."));
        Console.Write("> ");

        var line = Console.ReadLine()?.Trim().Trim('"').Trim();
        if (string.IsNullOrEmpty(line)) return 0;

        try
        {
            RunConvert(options.Prepend(line).ToArray());
        }
        catch (Exception ex) when (ex is InvalidOperationException or ArgumentException
            or FileNotFoundException or NotSupportedException or InvalidDataException or IOException)
        {
            Console.Error.WriteLine(Lang.T("エラー: ", "Error: ") + ex.Message);
        }
    }
}

static int RunInspect(string[] a)
{
    if (a.Length != 1) return Fail(Lang.T("入力を 1 つ指定してください。", "Give exactly one input."));

    ModInspector.Inspect(a[0], Console.WriteLine);
    return 0;
}

static string Next(string[] a, ref int i)
{
    if (i + 1 >= a.Length) throw new ArgumentException(Lang.T($"{a[i]} に値がありません。", $"{a[i]} needs a value."));
    return a[++i];
}

static int Print(string message)
{
    Console.WriteLine(message);
    return 0;
}

static int Fail(string message)
{
    Console.Error.WriteLine(Lang.T("エラー: ", "Error: ") + message);
    return 2;
}

