using System.Text;
using System.Xml;
using System.Xml.Linq;

namespace KnExchange;

/// <summary>
/// 置き換え型の mod を、別名の車として追加するための meta を作る。
///
/// 置き換え型はモデルとテクスチャしか持たず、車としての定義（座席・カメラ・音・ハンドリング）は
/// 置き換え先のバニラ車のものを借りている。別名にするには、その定義を写して名前だけ変える。
///
/// バニラの定義はゲーム本体の rpf（暗号化されていて読めない）にあるので、利用者が
/// 取り出しておいた vehicles.meta を外から受け取る。
/// </summary>
public static class AddonBuilder
{
    public sealed class Result
    {
        public byte[] VehiclesMeta { get; set; }
        public byte[] CarVariations { get; set; }   // バニラ側に資料が無ければ null
        public string GameName { get; set; }
        public List<string> Warnings { get; } = new();
    }

    /// <summary>表示名のキー（gameName）に使える長さ。これを超えると名前が引けなくなる。</summary>
    private const int MaxGameNameLength = 11;

    /// <summary>フォルダまたはファイルの指定から、目的のファイルを探す。</summary>
    public static string FindVanillaFile(string vanillaPath, params string[] names)
    {
        if (string.IsNullOrEmpty(vanillaPath)) return null;

        if (File.Exists(vanillaPath))
        {
            if (names.Contains(Path.GetFileName(vanillaPath), StringComparer.OrdinalIgnoreCase)) return vanillaPath;
            vanillaPath = Path.GetDirectoryName(Path.GetFullPath(vanillaPath));
        }

        if (!Directory.Exists(vanillaPath)) return null;

        return names.Select(n => Path.Combine(vanillaPath, n)).FirstOrDefault(File.Exists);
    }

    /// <summary>バニラの定義にその車があるか。</summary>
    public static HashSet<string> ReadModelNames(string vehiclesMetaPath) =>
        XDocument.Load(vehiclesMetaPath).Descendants("InitDatas").Elements("Item")
            .Select(i => ((string)i.Element("modelName") ?? "").Trim().ToLowerInvariant())
            .Where(n => n.Length > 0)
            .ToHashSet();

    /// <param name="renameTxd">mod がテクスチャ辞書も持っているか。持っていなければバニラのものを使い続ける。</param>
    public static Result Build(string vanillaPath, string baseModel, string newModel, bool renameTxd)
    {
        var result = new Result();

        var vehiclesPath = FindVanillaFile(vanillaPath, "vehicles.meta")
            ?? throw new InvalidOperationException(
                Lang.T($"バニラの vehicles.meta が見つかりません: {vanillaPath}", $"The vanilla vehicles.meta was not found: {vanillaPath}"));

        var doc = XDocument.Load(vehiclesPath);
        var source = doc.Descendants("InitDatas").Elements("Item")
            .FirstOrDefault(i => Same((string)i.Element("modelName"), baseModel))
            ?? throw new InvalidOperationException(
                Lang.T($"バニラの vehicles.meta に {baseModel} の定義がありません。" +
                "DLC で追加された車は、その DLC の vehicles.meta を渡す必要があります。", $"The vanilla vehicles.meta has no definition for {baseModel}. " +
                "For a vehicle added by a DLC, pass that DLC's vehicles.meta."));

        // --- vehicles.meta ---
        var item = new XElement(source);
        var baseTxd = ((string)item.Element("txdName") ?? baseModel).Trim();

        item.SetElementValue("modelName", newModel);
        if (renameTxd) item.SetElementValue("txdName", newModel);

        result.GameName = newModel.ToUpperInvariant();
        if (result.GameName.Length > MaxGameNameLength) result.GameName = result.GameName[..MaxGameNameLength];
        item.SetElementValue("gameName", result.GameName);

        //[ 音 ]
        // audioNameHash が空の車は、モデル名で音を引いている。名前を変えると引けなくなり
        // 無音になるので、元の車の名前を明示する。
        var audio = item.Element("audioNameHash");
        if (audio != null && string.IsNullOrWhiteSpace(audio.Value))
            audio.Value = ((string)source.Element("modelName")).Trim();

        var root = new XElement("CVehicleModelInfo__InitDataList",
            new XElement("residentTxd", "vehshare"),
            new XElement("residentAnims"),
            new XElement("InitDatas", item));

        // 親のテクスチャ辞書（内装などの共用テクスチャ）への繋がりも写す
        if (renameTxd)
        {
            var relations = doc.Descendants("txdRelationships").Elements("Item")
                .Where(r => Same((string)r.Element("child"), baseTxd))
                .Select(r => new XElement("Item",
                    new XElement("parent", ((string)r.Element("parent")).Trim()),
                    new XElement("child", newModel)))
                .ToList();
            if (relations.Count > 0) root.Add(new XElement("txdRelationships", relations));
        }

        result.VehiclesMeta = Serialize(root);

        // --- carvariations.meta ---
        var variationsPath = FindVanillaFile(vanillaPath, "carvariations.meta", "carvariations.ymt.xml");
        if (variationsPath == null)
        {
            result.Warnings.Add(Lang.T("バニラの carvariations が無いため、色とリバリーの設定は作っていません。", "There is no vanilla carvariations, so colour and livery settings were not created."));
            return result;
        }

        var variation = XDocument.Load(variationsPath).Descendants("variationData").Elements("Item")
            .FirstOrDefault(i => Same((string)i.Element("modelName"), baseModel));
        if (variation == null)
        {
            result.Warnings.Add(Lang.T($"バニラの carvariations に {baseModel} が無いため、色とリバリーの設定は作っていません。", $"The vanilla carvariations has no {baseModel}, so colour and livery settings were not created."));
            return result;
        }

        var models = doc.Descendants("InitDatas").Elements("Item")
            .Select(i => ((string)i.Element("modelName") ?? "").Trim().ToLowerInvariant())
            .Where(n => n.Length > 0).Distinct().ToList();

        var converted = ConvertVariation(variation, newModel, models, result.Warnings);
        result.CarVariations = Serialize(
            new XElement("CVehicleModelInfoVariation", new XElement("variationData", converted)));

        return result;
    }

    // ------------------------------------------------------------------
    // carvariations: ゲーム内の形式（.ymt を XML に起こしたもの）→ .meta の書式
    // ------------------------------------------------------------------

    private static XElement ConvertVariation(XElement source, string newModel, List<string> models, List<string> warnings)
    {
        // 元から .meta の書式なら名前だけ変える
        if (source.Descendants("indices").Any(i => i.Attribute("content") != null))
        {
            var copy = new XElement(source);
            copy.SetElementValue("modelName", newModel);
            return copy;
        }

        var item = new XElement("Item", new XElement("modelName", newModel));

        var colors = new XElement("colors");
        foreach (var c in source.Element("colors")?.Elements("Item") ?? Enumerable.Empty<XElement>())
        {
            var indices = Numbers((string)c.Element("indices"));
            var liveries = Numbers((string)c.Element("liveries"));

            // リバリーの枠は古いゲームビルドでは 8 個。使っている所までを書く（最低 8）
            var count = Math.Max(8, liveries.FindLastIndex(v => v != "0") + 1);

            colors.Add(new XElement("Item",
                new XElement("indices", new XAttribute("content", "char_array"),
                    "\n" + string.Join("\n", indices) + "\n"),
                new XElement("liveries", Enumerable.Range(0, count).Select(i =>
                    new XElement("Item", new XAttribute("value",
                        i < liveries.Count && liveries[i] != "0" ? "true" : "false"))))));
        }
        item.Add(colors);

        var kits = new XElement("kits");
        foreach (var k in source.Element("kits")?.Elements("Item") ?? Enumerable.Empty<XElement>())
        {
            var name = ResolveKit(k.Value.Trim(), models);
            if (name == null)
            {
                warnings.Add(Lang.T($"改造キットの名前を復元できませんでした（{k.Value.Trim()}）。既定のキットを当てています。", $"The mod kit name could not be recovered ({k.Value.Trim()}). The default kit is used."));
                name = "0_default_modkit";
            }
            if (kits.Elements("Item").All(e => e.Value != name)) kits.Add(new XElement("Item", name));
        }
        if (!kits.HasElements) kits.Add(new XElement("Item", "0_default_modkit"));
        item.Add(kits);

        item.Add(new XElement("windowsWithExposedEdges"));

        var plates = new XElement("Probabilities");
        foreach (var p in source.Descendants("Probabilities").Elements("Item"))
        {
            var name = ResolvePlate(((string)p.Element("Name") ?? "").Trim());
            var value = (string)p.Element("Value")?.Attribute("value");
            if (name == null || value == null) continue;
            plates.Add(new XElement("Item",
                new XElement("Name", name),
                new XElement("Value", new XAttribute("value", value))));
        }
        item.Add(new XElement("plateProbabilities", plates));

        item.Add(new XElement("lightSettings", new XAttribute("value",
            (string)source.Element("lightSettings")?.Attribute("value") ?? "0")));
        item.Add(new XElement("sirenSettings", new XAttribute("value",
            (string)source.Element("sirenSettings")?.Attribute("value") ?? "0")));

        return item;
    }

    private static List<string> Numbers(string text) =>
        (text ?? "").Split((char[])null, StringSplitOptions.RemoveEmptyEntries).ToList();

    //[ ハッシュになっている名前の復元 ]
    // ゲーム内の形式では名前がハッシュで入っているが、.meta は名前で書く必要がある。
    // 改造キットは "<番号>_<車名>_modkit" の形なので、総当たりで元の名前を探せる。

    private static readonly string[] PlateNames =
    {
        "Standard White", "White Plate 2", "Blue Plate", "Yellow Plate", "Yankton Plate",
    };

    private static Dictionary<uint, string> _kitNames;

    private static string ResolveKit(string value, List<string> models)
    {
        if (!TryParseHash(value, out var hash)) return value;   // 既に名前
        if (hash == Joaat("0_default_modkit")) return "0_default_modkit";

        if (_kitNames == null)
        {
            _kitNames = new Dictionary<uint, string>();
            foreach (var model in models)
                for (var id = 0; id < 1024; id++)
                {
                    var name = $"{id}_{model}_modkit";
                    _kitNames.TryAdd(Joaat(name), name);
                }
        }

        return _kitNames.GetValueOrDefault(hash);
    }

    private static string ResolvePlate(string value)
    {
        if (!TryParseHash(value, out var hash)) return value.Length > 0 ? value : null;
        return PlateNames.FirstOrDefault(n => Joaat(n) == hash);
    }

    private static bool TryParseHash(string value, out uint hash)
    {
        hash = 0;
        return value.StartsWith("hash_", StringComparison.OrdinalIgnoreCase)
            && uint.TryParse(value[5..], System.Globalization.NumberStyles.HexNumber, null, out hash);
    }

    /// <summary>GTA の名前ハッシュ（小文字化してから Jenkins one-at-a-time）。</summary>
    public static uint Joaat(string text)
    {
        uint h = 0;
        foreach (var b in Encoding.UTF8.GetBytes(text.ToLowerInvariant()))
        {
            h += b;
            h += h << 10;
            h ^= h >> 6;
        }
        h += h << 3;
        h ^= h >> 11;
        h += h << 15;
        return h;
    }

    private static bool Same(string a, string b) =>
        string.Equals(a?.Trim(), b?.Trim(), StringComparison.OrdinalIgnoreCase);

    private static byte[] Serialize(XElement root)
    {
        using var ms = new MemoryStream();
        var settings = new XmlWriterSettings
        {
            Indent = true,
            Encoding = new UTF8Encoding(encoderShouldEmitUTF8Identifier: false),
        };
        using (var writer = XmlWriter.Create(ms, settings))
            new XDocument(new XDeclaration("1.0", "UTF-8", null), root).Save(writer);
        return ms.ToArray();
    }
}

