  }),
)
const ROLES = list(process.env.ALLOWED_ROLES)

if (!DISCORD_TOKEN || !FIVEDOCK_TOKEN || !CHANNELS.size) {
  console.error('DISCORD_TOKEN, FIVEDOCK_TOKEN and CHANNELS have to be set. Copy .env.example to .env and fill it in.')
  process.exit(1)
}

async function upload(attachment, folder) {
  const download = await fetch(attachment.url)
  if (!download.ok) throw new Error(`Discord didn't hand over the attachment (${download.status}).`)

  const form = new FormData()
  form.append('file', await download.blob(), attachment.name)

  const url = new URL('/v1/upload', API_URL)
  url.searchParams.set('folder', folder)
  if (FIVEDOCK_SERVER_ID) url.searchParams.set('serverId', FIVEDOCK_SERVER_ID)

  const res = await fetch(url, {
    method: 'POST',
    headers: { Authorization: `Bearer ${FIVEDOCK_TOKEN}` },
    body: form,
  })
  const body = await res.json().catch(() => ({}))
  if (!res.ok) throw new Error(body.detail || body.title || `FiveDock answered with ${res.status}.`)
  return body
}

async function handle(message) {
  const folder = CHANNELS.get(message.channelId)
  if (!folder || message.author.bot || !message.attachments.size) return

  if (ROLES.length && !message.member?.roles.cache.hasAny(...ROLES)) {
    await message.react('⛔')
    return
  }

  const lines = []
  for (const attachment of message.attachments.values()) {
    try {
      const file = await upload(attachment, folder)
      lines.push(`**${file.name}** → ${file.url}`)
    } catch (err) {
      console.error(err)
      lines.push(`**${attachment.name}** didn't upload: ${err.message}`)
    }
  }
  await message.reply({ content: lines.join('\n'), allowedMentions: { repliedUser: false } })
}

const client = new Client({
  intents: [GatewayIntentBits.Guilds, GatewayIntentBits.GuildMessages, GatewayIntentBits.MessageContent],
})

client.once('clientReady', () => {
  const watched = [...CHANNELS].map(([id, folder]) => `${id} → ${folder}`).join(', ')
  console.log(`Logged in as ${client.user.tag}, watching ${watched}`)
})

client.on('messageCreate', (message) => handle(message).catch(console.error))

client.login(DISCORD_TOKEN)

