using SharpCompress.Archives;

namespace KnExchange;

/// <summary>
/// 入力（フォルダ / 書庫 / rpf 単体）を「ファイルが並んだフォルダ」として扱えるようにする。
///
/// 書庫は丸ごと展開しない。配布物には手順書や画像が多く含まれ、変換に要るのは
/// rpf・ストリーミングアセット・meta だけであるため。
/// ディレクトリ構造は Legacy / Enhanced の判別に使うので保持する。
/// </summary>
public sealed class InputUnpacker : IDisposable
{
    /// <summary>書庫の中の書庫を辿る深さ。.oiv や「zip の中に zip」を拾うため。</summary>
    private const int MaxArchiveDepth = 2;

    public string RootPath { get; }

    private readonly bool _isTemp;

    private InputUnpacker(string rootPath, bool isTemp)
    {
        RootPath = rootPath;
        _isTemp = isTemp;
    }

    public static InputUnpacker Open(string path, Action<string> log)
    {
        if (Directory.Exists(path))
            return new InputUnpacker(Path.GetFullPath(path), isTemp: false);

        if (!File.Exists(path))
            throw new FileNotFoundException(Lang.T($"入力が見つかりません: {path}", $"The input was not found: {path}"), path);

        var temp = Path.Combine(Path.GetTempPath(), "kn_exchange", Path.GetRandomFileName());
        Directory.CreateDirectory(temp);
        var unpacker = new InputUnpacker(temp, isTemp: true);

        try
        {
            if (ModFormats.IsRpf(path) || Path.GetExtension(path).Equals(".xml", StringComparison.OrdinalIgnoreCase))
                File.Copy(path, Path.Combine(temp, Path.GetFileName(path).ToLowerInvariant()));
            else
                Extract(path, temp, 0, log);

            return unpacker;
        }
        catch
        {
            unpacker.Dispose();
            throw;
        }
    }

    private static void Extract(string archivePath, string destRoot, int depth, Action<string> log)
    {
        using var archive = ArchiveFactory.Open(archivePath);
        log(Lang.T($"書庫を展開: {Path.GetFileName(archivePath)}  ({archive.Type})", $"Extracting archive: {Path.GetFileName(archivePath)}  ({archive.Type})"));

        var nested = new List<string>();
        var count = 0;

        foreach (var entry in archive.Entries)
        {
            if (entry.IsDirectory || entry.Key == null) continue;

            // 作者が FiveM 用を同梱していることがある。変換するより、そちらを使う方が確実
            if (Path.GetFileName(entry.Key).ToLowerInvariant() is "fxmanifest.lua" or "__resource.lua")
                log(Lang.T($"  [参考] 作者が用意した FiveM 用リソースが入っています: {Path.GetDirectoryName(entry.Key.Replace('\\', '/'))}", $"  [info] The author already ships a FiveM resource in here: {Path.GetDirectoryName(entry.Key.Replace('\\', '/'))}"));

            if (!ModFormats.IsRelevant(entry.Key)) continue;

            var relative = SafeRelativePath(entry.Key);
            if (relative == null)
            {
                log(Lang.T($"  [警告] 不正なパスを無視しました: {entry.Key}", $"  [warning] Ignored an unsafe path: {entry.Key}"));
                continue;
            }

            var dest = Path.Combine(destRoot, relative);
            Directory.CreateDirectory(Path.GetDirectoryName(dest));

            using (var src = entry.OpenEntryStream())
            using (var dst = File.Create(dest))
                src.CopyTo(dst);

            count++;
            if (ModFormats.IsArchive(dest)) nested.Add(dest);
        }

        log(Lang.T($"  {count} 件を取り出しました", $"  extracted {count} file(s)"));

        foreach (var inner in nested)
        {
            if (depth + 1 >= MaxArchiveDepth)
            {
                log(Lang.T($"  [警告] 入れ子が深い書庫は展開しません: {Path.GetFileName(inner)}", $"  [warning] Archives nested this deep are not extracted: {Path.GetFileName(inner)}"));
                continue;
            }

            // 書庫名のフォルダへ展開する（中身同士の名前衝突を避ける）
            var innerDest = inner + ".d";
            Directory.CreateDirectory(innerDest);
            try
            {
                Extract(inner, innerDest, depth + 1, log);
            }
            catch (Exception ex)
            {
                log(Lang.T($"  [警告] 入れ子の書庫を開けませんでした: {Path.GetFileName(inner)} ({ex.Message})", $"  [warning] A nested archive could not be opened: {Path.GetFileName(inner)} ({ex.Message})"));
            }
        }
    }

    /// <summary>
    /// 書庫内のパスを展開先の相対パスへ変換する。
    /// 絶対パスや ".." による書庫外への書き出し（zip slip）は拒否する。
    /// </summary>
    private static string SafeRelativePath(string key)
    {
        var normalized = key.Replace('\\', '/');

        var parts = normalized.Split('/', StringSplitOptions.RemoveEmptyEntries)
            .Where(p => p != ".")
            .ToArray();

        if (parts.Length == 0) return null;
        if (parts.Any(p => p == "..")) return null;
        if (Path.IsPathRooted(normalized) || normalized.Contains(':')) return null;

        // 末尾の空白とピリオドは Windows で作れないので落とす
        for (var i = 0; i < parts.Length; i++)
        {
            parts[i] = parts[i].TrimEnd(' ', '.');
            if (parts[i].Length == 0) return null;
        }

        parts[^1] = parts[^1].ToLowerInvariant();
        return Path.Combine(parts);
    }

    public void Dispose()
    {
        if (!_isTemp || !Directory.Exists(RootPath)) return;

        try { Directory.Delete(RootPath, recursive: true); }
        catch { /* 一時フォルダの削除失敗は無視する */ }
    }
}

