using System.Globalization;
using System.Text;
using System.Xml;
using System.Xml.Linq;

namespace KnExchange;

/// <summary>
/// Menyoo の保存ファイル（Object Spooner の .xml）を、同じ配置を置き直す FiveM リソースにする。
///
/// 書式は Menyoo 本体の保存・読み込み処理（MAFINS/MenyooSP の Spooner/FileManagement.cpp）に合わせている。
/// ファイルが持つのは「どのモデルをどこへ置くか」だけで、モデルそのものは含まない。
/// 今の対象は物（Type 3）の配置。種類の番号はゲームの実体の種類と同じ（1=ped 2=車 3=物）。
/// 動かない物へ取り付けられた物は、保存されているワールド座標へ固定して置く。
/// 車・ped・動く相手への取り付け・マーカーは数えて知らせるだけ。
/// </summary>
public static class MenyooBuilder
{
    public const string RootName = "SpoonerPlacements";

    [Flags]
    public enum PropFlags { None = 0, Frozen = 1, Dynamic = 2, Invisible = 4, NoCollision = 8 }

    public sealed class Prop
    {
        public int Hash;
        public string HashName;
        public double X, Y, Z, Pitch, Roll, Yaw;
        public PropFlags Flags;
        public int Alpha = 255;
        public int LodDistance;
    }

    public sealed class Result
    {
        public List<Prop> Props { get; } = new();
        public int Vehicles, Peds, Attached, AttachedPlaced, Markers, TextureVariations, Unreadable;
        public bool ChangesWorld;
        /// <summary>途中で壊れていて読めなかったファイル。</summary>
        public List<string> Broken { get; } = new();
        public (double X, double Y, double Z)? Reference;
    }

    /// <summary>外部実体や DTD は読まない（書庫の中身は信頼できない）。</summary>
    private static XDocument Load(string path)
    {
        var settings = new XmlReaderSettings { DtdProcessing = DtdProcessing.Prohibit, XmlResolver = null };
        using var reader = XmlReader.Create(path, settings);
        return XDocument.Load(reader);
    }

    /// <summary>フォルダの中から Menyoo の保存ファイルを探す。壊れた xml や他の用途の xml は対象外。</summary>
    public static List<string> Find(string root)
    {
        var found = new List<string>();
        foreach (var path in Directory.EnumerateFiles(root, "*.xml", SearchOption.AllDirectories)
                     .OrderBy(p => p, StringComparer.OrdinalIgnoreCase))
        {
            try
            {
                var settings = new XmlReaderSettings { DtdProcessing = DtdProcessing.Prohibit, XmlResolver = null };
                using var reader = XmlReader.Create(path, settings);
                if (reader.MoveToContent() == XmlNodeType.Element
                    && (reader.Name == RootName || MenyooVehicleBuilder.LooksLikeSavedVehicle(reader))) found.Add(path);
            }
            catch (Exception ex) when (ex is XmlException or IOException) { }
        }
        return found;
    }

    public static Result Parse(IEnumerable<string> paths)
    {
        var result = new Result();
        foreach (var path in paths)
        {
            XElement rootNode;
            try { rootNode = Load(path).Root; }
            catch (XmlException)
            {
                result.Broken.Add(Path.GetFileName(path));
                continue;
            }
            if (rootNode == null || rootNode.Name.LocalName != RootName) continue;

            result.Markers += rootNode.Elements("Marker").Count();
            if (rootNode.Element("IPLsToLoad")?.Elements("IPL").Any() == true
                || rootNode.Element("IPLsToRemove")?.Elements("IPL").Any() == true
                || rootNode.Element("InteriorsToEnable")?.HasElements == true
                || rootNode.Element("InteriorsToCap")?.HasElements == true)
                result.ChangesWorld = true;

            var reference = rootNode.Element("ReferenceCoords");
            if (result.Reference == null && reference != null
                && Num(reference, "X", out var rx) && Num(reference, "Y", out var ry) && Num(reference, "Z", out var rz))
                result.Reference = (rx, ry, rz);

            // 取り付け先は InitialHandle で指される。動かない物（固定、または物理なし）へ辿り着く取り付けだけ置ける。
            var nodes = rootNode.Elements("Placement").ToList();
            var byHandle = new Dictionary<string, XElement>();
            foreach (var node in nodes)
            {
                var handle = node.Element("InitialHandle")?.Value?.Trim();
                if (!string.IsNullOrEmpty(handle)) byHandle.TryAdd(handle, node);
            }
            static bool IsAttached(XElement n) => Bool(n.Element("Attachment")?.Attribute("isAttached")?.Value);
            bool Anchored(XElement n, int depth)
            {
                if ((int)Int(n.Element("Type")?.Value, 0) != 3 || depth > 32) return false;
                if (!IsAttached(n)) return Bool(n.Element("FrozenPos")?.Value) || !Bool(n.Element("Dynamic")?.Value);
                var to = n.Element("Attachment")?.Element("AttachedTo")?.Value?.Trim();
                return !string.IsNullOrEmpty(to) && byHandle.TryGetValue(to, out var parent)
                    && !ReferenceEquals(parent, n) && Anchored(parent, depth + 1);
            }

            foreach (var node in nodes)
            {
                var type = (int)Int(node.Element("Type")?.Value, 0);
                if (type == 1) { result.Peds++; continue; }
                if (type == 2) { result.Vehicles++; continue; }
                if (type != 3) { result.Unreadable++; continue; }

                var attached = IsAttached(node);
                if (attached && !Anchored(node, 0)) { result.Attached++; continue; }

                var pos = node.Element("PositionRotation");
                if (!TryHash(node.Element("ModelHash")?.Value, out var hash) || pos == null
                    || !Num(pos, "X", out var x) || !Num(pos, "Y", out var y) || !Num(pos, "Z", out var z))
                {
                    result.Unreadable++;
                    continue;
                }
                Num(pos, "Pitch", out var pitch);
                Num(pos, "Roll", out var roll);
                Num(pos, "Yaw", out var yaw);

                var flags = PropFlags.None;
                if (Bool(node.Element("FrozenPos")?.Value)) flags |= PropFlags.Frozen;
                if (Bool(node.Element("Dynamic")?.Value)) flags |= PropFlags.Dynamic;
                if (attached) { flags = (flags | PropFlags.Frozen) & ~PropFlags.Dynamic; result.AttachedPlaced++; }
                if (node.Element("IsVisible") != null && !Bool(node.Element("IsVisible").Value)) flags |= PropFlags.Invisible;
                if (Bool(node.Element("IsCollisionProof")?.Value)) flags |= PropFlags.NoCollision;

                if (Int(node.Element("ObjectProperties")?.Element("TextureVariation")?.Value, 0) != 0)
                    result.TextureVariations++;

                result.Props.Add(new Prop
                {
                    Hash = hash,
                    HashName = node.Element("HashName")?.Value?.Trim() ?? "",
                    X = x, Y = y, Z = z, Pitch = pitch, Roll = roll, Yaw = yaw,
                    Flags = flags,
                    Alpha = (int)Math.Clamp(Int(node.Element("OpacityLevel")?.Value, 255), 0, 255),
                    LodDistance = (int)Math.Clamp(Int(node.Element("LodDistance")?.Value, 0), 0, 0xFFFF),
                });
            }
        }
        return result;
    }

    /// <summary>ModelHash は "0x" 付きの 16 進で保存される。手で直したファイルの 10 進（負の値を含む）も受ける。</summary>
    public static bool TryHash(string text, out int hash)
    {
        hash = 0;
        text = text?.Trim();
        if (string.IsNullOrEmpty(text)) return false;

        if (text.StartsWith("0x", StringComparison.OrdinalIgnoreCase))
        {
            if (!uint.TryParse(text[2..], NumberStyles.HexNumber, CultureInfo.InvariantCulture, out var hex)) return false;
            hash = unchecked((int)hex);
            return hash != 0;
        }
        if (!long.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out var value)
            || value < int.MinValue || value > uint.MaxValue) return false;
        hash = unchecked((int)value);
        return hash != 0;
    }

    private static bool Num(XElement parent, string name, out double value)
    {
        value = 0;
        return double.TryParse(parent.Element(name)?.Value, NumberStyles.Float, CultureInfo.InvariantCulture, out value)
            && double.IsFinite(value);
    }

    private static long Int(string text, long fallback) =>
        long.TryParse(text?.Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out var v) ? v : fallback;

    private static bool Bool(string text) =>
        text != null && (text.Trim().Equals("true", StringComparison.OrdinalIgnoreCase) || text.Trim() == "1");

    /// <summary>Lua が必ず小数として読む形にする（整数と小数は別の型で、小数を求めるネイティブに整数は渡せない）。</summary>
    private static string F(double v) => v.ToString("0.0#####", CultureInfo.InvariantCulture);

    /// <summary>配置の表。1 行 1 個で { モデル, x, y, z, pitch, roll, yaw, 属性, 不透明度, 描画距離 }。</summary>
    public static string BuildPlacements(Result result)
    {
        var sb = new StringBuilder();
        sb.Append(Lang.T("-- kn_exchange が Menyoo の保存ファイルから作成\n", "-- Generated by kn_exchange from Menyoo save files\n"));
        sb.Append("-- { model, x, y, z, pitch, roll, yaw, flags, alpha, lodDistance }\n");
        sb.Append(Lang.T("-- flags: 1=固定 2=物理あり 4=非表示 8=当たり判定なし\n", "-- flags: 1=frozen 2=dynamic 4=invisible 8=no collision\n"));
        sb.Append("Placements = {\n");
        foreach (var p in result.Props)
        {
            sb.Append(CultureInfo.InvariantCulture,
                $"    {{ {p.Hash}, {F(p.X)}, {F(p.Y)}, {F(p.Z)}, {F(p.Pitch)}, {F(p.Roll)}, {F(p.Yaw)}, {(int)p.Flags}, {p.Alpha}, {p.LodDistance} }},");
            if (p.HashName.Length > 0 && !p.HashName.Contains('\n') && !p.HashName.Contains('\r'))
                sb.Append(" -- ").Append(p.HashName);
            sb.Append('\n');
        }
        sb.Append("}\n");
        return sb.ToString();
    }

    public const string Config = """
        Config = {}

        -- この距離（m）まで近づいた物を置く
        Config.SpawnDistance = 300.0

        -- この距離（m）より離れた物を消す。SpawnDistance より大きくすること
        Config.DespawnDistance = 350.0

        -- 配置を見直す間隔（ミリ秒）
        Config.Interval = 1000

        -- ゲームに無いモデルを F8 コンソールへ知らせる
        Config.ReportMissing = true

        """;

    public const string Client = """
        -- kn_exchange が作成。Menyoo で保存した配置を、近づいた分だけ置く。
        -- 物は自分の画面にだけ置く（サーバーとは同期しない）ので、参加している全員が同じ配置を見る。

        local CELL = 100.0
        local cells = {}       -- "cx:cy" → 配置番号の並び
        local spawned = {}     -- 配置番号 → 置いた物
        local missing = {}     -- ゲームに無かったモデル

        local function cellKey(cx, cy) return cx .. ':' .. cy end

        for i = 1, #Placements do
            local p = Placements[i]
            local key = cellKey(math.floor(p[2] / CELL), math.floor(p[3] / CELL))
            local list = cells[key]
            if not list then list = {}; cells[key] = list end
            list[#list + 1] = i
        end

        local function loadModel(model)
            if missing[model] then return false end
            if not IsModelInCdimage(model) then
                missing[model] = true
                if Config.ReportMissing then
                    print(('[%s] ゲームに無いモデルです（この分は表示されません）: %s'):format(GetCurrentResourceName(), model))
                end
                return false
            end
            RequestModel(model)
            local deadline = GetGameTimer() + 5000
            while not HasModelLoaded(model) do
                if GetGameTimer() > deadline then return false end
                Wait(0)
            end
            return true
        end

        local function spawn(i)
            local p = Placements[i]
            local model, flags = p[1], p[8]
            if not loadModel(model) then return end

            local obj = CreateObjectNoOffset(model, p[2], p[3], p[4], false, false, (flags & 2) ~= 0)
            SetModelAsNoLongerNeeded(model)
            if obj == 0 then return end

            SetEntityRotation(obj, p[5], p[6], p[7], 2, true)
            FreezeEntityPosition(obj, (flags & 1) ~= 0)
            if (flags & 4) ~= 0 then SetEntityVisible(obj, false, false) end
            if (flags & 8) ~= 0 then SetEntityCollision(obj, false, false) end
            if p[9] < 255 then SetEntityAlpha(obj, p[9], false) end
            if p[10] > 0 then SetEntityLodDist(obj, p[10]) end
            spawned[i] = obj
        end

        local function despawn(i)
            local obj = spawned[i]
            spawned[i] = nil
            if obj and DoesEntityExist(obj) then DeleteEntity(obj) end
        end

        CreateThread(function()
            local near = Config.SpawnDistance
            local far = math.max(Config.DespawnDistance, near + 10.0)
            local reach = math.ceil(near / CELL)

            while true do
                local ok, err = pcall(function()
                    local pos = GetEntityCoords(PlayerPedId())

                    for i in pairs(spawned) do
                        local p = Placements[i]
                        if #(pos - vector3(p[2], p[3], p[4])) > far then despawn(i) end
                    end

                    local cx, cy = math.floor(pos.x / CELL), math.floor(pos.y / CELL)
                    for x = cx - reach, cx + reach do
                        for y = cy - reach, cy + reach do
                            local list = cells[cellKey(x, y)]
                            if list then
                                for n = 1, #list do
                                    local i = list[n]
                                    if not spawned[i] then
                                        local p = Placements[i]
                                        if #(pos - vector3(p[2], p[3], p[4])) <= near then spawn(i) end
                                    end
                                end
                            end
                        end
                    end
                end)
                if not ok then print(('[%s] %s'):format(GetCurrentResourceName(), err)) end
                Wait(Config.Interval)
            end
        end)

        AddEventHandler('onResourceStop', function(resource)
            if resource ~= GetCurrentResourceName() then return end
            for i in pairs(spawned) do despawn(i) end
        end)

        """;

    /// <summary>配置と保存した車のうち、ある方だけを読み込む。保存した車はサーバー側のスクリプトも持つ。</summary>
    public static string BuildManifest(string version, bool placements = true, bool vehicles = false)
    {
        var client = new List<string>();
        if (placements) client.AddRange(new[] { "config.lua", "placements.lua", "client.lua" });
        if (vehicles) client.Add("vehicles_client.lua");

        var sb = new StringBuilder();
        sb.Append(Lang.T($"-- kn_exchange {version} で生成\n", $"-- Generated by kn_exchange {version}\n"));
        sb.Append("fx_version 'cerulean'\ngame 'gta5'\nlua54 'yes'\n\n");
        if (vehicles) sb.Append("shared_scripts {\n    'vehicles_config.lua',\n    'vehicles.lua',\n}\n\n");
        sb.Append("client_scripts {\n").Append(string.Concat(client.Select(f => $"    '{f}',\n"))).Append("}\n");
        if (vehicles) sb.Append("\nserver_scripts {\n    'vehicles_server.lua',\n}\n");
        return sb.ToString();
    }
}

