namespace KnExchange;

/// <summary>
/// Menyoo の「保存した車」（ルートが Vehicle の .xml）を、コマンドで呼び出せる車にする。
///
/// 配置（SpoonerPlacements）と違って場所を持たず、1 台分の色・改造と、車へ取り付けた物の並びを持つ。
/// 読み方は Menyoo 本体（MAFINS/MenyooSP の Spooner/FileManagement.cpp）に合わせている。
/// 反映しないもの: 性能の倍率・無敵などの耐性・ドアやタイヤの状態・取り付けられた ped と車。
/// </summary>
public static class MenyooVehicleBuilder
{
    public const string RootName = "Vehicle";

    public sealed class Attachment
    {
        public int Hash, Bone, Alpha = 255;
        public string HashName = "";
        public double X, Y, Z, Pitch, Roll, Yaw;
        public bool Collision;
    }

    public sealed class Effect
    {
        public string Asset, Name;
        public double X, Y, Z;
    }

    public sealed class Car
    {
        public string Key, Label;
        public int Hash;
        public int Primary, Secondary, Pearl, Rim, Interior, Dashboard, Xenon = 255;
        public int Mod1A, Mod1B, Mod1C, Mod2A, Mod2B;
        public (int R, int G, int B)? Custom1, Custom2, TyreSmoke;
        public int Livery = -1, PlateIndex, WheelType, WindowTint;
        public string Plate = "";
        public bool BulletProofTyres;
        public double Dirt, PaintFade;
        public bool[] Neons = new bool[4];
        public (int R, int G, int B) NeonColour;
        public SortedDictionary<int, bool> Extras { get; } = new();
        public SortedDictionary<int, (int Index, int Variation)> Mods { get; } = new();
        public SortedDictionary<int, bool> Toggles { get; } = new();
        public List<Attachment> Attachments { get; } = new();
        public List<Effect> Effects { get; } = new();
    }

    public sealed class Result
    {
        public List<Car> Cars { get; } = new();
        public List<string> Broken { get; } = new();
        public int Unreadable, SkippedPeds, SkippedVehicles, SkippedNested, HiddenCarriers, Tuned, Protected, Burning;
    }

    /// <summary>ルートが Vehicle で、最初の子が ModelHash のものだけを Menyoo の保存した車とみなす。</summary>
    public static bool LooksLikeSavedVehicle(XmlReader reader)
    {
        if (reader.Name != RootName) return false;
        while (reader.Read())
            if (reader.NodeType == XmlNodeType.Element) return reader.Name == "ModelHash";
        return false;
    }

    public static Result Parse(IEnumerable<string> paths)
    {
        var result = new Result();
        var used = new HashSet<string>(StringComparer.Ordinal);

        foreach (var path in paths)
        {
            XElement root;
            try
            {
                var settings = new XmlReaderSettings { DtdProcessing = DtdProcessing.Prohibit, XmlResolver = null };
                using var reader = XmlReader.Create(path, settings);
                root = XDocument.Load(reader).Root;
            }
            catch (XmlException)
            {
                result.Broken.Add(Path.GetFileName(path));
                continue;
            }
            if (root == null || root.Name.LocalName != RootName) continue;
            if (!MenyooBuilder.TryHash(root.Element("ModelHash")?.Value, out var hash)) { result.Unreadable++; continue; }

            var label = Path.GetFileNameWithoutExtension(path).Trim();
            var key = Slug(label);
            for (var n = 2; !used.Add(key); n++) key = Slug(label) + "_" + n.ToString(CultureInfo.InvariantCulture);

            var car = new Car { Key = key, Label = label, Hash = hash };
            var props = root.Element("VehicleProperties");
            var colours = props?.Element("Colours");
            if (colours != null)
            {
                car.Primary = I(colours, "Primary");
                car.Secondary = I(colours, "Secondary");
                car.Pearl = I(colours, "Pearl");
                car.Rim = I(colours, "Rim");
                car.Mod1A = I(colours, "Mod1_a"); car.Mod1B = I(colours, "Mod1_b"); car.Mod1C = I(colours, "Mod1_c");
                car.Mod2A = I(colours, "Mod2_a"); car.Mod2B = I(colours, "Mod2_b");
                if (B(colours, "IsPrimaryColourCustom")) car.Custom1 = Rgb(colours, "Cust1_R", "Cust1_G", "Cust1_B");
                if (B(colours, "IsSecondaryColourCustom")) car.Custom2 = Rgb(colours, "Cust2_R", "Cust2_G", "Cust2_B");
                if (colours.Element("tyreSmoke_R") != null) car.TyreSmoke = Rgb(colours, "tyreSmoke_R", "tyreSmoke_G", "tyreSmoke_B");
                car.Interior = I(colours, "LrInterior");
                car.Dashboard = I(colours, "LrDashboard");
                car.Xenon = I(colours, "LrXenonHeadlights", 255);
            }
            if (props != null)
            {
                car.Livery = I(props, "Livery", -1);
                // ナンバーは 8 文字まで。前後の空白は中央寄せの意味を持つので残す
                var plate = new string((props.Element("NumberPlateText")?.Value ?? "").Where(c => c >= 0x20 && c < 0x7F).ToArray());
                car.Plate = plate.Length > 8 ? plate[..8] : plate;
                car.PlateIndex = I(props, "NumberPlateIndex");
                car.WheelType = I(props, "WheelType");
                car.WindowTint = I(props, "WindowTint");
                car.BulletProofTyres = B(props, "BulletProofTyres");
                car.Dirt = Math.Clamp(D(props, "DirtLevel"), 0, 15);
                car.PaintFade = Math.Clamp(D(props, "PaintFade"), 0, 1);

                var neons = props.Element("Neons");
                if (neons != null)
                {
                    car.Neons = new[] { B(neons, "Left"), B(neons, "Right"), B(neons, "Front"), B(neons, "Back") };
                    car.NeonColour = Rgb(neons, "R", "G", "B");
                }
                foreach (var extra in props.Element("ModExtras")?.Elements() ?? Enumerable.Empty<XElement>())
                    if (Index(extra, 0, 20, out var id)) car.Extras[id] = Flag(extra.Value);

                // 値に "," があれば「番号,派生」、無ければ ON/OFF（Menyoo の読み込みと同じ見分け方）
                foreach (var mod in props.Element("Mods")?.Elements() ?? Enumerable.Empty<XElement>())
                {
                    if (!Index(mod, 0, 60, out var type)) continue;
                    var value = mod.Value.Trim();
                    var comma = value.IndexOf(',');
                    if (comma < 0) { car.Toggles[type] = Flag(value); continue; }
                    if (int.TryParse(value[..comma], NumberStyles.Integer, CultureInfo.InvariantCulture, out var index) && index >= 0 && index < 1000)
                    {
                        int.TryParse(value[(comma + 1)..], NumberStyles.Integer, CultureInfo.InvariantCulture, out var variation);
                        car.Mods[type] = (index, variation);
                    }
                }

                if (props.Element("RpmMultiplier") != null || props.Element("TorqueMultiplier") != null || props.Element("MaxSpeed") != null)
                    result.Tuned++;
            }
            if (B(root, "IsInvincible") || B(root, "IsBulletProof") || B(root, "IsExplosionProof") || B(root, "IsFireProof") || B(root, "IsMeleeProof"))
                result.Protected++;

            var selfHandle = root.Element("InitialHandle")?.Value?.Trim();
            foreach (var node in root.Element("SpoonerAttachments")?.Elements("Attachment") ?? Enumerable.Empty<XElement>())
            {
                var type = I(node, "Type");
                if (type == 1) { result.SkippedPeds++; continue; }
                if (type == 2) { result.SkippedVehicles++; continue; }
                var link = node.Element("Attachment");
                if (type != 3 || link == null || !MenyooBuilder.TryHash(node.Element("ModelHash")?.Value, out var objHash))
                {
                    result.Unreadable++;
                    continue;
                }
                // 車そのものへ付いた物だけを扱う（物へ付いた物は、付け先の姿勢を辿る必要がある）
                if (!Flag(link.Attribute("isAttached")?.Value) || link.Element("AttachedTo")?.Value?.Trim() != selfHandle)
                {
                    result.SkippedNested++;
                    continue;
                }

                double x = D(link, "X"), y = D(link, "Y"), z = D(link, "Z");
                var asset = Token(node.Element("PtfxLopAsset")?.Value);
                var effect = Token(node.Element("PtfxLopEffect")?.Value);
                if (asset != null && effect != null) car.Effects.Add(new Effect { Asset = asset, Name = effect, X = x, Y = y, Z = z });
                if (B(node, "IsOnFire")) result.Burning++;

                var alpha = Math.Clamp(I(node, "OpacityLevel", 255), 0, 255);
                var visible = node.Element("IsVisible") == null || B(node, "IsVisible");
                // 見えない物は効果を出すための台。効果は車の上で直接出すので、物は置かない
                if (!visible || alpha == 0) { result.HiddenCarriers++; continue; }

                car.Attachments.Add(new Attachment
                {
                    Hash = objHash,
                    HashName = node.Element("HashName")?.Value?.Trim() ?? "",
                    Bone = Math.Clamp(I(link, "BoneIndex"), 0, 0xFFFF),
                    X = x, Y = y, Z = z,
                    Pitch = D(link, "Pitch"), Roll = D(link, "Roll"), Yaw = D(link, "Yaw"),
                    Alpha = alpha,
                    Collision = !B(node, "IsCollisionProof"),
                });
            }
            result.Cars.Add(car);
        }
        return result;
    }

    /// <summary>コマンドで打てる名前にする（英小文字・数字・_）。空になったら car。</summary>
    public static string Slug(string text)
    {
        var sb = new StringBuilder();
        foreach (var c in (text ?? "").Trim().ToLowerInvariant())
        {
            if (c is >= 'a' and <= 'z' or >= '0' and <= '9') sb.Append(c);
            else if (sb.Length > 0 && sb[^1] != '_') sb.Append('_');
        }
        var slug = sb.ToString().Trim('_');
        if (slug.Length > 32) slug = slug[..32].Trim('_');
        return slug.Length == 0 ? "car" : slug;
    }

    /// <summary>パーティクルの名前は英数字と _ だけを通す（Lua の文字列へそのまま入れるため）。</summary>
    private static string Token(string text)
    {
        text = text?.Trim();
        return !string.IsNullOrEmpty(text) && text.Length <= 64 && text.All(c => char.IsAsciiLetterOrDigit(c) || c == '_') ? text : null;
    }

    private static bool Flag(string text) =>
        text != null && (text.Trim().Equals("true", StringComparison.OrdinalIgnoreCase) || text.Trim() == "1");

    private static bool B(XElement parent, string name) => Flag(parent.Element(name)?.Value);

    private static int I(XElement parent, string name, int fallback = 0) =>
        int.TryParse(parent.Element(name)?.Value?.Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out var v) ? v : fallback;

    private static double D(XElement parent, string name) =>
        double.TryParse(parent.Element(name)?.Value, NumberStyles.Float, CultureInfo.InvariantCulture, out var v) && double.IsFinite(v) ? v : 0;

    private static (int, int, int) Rgb(XElement parent, string r, string g, string b) =>
        (Math.Clamp(I(parent, r), 0, 255), Math.Clamp(I(parent, g), 0, 255), Math.Clamp(I(parent, b), 0, 255));

    private static bool Index(XElement node, int min, int max, out int value)
    {
        value = 0;
        var name = node.Name.LocalName;
        return name.Length > 1 && name[0] == '_'
            && int.TryParse(name[1..], NumberStyles.None, CultureInfo.InvariantCulture, out value) && value >= min && value <= max;
    }

    private static string F(double v) => v.ToString("0.0#####", CultureInfo.InvariantCulture);
    private static string L(bool v) => v ? "true" : "false";
    private static string Rgb((int R, int G, int B) c) => $"{{ {c.R}, {c.G}, {c.B} }}";

    private static string Quote(string text)
    {
        var sb = new StringBuilder("'");
        foreach (var c in text)
        {
            if (c is '\\' or '\'') sb.Append('\\').Append(c);
            else if (c < 0x20 || c == 0x7F) sb.Append(' ');
            else sb.Append(c);
        }
        return sb.Append('\'').ToString();
    }

    public static string BuildVehicles(Result result)
    {
        var inv = CultureInfo.InvariantCulture;
        var sb = new StringBuilder();
        sb.Append(Lang.T("-- kn_exchange が Menyoo の保存した車から作成\n", "-- Generated by kn_exchange from Menyoo saved vehicles\n"));
        sb.Append("-- attachments: { model, bone, x, y, z, pitch, roll, yaw, alpha, collision }\n");
        sb.Append(Lang.T("-- effects: { asset, name, x, y, z }（車からの位置）\n", "-- effects: { asset, name, x, y, z } (offset from the vehicle)\n"));
        sb.Append("Vehicles = {\n");
        foreach (var c in result.Cars)
        {
            sb.Append(inv, $"    ['{c.Key}'] = {{\n");
            sb.Append(inv, $"        label = {Quote(c.Label)},\n");
            sb.Append(inv, $"        model = {c.Hash},\n");
            sb.Append(inv, $"        colours = {{ {c.Primary}, {c.Secondary}, {c.Pearl}, {c.Rim} }},\n");
            sb.Append(inv, $"        paint = {{ {c.Mod1A}, {c.Mod1B}, {c.Mod1C}, {c.Mod2A}, {c.Mod2B} }},\n");
            if (c.Custom1 is { } c1) sb.Append(inv, $"        custom1 = {Rgb(c1)},\n");
            if (c.Custom2 is { } c2) sb.Append(inv, $"        custom2 = {Rgb(c2)},\n");
            if (c.TyreSmoke is { } smoke) sb.Append(inv, $"        tyreSmoke = {Rgb(smoke)},\n");
            sb.Append(inv, $"        interior = {c.Interior}, dashboard = {c.Dashboard}, xenon = {c.Xenon},\n");
            sb.Append(inv, $"        livery = {c.Livery}, plate = {Quote(c.Plate)}, plateIndex = {c.PlateIndex},\n");
            sb.Append(inv, $"        wheelType = {c.WheelType}, windowTint = {c.WindowTint}, bulletProofTyres = {L(c.BulletProofTyres)},\n");
            sb.Append(inv, $"        dirt = {F(c.Dirt)}, paintFade = {F(c.PaintFade)},\n");
            sb.Append(inv, $"        neons = {{ {L(c.Neons[0])}, {L(c.Neons[1])}, {L(c.Neons[2])}, {L(c.Neons[3])} }}, neonColour = {Rgb(c.NeonColour)},\n");
            sb.Append("        extras = {").Append(string.Join(",", c.Extras.Select(e => $" [{e.Key}] = {L(e.Value)}"))).Append(" },\n");
            sb.Append("        mods = {").Append(string.Join(",", c.Mods.Select(m => $" [{m.Key}] = {{ {m.Value.Index}, {m.Value.Variation} }}"))).Append(" },\n");
            sb.Append("        toggles = {").Append(string.Join(",", c.Toggles.Select(t => $" [{t.Key}] = {L(t.Value)}"))).Append(" },\n");
            sb.Append("        attachments = {\n");
            foreach (var a in c.Attachments)
            {
                sb.Append(inv, $"            {{ {a.Hash}, {a.Bone}, {F(a.X)}, {F(a.Y)}, {F(a.Z)}, {F(a.Pitch)}, {F(a.Roll)}, {F(a.Yaw)}, {a.Alpha}, {L(a.Collision)} }},");
                if (a.HashName.Length > 0 && !a.HashName.Contains('\n') && !a.HashName.Contains('\r')) sb.Append(" -- ").Append(a.HashName);
                sb.Append('\n');
            }
            sb.Append("        },\n");
            sb.Append("        effects = {\n");
            foreach (var e in c.Effects)
                sb.Append(inv, $"            {{ '{e.Asset}', '{e.Name}', {F(e.X)}, {F(e.Y)}, {F(e.Z)} }},\n");
            sb.Append("        },\n");
            sb.Append("    },\n");
        }
        sb.Append("}\n");
        return sb.ToString();
    }

    public const string Config = """
        VehicleConfig = {}

        -- 車を呼び出すコマンド。名前を付けずに打つと一覧が出る（例: /kncar fire_bikes）
        -- 変換したリソースを 2 つ以上入れる場合は、リソースごとに別の名前にする
        VehicleConfig.Command = 'kncar'

        -- true: 権限（ACE の command.<コマンド名>）を持つ人だけが使える。false: 誰でも使える
        VehicleConfig.Restricted = true

        -- 次に呼び出せるまでの秒数
        VehicleConfig.Cooldown = 5

        -- 新しく呼び出すと、その人が前に出した車を消す
        VehicleConfig.OnePerPlayer = true

        -- 出した人がサーバーを抜けたら、その車を消す
        VehicleConfig.DeleteOnDrop = true

        -- 目の前のどれだけ先へ出すか（メートル）
        VehicleConfig.SpawnAhead = 5.0

        -- 車に付いたパーティクル（炎など）を出すか。周りの人の画面でも出る
        VehicleConfig.Effects = true
        VehicleConfig.EffectInterval = 400    -- 出し直す間隔（ミリ秒）
        VehicleConfig.EffectDistance = 120.0  -- これより遠い車の分は出さない
        VehicleConfig.EffectScale = 1.0

        -- 出した直後に呼ばれる（クライアント側）。鍵を渡すなど、サーバーごとの処理をここへ書く
        -- qb-vehiclekeys が動いていれば鍵を渡す。ほかの鍵リソースを使うサーバーは、ここを書き換える
        VehicleConfig.OnSpawned = function(vehicle, plate)
            if GetResourceState('qb-vehiclekeys') == 'started' then
                TriggerEvent('vehiclekeys:client:SetOwner', plate)
            end
        end

        VehicleConfig.Text = {
            list = '呼び出せる車: %s',
            many = '呼び出せる車が %d 台あります。/%s <名前の一部> で絞り込めます',
            unknown = 'その名前の車はありません: %s',
            cooldown = '少し待ってからもう一度どうぞ',
            noModel = 'この車のモデルがゲームにありません: %s',
            failed = '車を出せませんでした',
            spawned = '%s を出しました',
        }
        """;

    public const string Server = """
        -- kn_exchange が作成。Menyoo で保存した車を、コマンドで呼び出す。
        -- 出すのは呼んだ人のクライアント。ここは「誰が何を出してよいか」と後片付けを受け持つ。

        local RES = GetCurrentResourceName()
        local STATE = 'knx:' .. RES
        local pending = {}   -- source → { name, expires }
        local records = {}   -- source → { { vehicle, objects }, ... }
        local lastUse = {}   -- source → 最後に使った時刻

        local function tell(src, text)
            TriggerClientEvent(RES .. ':tell', src, text)
        end

        local function remove(entity)
            if entity and DoesEntityExist(entity) then DeleteEntity(entity) end
        end

        local function clear(src)
            local list = records[src]
            if not list then return end
            records[src] = nil
            for i = 1, #list do
                for j = 1, #list[i].objects do remove(list[i].objects[j]) end
                remove(list[i].vehicle)
            end
        end

        -- クライアントが作った直後の実体は、サーバーにまだ届いていないことがある。届くまで少し待つ
        local function waitEntity(net, kind, deadline)
            if type(net) ~= 'number' then return nil end
            while true do
                local entity = NetworkGetEntityFromNetworkId(net)
                if entity and entity ~= 0 and DoesEntityExist(entity) then
                    return GetEntityType(entity) == kind and entity or nil
                end
                if GetGameTimer() > deadline then return nil end
                Wait(100)
            end
        end

        -- 名前の一覧。filter があれば、それを含む名前だけ。多すぎるときは数と絞り込み方を返す
        local function names(filter)
            local list = {}
            for name in pairs(Vehicles) do
                if not filter or name:find(filter, 1, true) then list[#list + 1] = name end
            end
            table.sort(list)
            if #list == 0 then return nil end
            if #list > 30 then return VehicleConfig.Text.many:format(#list, VehicleConfig.Command) end
            return VehicleConfig.Text.list:format(table.concat(list, ', '))
        end

        RegisterCommand(VehicleConfig.Command, function(src, args)
            if src == 0 then
                print(names(args[1] and tostring(args[1]):lower() or nil) or VehicleConfig.Text.unknown:format(args[1]))
                return
            end
            local name = args[1] and tostring(args[1]):lower() or nil
            if not name then return tell(src, names()) end
            if not Vehicles[name] then
                tell(src, VehicleConfig.Text.unknown:format(name))
                local close = names(name)
                if close then tell(src, close) end
                return
            end

            local now = os.time()
            if lastUse[src] and now - lastUse[src] < VehicleConfig.Cooldown then
                return tell(src, VehicleConfig.Text.cooldown)
            end
            lastUse[src] = now
            pending[src] = { name = name, expires = now + 30 }
            -- 前の車は先に消す。出した後で消すと、同じ場所で 2 台が重なって壊れる
            if VehicleConfig.OnePerPlayer then clear(src) end
            TriggerClientEvent(RES .. ':spawn', src, name)
        end, VehicleConfig.Restricted)

        -- クライアントが出した車と取り付けた物を控える。直前にコマンドで許可した分しか受け取らない
        RegisterNetEvent(RES .. ':spawned', function(vehNet, objNets)
            local src = source
            local ask = pending[src]
            pending[src] = nil
            if not ask or os.time() > ask.expires then return end
            local def = Vehicles[ask.name]
            if type(vehNet) ~= 'number' or type(objNets) ~= 'table' or #objNets > #def.attachments then return end

            local deadline = GetGameTimer() + 5000
            local vehicle = waitEntity(vehNet, 2, deadline)
            if not vehicle then
                return print(('[%s] 出した車がサーバーへ届きませんでした（%s）'):format(RES, ask.name))
            end
            if (GetEntityModel(vehicle) & 0xFFFFFFFF) ~= (def.model & 0xFFFFFFFF) then return end

            local objects = {}
            for i = 1, #objNets do
                local obj = waitEntity(objNets[i], 3, deadline)
                if obj then objects[#objects + 1] = obj end
            end
            if not DoesEntityExist(vehicle) then
                for i = 1, #objects do remove(objects[i]) end
                return
            end

            local list = records[src] or {}
            records[src] = list
            list[#list + 1] = { vehicle = vehicle, objects = objects }
            Entity(vehicle).state:set(STATE, ask.name, true)
        end)

        -- 車が消えたら、付いていた物も消す（付いていた物は車と一緒には消えない）
        CreateThread(function()
            while true do
                Wait(5000)
                for src, list in pairs(records) do
                    for i = #list, 1, -1 do
                        if not DoesEntityExist(list[i].vehicle) then
                            for j = 1, #list[i].objects do remove(list[i].objects[j]) end
                            table.remove(list, i)
                        end
                    end
                    if #list == 0 then records[src] = nil end
                end
            end
        end)

        AddEventHandler('playerDropped', function()
            local src = source
            pending[src] = nil
            lastUse[src] = nil
            if VehicleConfig.DeleteOnDrop then clear(src) else records[src] = nil end
        end)

        AddEventHandler('onResourceStop', function(resource)
            if resource ~= RES then return end
            for src in pairs(records) do clear(src) end
        end)
        """;

    public const string Client = """
        -- kn_exchange が作成。Menyoo で保存した車を出し、色・改造・取り付けた物を付ける。

        local RES = GetCurrentResourceName()
        local STATE = 'knx:' .. RES

        -- 無いネイティブ名を呼ぶとスレッドごと止まるので、あるものだけ呼ぶ
        local function call(fn, ...)
            if fn then return fn(...) end
        end

        local function tell(text)
            print(('[%s] %s'):format(RES, text))
            TriggerEvent('chat:addMessage', { args = { RES, text } })
        end

        RegisterNetEvent(RES .. ':tell', function(text)
            if type(text) == 'string' then tell(text) end
        end)

        local function loadModel(model)
            if not IsModelInCdimage(model) then return false end
            RequestModel(model)
            local deadline = GetGameTimer() + 10000
            while not HasModelLoaded(model) do
                if GetGameTimer() > deadline then return false end
                Wait(0)
            end
            return true
        end

        local function applyLook(vehicle, def)
            SetVehicleModKit(vehicle, 0)
            if def.livery >= 0 then SetVehicleLivery(vehicle, def.livery) end

            local p = def.paint
            call(SetVehicleModColor_1, vehicle, p[1], p[2], p[3])
            call(SetVehicleModColor_2, vehicle, p[4], p[5])
            local c = def.colours
            SetVehicleColours(vehicle, c[1], c[2])
            SetVehicleExtraColours(vehicle, c[3], c[4])
            if def.custom1 then SetVehicleCustomPrimaryColour(vehicle, def.custom1[1], def.custom1[2], def.custom1[3]) end
            if def.custom2 then SetVehicleCustomSecondaryColour(vehicle, def.custom2[1], def.custom2[2], def.custom2[3]) end
            call(SetVehicleInteriorColor or SetVehicleInteriorColour, vehicle, def.interior)
            call(SetVehicleDashboardColor or SetVehicleDashboardColour, vehicle, def.dashboard)

            SetVehicleNumberPlateText(vehicle, def.plate)
            SetVehicleNumberPlateTextIndex(vehicle, def.plateIndex)
            SetVehicleWheelType(vehicle, def.wheelType)
            if def.windowTint >= 0 then SetVehicleWindowTint(vehicle, def.windowTint) end
            SetVehicleTyresCanBurst(vehicle, not def.bulletProofTyres)
            SetVehicleDirtLevel(vehicle, def.dirt)
            call(SetVehicleEnveffScale, vehicle, def.paintFade)

            for i = 1, 4 do SetVehicleNeonLightEnabled(vehicle, i - 1, def.neons[i]) end
            SetVehicleNeonLightsColour(vehicle, def.neonColour[1], def.neonColour[2], def.neonColour[3])

            for id, on in pairs(def.extras) do
                if DoesExtraExist(vehicle, id) then SetVehicleExtra(vehicle, id, not on) end
            end
            for modType, on in pairs(def.toggles) do ToggleVehicleMod(vehicle, modType, on) end
            for modType, mod in pairs(def.mods) do SetVehicleMod(vehicle, modType, mod[1], mod[2] ~= 0) end

            if def.tyreSmoke then SetVehicleTyreSmokeColor(vehicle, def.tyreSmoke[1], def.tyreSmoke[2], def.tyreSmoke[3]) end
            -- ヘッドライトの色は、キセノン（改造 22）を付けた後でないと効かない
            if def.xenon ~= 255 then call(SetVehicleXenonLightsColor or SetVehicleHeadlightsColour, vehicle, def.xenon) end
        end

        local function attach(vehicle, def)
            local nets, objects = {}, {}
            local pos = GetEntityCoords(vehicle)
            for i = 1, #def.attachments do
                local a = def.attachments[i]
                if loadModel(a[1]) then
                    local obj = CreateObject(a[1], pos.x, pos.y, pos.z + 2.0, true, false, false)
                    SetModelAsNoLongerNeeded(a[1])
                    if obj ~= 0 then
                        if a[9] < 255 then SetEntityAlpha(obj, a[9], false) end
                        -- Menyoo と同じ引数で付ける（回転順 2・向きを固定）
                        AttachEntityToEntity(obj, vehicle, a[2], a[3], a[4], a[5], a[6], a[7], a[8],
                            false, false, a[10], false, 2, true)
                        nets[#nets + 1] = NetworkGetNetworkIdFromEntity(obj)
                        objects[#objects + 1] = obj
                    end
                else
                    print(('[%s] ゲームに無いモデルです（この分は付きません）: %s'):format(RES, a[1]))
                end
            end
            return nets, objects
        end

        local busy = false
        local mine = {}   -- 自分が出した分 { vehicle, objects }。サーバーの後片付けが届かないときの保険

        local function removeLocal(entity)
            if DoesEntityExist(entity) then
                SetEntityAsMissionEntity(entity, true, true)
                DeleteEntity(entity)
            end
        end

        local function clearMine(withVehicle)
            for i = #mine, 1, -1 do
                local rec = mine[i]
                if withVehicle or not DoesEntityExist(rec.vehicle) then
                    for j = 1, #rec.objects do removeLocal(rec.objects[j]) end
                    if withVehicle then removeLocal(rec.vehicle) end
                    table.remove(mine, i)
                end
            end
        end

        -- 車が消えたら、付いていた物も消す
        CreateThread(function()
            while true do
                Wait(2000)
                if #mine > 0 then pcall(clearMine, false) end
            end
        end)

        local function trim(text)
            return (text:gsub('^%s+', ''):gsub('%s+$', ''))
        end

        RegisterNetEvent(RES .. ':spawn', function(name)
            local def = type(name) == 'string' and Vehicles[name] or nil
            if not def or busy then return end
            busy = true

            local ok, err = pcall(function()
                if not IsModelAVehicle(def.model) or not loadModel(def.model) then
                    return tell(VehicleConfig.Text.noModel:format(def.label))
                end
                if VehicleConfig.OnePerPlayer then clearMine(true) end
                local ped = PlayerPedId()
                local pos = GetOffsetFromEntityInWorldCoords(ped, 0.0, VehicleConfig.SpawnAhead + 0.0, 0.5)
                local vehicle = CreateVehicle(def.model, pos.x, pos.y, pos.z, GetEntityHeading(ped) + 90.0, true, false)
                SetModelAsNoLongerNeeded(def.model)
                if vehicle == 0 then return tell(VehicleConfig.Text.failed) end

                SetVehicleOnGroundProperly(vehicle)
                applyLook(vehicle, def)
                local nets, objects = attach(vehicle, def)
                mine[#mine + 1] = { vehicle = vehicle, objects = objects }
                TriggerServerEvent(RES .. ':spawned', NetworkGetNetworkIdFromEntity(vehicle), nets)
                tell(VehicleConfig.Text.spawned:format(def.label))
                VehicleConfig.OnSpawned(vehicle, trim(GetVehicleNumberPlateText(vehicle)))
            end)
            busy = false
            if not ok then print(('[%s] %s'):format(RES, err)) end
        end)

        -- パーティクル（炎など）。サーバーが車へ付けた印を見て、近くにいる全員が自分の画面で出す
        if VehicleConfig.Effects then
            local active = {}   -- 車 → 定義

            CreateThread(function()
                while true do
                    local ok, err = pcall(function()
                        local found = {}
                        local pos = GetEntityCoords(PlayerPedId())
                        local vehicles = GetGamePool('CVehicle')
                        for i = 1, #vehicles do
                            local vehicle = vehicles[i]
                            local name = Entity(vehicle).state[STATE]
                            local def = name and Vehicles[name]
                            if def and #def.effects > 0 and #(pos - GetEntityCoords(vehicle)) <= VehicleConfig.EffectDistance then
                                found[vehicle] = def
                            end
                        end
                        active = found
                    end)
                    if not ok then print(('[%s] %s'):format(RES, err)) end
                    Wait(1000)
                end
            end)

            CreateThread(function()
                while true do
                    local ok, err = pcall(function()
                        for vehicle, def in pairs(active) do
                            if DoesEntityExist(vehicle) then
                                for i = 1, #def.effects do
                                    local e = def.effects[i]
                                    if HasNamedPtfxAssetLoaded(e[1]) then
                                        UseParticleFxAsset(e[1])
                                        StartParticleFxNonLoopedOnEntity(e[2], vehicle, e[3], e[4], e[5], 0.0, 0.0, 0.0,
                                            VehicleConfig.EffectScale + 0.0, false, false, false)
                                    else
                                        RequestNamedPtfxAsset(e[1])
                                    end
                                end
                            end
                        end
                    end)
                    if not ok then print(('[%s] %s'):format(RES, err)) end
                    Wait(next(active) and VehicleConfig.EffectInterval or 1000)
                end
            end)
        end
        """;
}

