using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;
using KnExchange.Rpf7;

namespace KnExchange;

public sealed class ConvertOptions
{
    public string Input { get; set; }
    public string OutputDir { get; set; }

    /// <summary>複数系統（Legacy / Enhanced など）があるとき、パスにこの文字列を含むものだけを使う。</summary>
    public string Variant { get; set; }

    /// <summary>リソース名の上書き。出力が 1 つのときだけ有効。</summary>
    public string Name { get; set; }

    /// <summary>出力先に既存ファイルがあっても書き込む。</summary>
    public bool Force { get; set; }

    /// <summary>
    /// バニラの vehicles.meta（と carvariations）を置いたフォルダ。
    /// 置き換え型の mod を別名の車として追加するときに、元の車の定義を写すために使う。
    /// 未指定なら環境変数 KN_EXCHANGE_VANILLA を見る。
    /// </summary>
    public string Vanilla { get; set; }

    /// <summary>置き換え型を、バニラの車を上書きする形のまま出す。</summary>
    public bool Replace { get; set; }

    /// <summary>置き換え型が複数の車を含むとき、変換する 1 台（置き換え先のモデル名）。</summary>
    public string BaseModel { get; set; }

    /// <summary>ped の定義を作るときの性別（"male" / "female"）。モデルからは判別できない。</summary>
    public string Gender { get; set; }
}

public sealed class ResourceReport
{
    public string Name { get; set; }
    public string OutputPath { get; set; }
    public int StreamCount { get; set; }
    public int HeadersRestored { get; set; }
    public int TextEntries { get; set; }
    public List<(string Type, string Path)> DataFiles { get; } = new();
    public List<string> Warnings { get; } = new();
    public List<string> Skipped { get; } = new();
}

/// <summary>
/// シングルプレイヤー用 mod を FiveM リソースへ組み替える。
///
/// やることは「rpf から取り出して置き直す」だけで、モデルやテクスチャの中身には触らない。
/// data_file の種別は mod 自身の content.xml から引く（ファイル名からの推測は最後の手段）。
/// </summary>
public static class ModConverter
{
    /// <summary>版は Directory.Build.props に書く（ここへは書かない）。</summary>
    public static readonly string Version =
        typeof(ModConverter).Assembly.GetName().Version?.ToString(3) ?? "0.0.0";

    /// <summary>FiveM が読めない世代の資産が入っているフォルダの目印。</summary>
    private static readonly Regex EnhancedMarker =
        new(@"enhanced|gen9|next[\s_-]?gen", RegexOptions.IgnoreCase | RegexOptions.Compiled);

    /// <summary>グラフィックメモリがこれ以上のリソースは FiveM がストリーミング警告を出す。</summary>
    private const long LargeAssetBytes = 16 * 1024 * 1024;

    /// <summary>
    /// 「フォルダ名^ファイル名」の読み替えは、サーバーのポリシーに subdir_file_mapping がある時だけ働く
    /// （FiveM の LoadStreamingFile.cpp）。無いとエラーも出ずに無視されるので、変換した時点で知らせる。
    /// </summary>
    static void WarnSubdirPolicy(ResourceReport report, IEnumerable<string> names)
    {
        if (names.Any(n => n.Contains('^')))
            report.Warnings.Add(Lang.T("部品フォルダ型です（stream/ に「名前^部品」形式のファイルがあります）。" +
                "この形式はサーバーに独自衣装のストリーミング権限（ポリシー subdir_file_mapping）が無いと読まれず、" +
                "エラーも出ないまま、追加した ped は透明に、バニラの ped の置き換えは元の姿のままになります。", "This ped keeps its components in a folder (stream/ contains \"name^component\" files). " +
                "The server only loads these when it has the custom clothing streaming permission (policy subdir_file_mapping). " +
                "Without it nothing is reported: an added ped turns invisible and a replaced vanilla ped keeps its original look."));
    }

    /// <summary>車 1 台ぶんの vehiclelayouts.meta は数 KB。これを超えるならバニラ全体の写しを疑う。</summary>
    private const long LargeLayoutsBytes = 256 * 1024;

    public static List<ResourceReport> Convert(ConvertOptions options, Action<string> log)
    {
        if (string.IsNullOrWhiteSpace(options.OutputDir))
            throw new ArgumentException(Lang.T("出力先が指定されていません。", "No output folder was given."));

        using var input = InputUnpacker.Open(options.Input, log);

        var rpfs = SelectVariant(
            Directory.EnumerateFiles(input.RootPath, "*.rpf", SearchOption.AllDirectories).ToList(),
            input.RootPath, options.Variant, log);

        var reports = new List<ResourceReport>();
        var usedNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        // gta5-mods の配布ファイル名は先頭に 6 桁の識別子が付く（"ac8e43-..."）。名前には要らない
        // フォルダ名の "2.0" を拡張子と取り違えない
        var inputPath = options.Input.TrimEnd('/', '\\');
        // 末尾に "_1791299915_143550" のような長い数字の並びを足す配布サイトもある。これも落とす
        var rawName = Regex.Replace(
            Directory.Exists(inputPath) ? Path.GetFileName(inputPath) : Path.GetFileNameWithoutExtension(inputPath),
            @"^[0-9a-f]{6}-|(_\d{6,})+$", "");
        var fallbackName = Sanitize(rawName);

        // Menyoo の保存ファイルは、車やマップの資産とは別のリソースにする（仕組みが違うため）
        var menyoo = MenyooBuilder.Find(input.RootPath);

        if (rpfs.Count == 0)
        {
            RejectGen9(LooseGen9(input.RootPath, options.Variant));
            var hasAssets = LooseAssets(input.RootPath).Count > 0;
            if (hasAssets || menyoo.Count == 0)
                reports.Add(ConvertLoose(input.RootPath, options, rawName, log));
            if (menyoo.Count > 0)
                reports.Add(ConvertMenyoo(menyoo, options, fallbackName, !hasAssets, log));
            return reports;
        }

        var failures = new List<string>();
        foreach (var rpf in rpfs)
        {
            var label = Path.GetRelativePath(input.RootPath, rpf);
            try
            {
                var name = rpfs.Count == 1 && options.Name != null ? Sanitize(options.Name) : null;
                RejectGen9(RpfTree.Flatten(Rpf7Archive.Open(rpf))
                    .Where(f => f.Entry is Rpf7ResourceFileEntry r
                        && ModFormats.IsGen9(f.Name, ModFormats.ResourceVersion(r.SystemFlags, r.GraphicsFlags)))
                    .Select(f => f.Name).ToList());
                reports.Add(ConvertRpf(rpf, options, name, fallbackName, usedNames, log));
            }
            catch (Exception ex) when (ex is NotSupportedException or InvalidDataException or EndOfStreamException)
            {
                failures.Add($"{label}: {ex.Message}");
                log(Lang.T($"[失敗] {label}: {ex.Message}", $"[failed] {label}: {ex.Message}"));
            }
        }

        if (menyoo.Count > 0)
            reports.Add(ConvertMenyoo(menyoo, options, fallbackName, false, log));

        if (reports.Count == 0)
            throw new InvalidOperationException(
                Lang.T("変換できる rpf がありませんでした。\n", "No rpf could be converted.\n") + string.Join("\n", failures));

        return reports;
    }

    // ------------------------------------------------------------------
    // 系統の選択
    // ------------------------------------------------------------------

    private static List<string> SelectVariant(List<string> paths, string root, string variant, Action<string> log)
    {
        if (paths.Count <= 1) return paths;

        string Rel(string p) => Path.GetRelativePath(root, p);

        if (!string.IsNullOrEmpty(variant))
        {
            var chosen = paths.Where(p => Rel(p).Contains(variant, StringComparison.OrdinalIgnoreCase)).ToList();
            if (chosen.Count == 0)
                throw new InvalidOperationException(
                    Lang.T($"--variant \"{variant}\" に一致するものがありません。候補:\n  ", $"Nothing matches --variant \"{variant}\". Candidates:\n  ") +
                    string.Join("\n  ", paths.Select(Rel)));
            return chosen;
        }

        // FiveM は Legacy のゲーム上で動くので、Enhanced 用の資産は読めない
        var legacy = paths.Where(p => !EnhancedMarker.IsMatch(Rel(p))).ToList();
        if (legacy.Count > 0 && legacy.Count < paths.Count)
        {
            foreach (var p in paths.Except(legacy))
                log(Lang.T($"Enhanced 用と判断して除外: {Rel(p)}", $"Skipped as an Enhanced build: {Rel(p)}"));
            return legacy;
        }

        return paths;
    }

    // ------------------------------------------------------------------
    // rpf → リソース
    // ------------------------------------------------------------------

    private static ResourceReport ConvertRpf(string rpfPath, ConvertOptions options, string forcedName,
        string fallbackName, HashSet<string> usedNames, Action<string> log)
    {
        var archive = Rpf7Archive.Open(rpfPath);
        var files = RpfTree.Flatten(archive);
        var report = new ResourceReport();

        //[ DLC の起点 ]
        // content.xml のパスは DLC の起点からの相対で書かれている。配布パックによっては
        // 起点が最上位ではなく入れ子の中にある（例: content/foo.rpf/content.xml）ので、
        // いちばん浅い content.xml（無ければ setup2.xml）の位置を起点とする。
        var anchor = files
            .Where(x => x.Name is "content.xml" or "setup2.xml")
            .OrderBy(x => x.Path.Count(c => c == '/')).ThenBy(x => x.Name, StringComparer.Ordinal)
            .FirstOrDefault();
        var basePath = anchor != null ? anchor.Path[..^anchor.Name.Length] : "";

        byte[] ReadRoot(string name)
        {
            var f = files.FirstOrDefault(x => x.Path == basePath + name);
            return f?.Read(out _);
        }

        // --- 名前 ---
        var name = forcedName;
        if (name == null)
        {
            var setup = ReadRoot("setup2.xml");
            var device = setup != null ? ContentXml.ReadDeviceName(setup) : null;
            if (!string.IsNullOrEmpty(device))
                name = Sanitize(device.StartsWith("dlc_", StringComparison.OrdinalIgnoreCase) ? device[4..] : device);
        }
        if (string.IsNullOrEmpty(name))
        {
            var stem = Path.GetFileNameWithoutExtension(rpfPath);
            name = Sanitize(stem.Equals("dlc", StringComparison.OrdinalIgnoreCase)
                ? Path.GetFileName(Path.GetDirectoryName(rpfPath))
                : stem);
        }
        if (string.IsNullOrEmpty(name) || name.StartsWith("tmp", StringComparison.Ordinal) && name.Contains('.'))
            name = fallbackName;
        if (string.IsNullOrEmpty(name)) name = "converted";

        var unique = name;
        for (var n = 2; !usedNames.Add(unique); n++) unique = $"{name}_{n}";
        report.Name = unique;
        report.OutputPath = PrepareOutput(options, unique);

        log(Lang.T($"変換: {Path.GetFileName(rpfPath)} → {unique}  ({files.Count} ファイル)", $"Converting: {Path.GetFileName(rpfPath)} → {unique}  ({files.Count} files)"));

        // --- 置き場所を決める ---
        var plan = new Dictionary<string, string>();      // rpf 内パス → 出力の相対パス
        var takenData = new HashSet<string>();
        var gxt = new List<RpfFile>();

        var allPaths = files.Select(f => f.Path.ToLowerInvariant()).ToHashSet();

        foreach (var f in files)
        {
            if (f.Path == basePath + "content.xml" || f.Path == basePath + "setup2.xml") continue;

            // rpf の中の名前はそのまま出力のファイル名になる。区切り文字や ".." を含む名前（細工された rpf）を
            // 通すと、出力フォルダの外へ書き出してしまう
            if (!IsPlainFileName(f.Name))
            {
                report.Warnings.Add(Lang.T($"ファイル名として使えない名前のため取り出していません: {f.Path}", $"Not extracted because its name cannot be used as a file name: {f.Path}"));
                continue;
            }

            if (ModFormats.IsStream(f.Name))
            {
                plan[f.Path] = "stream/" + ModFormats.StreamName(f.Path, allPaths);
            }
            else if (f.Name.EndsWith(".awc", StringComparison.Ordinal))
            {
                var pack = f.ContainerName != null && IsPlainFileName(f.ContainerName) ? f.ContainerName : ParentName(f.Path);
                plan[f.Path] = $"audio/sfx/{(string.IsNullOrEmpty(pack) ? "sfx" : pack)}/{f.Name}";
            }
            else if (ModFormats.IsAudio(f.Name))
            {
                plan[f.Path] = "audio/" + f.Name;
            }
            else if (f.Name.EndsWith(".gxt2", StringComparison.Ordinal))
            {
                gxt.Add(f);
            }
            else if (ModFormats.IsData(f.Name))
            {
                var rel = "data/" + f.Name;
                if (!takenData.Add(rel))
                {
                    rel = $"data/{ParentName(f.Path) ?? "dup"}_{f.Name}";
                    for (var n = 2; !takenData.Add(rel); n++)
                        rel = $"data/{ParentName(f.Path) ?? "dup"}{n}_{f.Name}";
                }
                plan[f.Path] = rel;
            }
            else
            {
                report.Skipped.Add(f.Path);
            }
        }

        // --- data_file を決める ---
        var entries = new List<(string Type, string Path)>();
        var declared = new HashSet<string>();
        var unused = new HashSet<string>();               // FiveM では読まれない種別で宣言されたもの
        var missingCarcols = false;

        var contentBytes = ReadRoot("content.xml");
        var items = contentBytes != null ? ContentXml.Parse(contentBytes) : null;
        if (contentBytes == null)
            report.Warnings.Add(Lang.T("content.xml がありません。種別はファイル名から決めます。", "There is no content.xml. File types are decided from the file names."));
        else if (items == null)
            report.Warnings.Add(Lang.T("content.xml を読めませんでした。種別はファイル名から決めます。", "content.xml could not be read. File types are decided from the file names."));

        foreach (var item in items ?? new List<ContentItem>())
        {
            if (ModFormats.IsSkippedType(item.Type))
            {
                if (plan.TryGetValue(basePath + item.Path, out var ignored)) unused.Add(ignored);
                continue;
            }

            if (item.Type == "AUDIO_WAVEPACK")
            {
                var pack = item.Path[(item.Path.LastIndexOf('/') + 1)..];
                var dir = $"audio/sfx/{pack}";
                if (plan.Values.Any(v => v.StartsWith(dir + "/", StringComparison.Ordinal)))
                    entries.Add((item.Type, dir));
                else
                    report.Warnings.Add(Lang.T($"content.xml が指す音声パックがありません: {item.Path}", $"The audio pack named in content.xml is missing: {item.Path}"));
                continue;
            }

            if (ModFormats.IsAudioDataType(item.Type))
            {
                // "x64/audio/foo_game.dat" は実ファイル "foo_game.dat151.rel" を指す
                if (files.Any(f => f.Path.StartsWith(basePath + item.Path, StringComparison.Ordinal) && ModFormats.IsAudio(f.Name)))
                    entries.Add((item.Type, "audio/" + item.Path[(item.Path.LastIndexOf('/') + 1)..]));
                else
                    report.Warnings.Add(Lang.T($"content.xml が指す音声データがありません: {item.Path}", $"The audio data named in content.xml is missing: {item.Path}"));
                continue;
            }

            if (plan.TryGetValue(basePath + item.Path, out var outPath))
            {
                if (declared.Add(item.Type + "|" + outPath)) entries.Add((item.Type, outPath));
            }
            else
            {
                report.Warnings.Add(Lang.T($"content.xml が指すファイルがありません: {item.Path} ({item.Type})", $"A file named in content.xml is missing: {item.Path} ({item.Type})"));
                if (item.Type == "CARCOLS_FILE") missingCarcols = true;
            }
        }

        var declaredPaths = entries.Select(e => e.Path).ToHashSet();
        foreach (var (src, outPath) in plan.Where(p => p.Value.StartsWith("data/", StringComparison.Ordinal)))
        {
            if (declaredPaths.Contains(outPath) || unused.Contains(outPath)) continue;

            var fileName = src[(src.LastIndexOf('/') + 1)..];
            if (ModFormats.FallbackTypes.TryGetValue(fileName, out var type))
            {
                entries.Add((type, outPath));
                if (items != null)
                    report.Warnings.Add(Lang.T($"content.xml に宣言の無い {fileName} を {type} として加えました。", $"{fileName} is not declared in content.xml; added it as {type}."));
            }
            else
            {
                report.Warnings.Add(Lang.T($"種別が分からないため manifest へ載せていません: {outPath}", $"Left out of the manifest because its type is unknown: {outPath}"));
            }
        }

        // 小物や内装（MLO）の型の定義（.ytyp）は、stream/ へ置くだけでは読まれない。
        // SP では dlc.rpf ごと読むので content.xml に宣言が無く、ここで足す
        foreach (var ytyp in plan.Values
            .Where(v => v.StartsWith("stream/", StringComparison.Ordinal) && v.EndsWith(".ytyp", StringComparison.Ordinal))
            .Distinct().OrderBy(v => v, StringComparer.Ordinal))
        {
            if (entries.All(e => e.Path != ytyp))
                entries.Add(("DLC_ITYP_REQUEST", ytyp));
        }

        // 同じ種別の中では宣言順を保つ（安定ソート）
        report.DataFiles.AddRange(entries
            .Select((e, i) => (e, i))
            .OrderBy(x => TypeRank(x.e.Type)).ThenBy(x => x.i)
            .Select(x => x.e));

        // --- 書き出し ---
        var written = new Dictionary<string, string>();   // 出力の相対パス → 内容のハッシュ
        foreach (var f in files)
        {
            if (!plan.TryGetValue(f.Path, out var rel)) continue;

            var data = f.Read(out var restored);
            var hash = System.Convert.ToHexString(SHA256.HashData(data));

            if (written.TryGetValue(rel, out var existing))
            {
                if (existing != hash)
                    report.Warnings.Add(Lang.T($"同名で中身の違うファイルがあります。先に見つけた方を使いました: {rel}  (捨てた方: {f.Path})", $"Two files share a name but differ in content. Kept the first one found: {rel}  (dropped: {f.Path})"));
                continue;
            }
            written[rel] = hash;

            WriteFile(report.OutputPath, rel, data);
            if (restored) report.HeadersRestored++;

            if (rel.StartsWith("stream/", StringComparison.Ordinal))
            {
                report.StreamCount++;
                WarnIfLarge(report, f.Name, data);
            }
            else if (f.Name == "vehiclelayouts.meta" && data.Length >= LargeLayoutsBytes)
            {
                report.Warnings.Add(Lang.T($"vehiclelayouts.meta が {data.Length / 1024} KB あります。バニラ全体の写しなら、他の車の乗降に影響することがあります。", $"vehiclelayouts.meta is {data.Length / 1024} KB. If it is a copy of the whole vanilla file it can affect entering and leaving other vehicles."));
            }
        }

        // --- 表示名 ---
        var texts = ReadTexts(gxt, report);
        var hasNames = texts.Count > 0;
        if (hasNames)
        {
            WriteFile(report.OutputPath, "names.lua", Encoding.UTF8.GetBytes(BuildNamesLua(texts)));
            report.TextEntries = texts.Count;
        }

        if (!missingCarcols
            && report.DataFiles.Any(d => d.Type == "VEHICLE_METADATA_FILE")
            && report.DataFiles.All(d => d.Type != "CARCOLS_FILE"))
            report.Warnings.Add(Lang.T("carcols.meta がありません（改造キットやサイレンを持たない車なら問題ありません）。", "There is no carcols.meta (fine for a vehicle without mod kits or sirens)."));

        if (report.StreamCount == 0)
            report.Warnings.Add(Lang.T("stream/ へ置くファイルが 1 つもありませんでした。", "There was not a single file to put into stream/."));
        WarnSubdirPolicy(report, written.Keys);

        var audioFiles = written.Keys.Where(k => k.StartsWith("audio/", StringComparison.Ordinal)).ToList();
        WriteFile(report.OutputPath, "fxmanifest.lua",
            Encoding.UTF8.GetBytes(BuildManifest(report.DataFiles, audioFiles, hasNames)));

        return report;
    }

    // ------------------------------------------------------------------
    // rpf を持たない mod（置き換え型など）
    // ------------------------------------------------------------------

    /// <summary>
    /// Enhanced 用の資産は、置き直しても FiveM では読めない。動かないリソースを黙って出さずに止まる。
    /// </summary>
    private static void RejectGen9(List<string> names)
    {
        if (names.Count == 0) return;
        throw new NotSupportedException(
            Lang.T($"Enhanced（gen9）用の資産が {names.Count} 件あります（{string.Join(", ", names.Take(5))}{(names.Count > 5 ? " ..." : "")}）。" +
            "FiveM は Legacy 用の資産しか読めず、形式の変換にも対応していません。" +
            "Legacy 用が同梱されているなら --variant でそのフォルダを指定してください。", $"Found {names.Count} asset(s) built for Enhanced (gen9): {string.Join(", ", names.Take(5))}{(names.Count > 5 ? " ..." : "")}. " +
            "FiveM only reads Legacy assets, and this tool cannot convert between the two formats. " +
            "If a Legacy build is included, point --variant at its folder."));
    }

    /// <summary>変換の対象になる（系統の選択を通った）ばらのファイルのうち、Enhanced 用のもの。</summary>
    private static List<string> LooseGen9(string root, string variant)
    {
        var all = LooseAssets(root).Where(ModFormats.IsStream).ToList();
        string Rel(string p) => Path.GetRelativePath(root, p);

        if (!string.IsNullOrEmpty(variant))
            all = all.Where(p => Rel(p).Contains(variant, StringComparison.OrdinalIgnoreCase)).ToList();
        else
        {
            var legacy = all.Where(p => !EnhancedMarker.IsMatch(Rel(p))).ToList();
            if (legacy.Count > 0) all = legacy;
        }

        var found = new List<string>();
        var head = new byte[8];
        foreach (var p in all)
        {
            using var fs = File.OpenRead(p);
            if (fs.Read(head, 0, 8) == 8 && Rpf7Format.ReadU32(head, 0) == Rpf7Format.Rsc7Magic
                && ModFormats.IsGen9(p, Rpf7Format.ReadU32(head, 4)))
                found.Add(Path.GetFileName(p));
        }
        return found;
    }

    private static List<string> LooseAssets(string root) =>
        Directory.EnumerateFiles(root, "*", SearchOption.AllDirectories)
            .Where(p => ModFormats.IsStream(p) || ModFormats.FallbackTypes.ContainsKey(Path.GetFileName(p)))
            .ToList();

    // ------------------------------------------------------------------
    // Menyoo の保存ファイル → 配置を置き直すスクリプト
    // ------------------------------------------------------------------

    private static ResourceReport ConvertMenyoo(List<string> files, ConvertOptions options, string name,
        bool only, Action<string> log)
    {
        var parsed = MenyooBuilder.Parse(files);
        var cars = MenyooVehicleBuilder.Parse(files);
        var hasProps = parsed.Props.Count > 0;
        var hasCars = cars.Cars.Count > 0;

        // 資産と同梱なら別名にする。配置だけのときの名前は従来どおり
        if (!only) name += hasCars ? "_menyoo" : "_placements";
        else if (options.Name != null) name = Sanitize(options.Name);
        if (string.IsNullOrEmpty(name)) name = hasCars ? "menyoo" : "placements";

        var report = new ResourceReport { Name = name };
        log(Lang.T(
            $"Menyoo の保存ファイル {files.Count} 件: " +
            (hasCars ? $"車 {cars.Cars.Count} 台を呼び出せるようにし、" : "") + $"物 {parsed.Props.Count} 個を置くスクリプトにします",
            $"{files.Count} Menyoo save file(s): " +
            (hasCars ? $"making {cars.Cars.Count} vehicle(s) spawnable and " : "") + $"writing a script that places {parsed.Props.Count} object(s)"));

        foreach (var broken in parsed.Broken.Concat(cars.Broken).Distinct())
            report.Warnings.Add(Lang.T($"壊れていて読めない保存ファイルを飛ばしました: {broken}", $"Skipped a save file that is damaged and unreadable: {broken}"));

        if (!hasProps && !hasCars)
            throw new InvalidOperationException(
                Lang.T("Menyoo の保存ファイルに、変換できる物の配置も保存した車もありませんでした" +
                $"（配置の中の車 {parsed.Vehicles}・ped {parsed.Peds}・取り付けられた物 {parsed.Attached}。これらはまだ変換できません）。", "The Menyoo save files contain neither placed objects nor saved vehicles that can be converted " +
                $"(placed vehicles {parsed.Vehicles}, peds {parsed.Peds}, attached objects {parsed.Attached}; these are not supported yet)."));

        report.OutputPath = PrepareOutput(options, name);
        if (hasProps)
        {
            WriteFile(report.OutputPath, "placements.lua", Encoding.UTF8.GetBytes(MenyooBuilder.BuildPlacements(parsed)));
            WriteFile(report.OutputPath, "config.lua", Encoding.UTF8.GetBytes(LuaText.Localize(MenyooBuilder.Config)));
            WriteFile(report.OutputPath, "client.lua", Encoding.UTF8.GetBytes(LuaText.Localize(MenyooBuilder.Client)));
        }
        if (hasCars)
        {
            WriteFile(report.OutputPath, "vehicles.lua", Encoding.UTF8.GetBytes(MenyooVehicleBuilder.BuildVehicles(cars)));
            WriteFile(report.OutputPath, "vehicles_config.lua", Encoding.UTF8.GetBytes(LuaText.Localize(MenyooVehicleBuilder.Config)));
            WriteFile(report.OutputPath, "vehicles_client.lua", Encoding.UTF8.GetBytes(LuaText.Localize(MenyooVehicleBuilder.Client)));
            WriteFile(report.OutputPath, "vehicles_server.lua", Encoding.UTF8.GetBytes(LuaText.Localize(MenyooVehicleBuilder.Server)));
        }
        WriteFile(report.OutputPath, "fxmanifest.lua", Encoding.UTF8.GetBytes(MenyooBuilder.BuildManifest(Version, hasProps, hasCars)));

        if (hasCars)
        {
            var listed = string.Join(", ", cars.Cars.Take(10).Select(c => c.Key));
            report.Warnings.Add(Lang.T(
                $"保存した車 {cars.Cars.Count} 台を、コマンド /kncar <名前> で呼び出せるようにしました: " + listed +
                (cars.Cars.Count > 10 ? $" ほか {cars.Cars.Count - 10} 台（名前は vehicles.lua、ゲーム内では /kncar で探せます）" : "") +
                "。既定では権限（ACE の command.kncar）を持つ人だけが使えます。設定は vehicles_config.lua。",
                $"{cars.Cars.Count} saved vehicle(s) can now be spawned with the command /kncar <name>: " + listed +
                (cars.Cars.Count > 10 ? $" and {cars.Cars.Count - 10} more (names are in vehicles.lua; in game, /kncar lists them)" : "") +
                ". By default only players with the permission (ACE command.kncar) can use it. Settings are in vehicles_config.lua."));
            var attached = cars.Cars.Sum(c => c.Attachments.Count);
            var effects = cars.Cars.Sum(c => c.Effects.Count);
            if (attached > 0) report.Warnings.Add(Lang.T($"車へ取り付けられた物 {attached} 個を、車に付けて出します。", $"{attached} object(s) attached to vehicles are spawned on the vehicle."));
            if (effects > 0) report.Warnings.Add(Lang.T($"パーティクル（炎など）{effects} 個を、車の上で出します。", $"{effects} particle effect(s) (flames etc.) are played on the vehicle."));
            if (cars.HiddenCarriers > 0)
                report.Warnings.Add(Lang.T($"見えない物 {cars.HiddenCarriers} 個は置いていません（パーティクルを出すための台なので、効果だけを車の上で出します）。", $"{cars.HiddenCarriers} invisible object(s) are not spawned (they only carry particle effects, so just the effect is played on the vehicle)."));
            if (cars.SkippedPeds + cars.SkippedVehicles > 0)
                report.Warnings.Add(Lang.T($"車へ取り付けられた ped {cars.SkippedPeds} 体・車 {cars.SkippedVehicles} 台は変換していません（未対応）。", $"{cars.SkippedPeds} ped(s) and {cars.SkippedVehicles} vehicle(s) attached to vehicles were not converted (not supported)."));
            if (cars.SkippedNested > 0)
                report.Warnings.Add(Lang.T($"車ではなく別の物へ取り付けられた物 {cars.SkippedNested} 個は変換していません（未対応）。", $"{cars.SkippedNested} object(s) attached to another object instead of the vehicle were not converted (not supported)."));
            if (cars.Burning > 0)
                report.Warnings.Add(Lang.T($"「燃えている」指定の物が {cars.Burning} 個あります。本物の火（触れると燃え移る）は付けていません。", $"{cars.Burning} object(s) are marked as burning. Real fire (which spreads on contact) is not added."));
            if (cars.Tuned > 0)
                report.Warnings.Add(Lang.T($"性能の倍率（回転数・トルク・最高速）を指定した車が {cars.Tuned} 台あります。倍率は反映していません。", $"{cars.Tuned} vehicle(s) set performance multipliers (RPM, torque, top speed). They are not applied."));
            if (cars.Protected > 0)
                report.Warnings.Add(Lang.T($"無敵・防弾などの耐性を指定した車が {cars.Protected} 台あります。耐性は反映していません。", $"{cars.Protected} vehicle(s) set proofs such as invincible or bulletproof. They are not applied."));
            if (cars.Unreadable > 0)
                report.Warnings.Add(Lang.T($"読み取れなかった保存した車・取り付けが {cars.Unreadable} 個ありました。", $"{cars.Unreadable} saved vehicle(s) or attachment(s) could not be read."));
        }
        if (!hasProps) return report;

        report.Warnings.Add(Lang.T($"物 {parsed.Props.Count} 個の配置を、近づくと置くスクリプトにしました。モデルは含みません。" +
            "ゲームに無いモデル（別の mod の小物）は表示されず、F8 コンソールに知らせが出ます。", $"Turned the placement of {parsed.Props.Count} object(s) into a script that spawns them when a player comes near. Models are not included. " +
            "Models the game does not have (props from another mod) are not shown, and a notice appears in the F8 console."));
        if (parsed.Reference is { } r)
            report.Warnings.Add(FormattableString.Invariant($"{Lang.T("配置の基準位置", "Reference position of the placement")}: {r.X:0.0}, {r.Y:0.0}, {r.Z:0.0}"));
        if (parsed.Vehicles + parsed.Peds > 0)
            report.Warnings.Add(Lang.T($"車 {parsed.Vehicles} 台・ped {parsed.Peds} 体の配置は変換していません（未対応）。", $"{parsed.Vehicles} placed vehicle(s) and {parsed.Peds} ped(s) were not converted (not supported)."));
        if (parsed.Attached > 0)
            report.Warnings.Add(Lang.T($"車・ped・動く物へ取り付けられた物 {parsed.Attached} 個は変換していません（未対応）。", $"{parsed.Attached} object(s) attached to vehicles, peds or moving objects were not converted (not supported)."));
        if (parsed.AttachedPlaced > 0)
            report.Warnings.Add(Lang.T($"動かない物へ取り付けられた物 {parsed.AttachedPlaced} 個は、保存された位置へ固定して置きます。", $"{parsed.AttachedPlaced} object(s) attached to static objects are placed at their saved position."));
        if (parsed.Markers > 0)
            report.Warnings.Add(Lang.T($"マーカー {parsed.Markers} 個は変換していません（未対応）。", $"{parsed.Markers} marker(s) were not converted (not supported)."));
        if (parsed.TextureVariations > 0)
            report.Warnings.Add(Lang.T($"色違い（テクスチャの番号）を指定した物が {parsed.TextureVariations} 個あります。番号は反映していません。", $"{parsed.TextureVariations} object(s) set a texture variation. It is not applied."));
        if (parsed.ChangesWorld)
            report.Warnings.Add(Lang.T("この配置は、マップの読み込み・取り外し（IPL）や内装の切り替えも指定しています。それらは反映していません。", "This placement also loads or removes map parts (IPLs) or switches interiors. Those are not applied."));
        if (parsed.Unreadable > 0)
            report.Warnings.Add(Lang.T($"読み取れなかった配置が {parsed.Unreadable} 個ありました。", $"{parsed.Unreadable} placement(s) could not be read."));
        if (parsed.Props.Count >= 2000)
            report.Warnings.Add(Lang.T($"物が {parsed.Props.Count} 個あります。スクリプトで置く方式は数が多いと重くなります。", $"There are {parsed.Props.Count} objects. Spawning by script gets heavy when there are many."));
        return report;
    }

    private static ResourceReport ConvertLoose(string root, ConvertOptions options, string rawName, Action<string> log)
    {
        var all = LooseAssets(root);

        if (all.Count == 0)
            throw new InvalidOperationException(
                Lang.T("rpf もストリーミングアセットも見つかりませんでした。スクリプト型の mod は変換できません。", "Found neither an rpf nor streaming assets. Script mods cannot be converted."));

        string Rel(string p) => Path.GetRelativePath(root, p);
        string Dir(string p) => Path.GetDirectoryName(Rel(p)) ?? "";

        if (!string.IsNullOrEmpty(options.Variant))
        {
            all = all.Where(p => Rel(p).Contains(options.Variant, StringComparison.OrdinalIgnoreCase)).ToList();
            if (all.Count == 0)
                throw new InvalidOperationException(Lang.T($"--variant \"{options.Variant}\" に一致するファイルがありません。", $"No file matches --variant \"{options.Variant}\"."));
        }
        else
        {
            var legacy = all.Where(p => !EnhancedMarker.IsMatch(Rel(p))).ToList();
            if (legacy.Count > 0 && legacy.Count < all.Count)
            {
                log(Lang.T($"Enhanced 用と判断して {all.Count - legacy.Count} 件を除外しました", $"Skipped {all.Count - legacy.Count} file(s) as an Enhanced build"));
                all = legacy;
            }
        }

        // stream/ はフォルダを持てないので、置くときの名前で突き合わせる
        var allPaths = Directory.EnumerateFiles(root, "*", SearchOption.AllDirectories)
            .Select(p => Rel(p).Replace('\\', '/').ToLowerInvariant()).ToHashSet();
        string OutName(string p) => ModFormats.IsStream(p)
            ? ModFormats.StreamName(Rel(p), allPaths)
            : Path.GetFileName(p).ToLowerInvariant();

        // 同じ中身の写し（SP 用と FiveM 用の両方を同梱した書庫など）は 1 つにまとめる。
        // 中身が違うなら、どれを使うかはこちらで決められない
        var picked = new List<string>();
        foreach (var group in all.GroupBy(OutName))
        {
            // 写しが無い（ほとんどの）ファイルは比べる相手がいないので、中身を読まない
            var hashes = group.Skip(1).Any()
                ? group.Select(p => System.Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(p)))).Distinct().Count()
                : 1;
            if (hashes > 1)
                throw new InvalidOperationException(
                    Lang.T($"{group.Key} が複数のフォルダにあり、中身が違います。--variant で使う方を指定してください:\n  ", $"{group.Key} exists in several folders with different content. Choose one with --variant:\n  ") +
                    string.Join("\n  ", group.Select(Dir).Distinct().OrderBy(d => d)));
            picked.Add(group.OrderBy(p => p, StringComparer.Ordinal).First());
        }
        all = picked;

        var streams = all.Where(ModFormats.IsStream).ToList();
        var metas = all.Except(streams).ToList();

        // ped は <名前>.yft の隣に <名前>.ymt / .ydd か、同名の部品フォルダを持つ
        var outNames = streams.Select(OutName).ToHashSet();
        var peds = outNames
            .Where(n => n.EndsWith(".yft", StringComparison.Ordinal) && !n.Contains('^'))
            .Select(n => n[..^4])
            .Where(m => outNames.Contains(m + ".ymt") || outNames.Contains(m + ".ydd")
                || outNames.Any(n => n.StartsWith(m + "^", StringComparison.Ordinal)))
            .OrderBy(m => m, StringComparer.Ordinal).ToList();

        if (peds.Count > 0)
            return ConvertPeds(options, rawName, peds, streams, OutName, log);

        // 車のモデル（.yft）を持つなら、別名の車として追加できる
        var bases = streams
            .Where(p => Path.GetExtension(p).Equals(".yft", StringComparison.OrdinalIgnoreCase))
            .Select(BaseModelOf).Distinct().OrderBy(b => b, StringComparer.Ordinal).ToList();

        if (options.Replace || bases.Count == 0)
        {
            var isMap = bases.Count == 0 && streams.All(ModFormats.IsMapAsset)
                && streams.Any(p => Path.GetExtension(p).ToLowerInvariant() is ".ymap" or ".ytyp");
            if (isMap)
                log(Lang.T("マップとして出力します", "Writing it as a map"));
            else if (!options.Replace)
                log(Lang.T("車のモデルを含まない（テクスチャなどの差し替えのみ）ため、置き換えのまま出力します", "No vehicle model is included (only textures and the like), so it is written as a replacement"));
            return WriteReplace(options, Sanitize(options.Name ?? rawName), streams, metas, isMap, log);
        }

        var baseModel = bases[0];
        if (!string.IsNullOrEmpty(options.BaseModel))
        {
            baseModel = bases.FirstOrDefault(b => b.Equals(options.BaseModel, StringComparison.OrdinalIgnoreCase))
                ?? throw new InvalidOperationException(
                    Lang.T($"--base \"{options.BaseModel}\" はこの mod に含まれていません。候補: {string.Join(", ", bases)}", $"--base \"{options.BaseModel}\" is not part of this mod. Candidates: {string.Join(", ", bases)}"));
        }
        else if (bases.Count > 1)
        {
            throw new InvalidOperationException(
                Lang.T($"複数の車を置き換える mod です（{string.Join(", ", bases)}）。\n" +
                "--base <モデル名> で 1 台ずつ変換するか、--replace で置き換えのまま出力してください。", $"This mod replaces several vehicles ({string.Join(", ", bases)}).\n" +
                "Convert them one at a time with --base <model>, or keep them as replacements with --replace."));
        }

        var vanilla = options.Vanilla ?? Environment.GetEnvironmentVariable("KN_EXCHANGE_VANILLA");
        var vehiclesMeta = AddonBuilder.FindVanillaFile(vanilla, "vehicles.meta")
            ?? throw new InvalidOperationException(
                Lang.T($"置き換え型の mod（{baseModel} を差し替えるもの）を別名の車として追加するには、" +
                "バニラの vehicles.meta が要ります。\n" +
                "  --vanilla <vehicles.meta のあるフォルダ> を付けるか、環境変数 KN_EXCHANGE_VANILLA を設定してください。\n" +
                "  バニラの車を上書きする形のまま出すなら --replace を付けてください。", $"Adding a replace-type mod (one that swaps out {baseModel}) as a vehicle with its own name " +
                "needs the vanilla vehicles.meta.\n" +
                "  Pass --vanilla <folder holding vehicles.meta> or set the environment variable KN_EXCHANGE_VANILLA.\n" +
                "  To keep it as a replacement of the vanilla vehicle, pass --replace."));

        // --- 新しいモデル名 ---
        var taken = AddonBuilder.ReadModelNames(vehiclesMeta);
        var newModel = ModelName(options.Name ?? rawName);
        if (newModel.Length == 0) newModel = baseModel + "x";
        while (taken.Contains(newModel) || newModel == baseModel) newModel += "x";

        var report = new ResourceReport { Name = newModel };
        report.OutputPath = PrepareOutput(options, newModel);
        log(Lang.T($"変換: 置き換え型（{baseModel}）→ 追加車 {newModel}", $"Converting: replace-type ({baseModel}) → added vehicle {newModel}"));

        // --- モデルとテクスチャを新しい名前で置く ---
        var hasTxd = false;
        var hasHi = false;
        byte[] mainModel = null;

        foreach (var path in streams)
        {
            var fileName = Path.GetFileName(path).ToLowerInvariant();
            var data = File.ReadAllBytes(path);
            var outName = fileName;

            if (BaseModelOf(path) == baseModel)
            {
                outName = newModel + fileName[baseModel.Length..];
                if (fileName == baseModel + ".ytd") hasTxd = true;
                if (fileName == baseModel + "_hi.yft") hasHi = true;
                if (fileName == baseModel + ".yft") mainModel = data;
            }
            else
            {
                report.Warnings.Add(Lang.T($"{fileName} は {baseModel} の一部ではないため、元の名前のまま置いています（バニラの同名ファイルを上書きします）。", $"{fileName} is not part of {baseModel}, so it keeps its original name (it overrides the vanilla file of the same name)."));
            }

            WriteFile(report.OutputPath, "stream/" + outName, data);
            report.StreamCount++;
            WarnIfLarge(report, outName, data);
        }

        //[ 近距離用のモデル ]
        // 車は遠距離用（<名前>.yft）と近距離用（<名前>_hi.yft）の 2 つで 1 組。
        // 片方しか無い mod を別名にすると近距離用が存在しなくなるので、同じものを当てる。
        if (!hasHi && mainModel != null)
        {
            WriteFile(report.OutputPath, $"stream/{newModel}_hi.yft", mainModel);
            report.StreamCount++;
            log(Lang.T($"  近距離用のモデルが無いため、{newModel}.yft を {newModel}_hi.yft としても置きました", $"  There is no close-range model, so {newModel}.yft was also written as {newModel}_hi.yft"));
        }

        foreach (var m in metas)
            report.Warnings.Add(Lang.T($"同梱の {Path.GetFileName(m)} は使っていません（バニラの車を書き換える前提の内容のため）。", $"The bundled {Path.GetFileName(m)} is not used (it is written to modify the vanilla vehicle)."));

        // --- 車の定義 ---
        var built = AddonBuilder.Build(vanilla, baseModel, newModel, hasTxd);
        report.Warnings.AddRange(built.Warnings);

        WriteFile(report.OutputPath, "data/vehicles.meta", built.VehiclesMeta);
        report.DataFiles.Add(("VEHICLE_METADATA_FILE", "data/vehicles.meta"));

        if (built.CarVariations != null)
        {
            WriteFile(report.OutputPath, "data/carvariations.meta", built.CarVariations);
            report.DataFiles.Add(("VEHICLE_VARIATION_FILE", "data/carvariations.meta"));
        }

        var display = DisplayName(rawName, newModel);
        WriteFile(report.OutputPath, "names.lua", Encoding.UTF8.GetBytes(
            Lang.T("-- 車の表示名\n", "-- Display name of the vehicle\n") +
            $"AddTextEntry(\"{EscapeLua(built.GameName)}\", \"{EscapeLua(display)}\")\n"));
        report.TextEntries = 1;

        WriteFile(report.OutputPath, "fxmanifest.lua",
            Encoding.UTF8.GetBytes(BuildManifest(report.DataFiles, new List<string>(), true)));

        return report;
    }

    // ------------------------------------------------------------------
    // ped
    // ------------------------------------------------------------------

    private static ResourceReport ConvertPeds(ConvertOptions options, string rawName, List<string> peds,
        List<string> streams, Func<string, string> outName, Action<string> log)
    {
        var female = (options.Gender ?? "").ToLowerInvariant() switch
        {
            "female" or "f" => true,
            "male" or "m" or "" => false,
            _ => throw new ArgumentException(Lang.T($"--gender は male か female で指定してください: {options.Gender}", $"--gender must be male or female: {options.Gender}")),
        };

        var vanilla = options.Vanilla ?? Environment.GetEnvironmentVariable("KN_EXCHANGE_VANILLA");
        var pedsMeta = AddonBuilder.FindVanillaFile(vanilla, "peds.meta");
        var names = streams.Select(outName).ToHashSet();

        //[ 置き換え型の見分け ]
        // バニラの ped と同じ名前なら置き換え型。定義はバニラのものが使われるので、
        // 別名にするにはその定義を写す必要がある（車と同じ）。
        var rename = new Dictionary<string, string>();     // 元の名前 → 新しい名前
        var defs = new List<PedBuilder.Ped>();
        var warnings = new List<string>();

        foreach (var ped in peds)
        {
            var source = pedsMeta != null ? PedBuilder.FindVanilla(pedsMeta, ped) : null;
            var isVanilla = source != null || (pedsMeta == null && PedBuilder.LooksVanilla(ped));
            var def = new PedBuilder.Ped
            {
                Name = ped,
                Female = female,
                Streamed = names.Any(n => n.StartsWith(ped + "^", StringComparison.Ordinal)),
                HasProps = names.Contains(ped + "_p.ydd") || names.Any(n => n.StartsWith(ped + "_p^", StringComparison.Ordinal)),
            };

            if (!isVanilla)
            {
                defs.Add(def);
                continue;
            }

            if (options.Replace)
            {
                warnings.Add(Lang.T($"バニラの ped（{ped}）を上書きします。サーバー上のその ped すべてに影響します。", $"This overrides the vanilla ped ({ped}). It affects every such ped on the server."));
            }
            else if (source == null)
            {
                warnings.Add(Lang.T($"{ped} はバニラの ped を置き換えるものに見えます。別名の ped にするにはバニラの peds.meta が要るため、" +
                    "上書きのまま出力しました（--vanilla でフォルダを指定すると別名にします）。", $"{ped} looks like a replacement of a vanilla ped. Giving it its own name needs the vanilla peds.meta, " +
                    "so it was written as a replacement (pass the folder with --vanilla to rename it)."));
            }
            else if (peds.Count > 1)
            {
                warnings.Add(Lang.T($"複数の ped を含むため、{ped} は別名にせず上書きのまま出力しました。", $"Several peds are included, so {ped} was written as a replacement instead of being renamed."));
            }
            else
            {
                var taken = PedBuilder.ReadNames(pedsMeta);
                var newName = ModelName(options.Name ?? rawName);
                if (newName.Length == 0) newName = ped + "x";
                while (taken.Contains(newName)) newName += "x";

                rename[ped] = newName;
                def.Name = newName;
                def.Source = source;
                def.SourceName = ped;
                defs.Add(def);
            }
        }

        var resource = rename.Count == 1 ? rename.Values.First()
            : options.Name != null ? Sanitize(options.Name)
            : peds.Count == 1 ? Sanitize(peds[0])
            : Sanitize(rawName);

        var report = new ResourceReport { Name = string.IsNullOrEmpty(resource) ? "converted" : resource };
        report.OutputPath = PrepareOutput(options, report.Name);
        report.Warnings.AddRange(warnings);
        WarnSubdirPolicy(report, names);

        log(rename.Count == 1
            ? Lang.T($"変換: 置き換え型の ped（{rename.Keys.First()}）→ 追加 ped {report.Name}", $"Converting: replace-type ped ({rename.Keys.First()}) → added ped {report.Name}")
            : Lang.T($"変換: ped（{string.Join(", ", peds)}）→ {report.Name}", $"Converting: ped ({string.Join(", ", peds)}) → {report.Name}"));

        foreach (var path in streams)
        {
            var name = outName(path);
            foreach (var (from, to) in rename)
            {
                // <名前>.* / <名前>_p.* / <名前>^* / <名前>_p^*
                foreach (var prefix in new[] { from + "^", from + "_p^", from + "_p.", from + "." })
                    if (name.StartsWith(prefix, StringComparison.Ordinal))
                    {
                        name = to + name[from.Length..];
                        break;
                    }
            }

            var data = File.ReadAllBytes(path);
            WriteFile(report.OutputPath, "stream/" + name, data);
            report.StreamCount++;
            WarnIfLarge(report, name, data);
        }

        if (defs.Count > 0)
        {
            WriteFile(report.OutputPath, "data/peds.meta", PedBuilder.Build(defs));
            report.DataFiles.Add(("PED_METADATA_FILE", "data/peds.meta"));

            if (defs.Any(d => d.Source == null))
            {
                report.Warnings.Add(Lang.T($"ped の定義は既定値（{(female ? "女性" : "男性")}の一般市民）で作りました。" +
                    "歩き方が合わないときは --gender male / female を指定し直してください。声は付きません。", $"The ped definition was built from defaults (a {(female ? "female" : "male")} civilian). " +
                    "If the walk style looks wrong, set --gender male / female again. No voice is assigned."));
            }
        }

        WriteFile(report.OutputPath, "fxmanifest.lua",
            Encoding.UTF8.GetBytes(BuildManifest(report.DataFiles, new List<string>(), false)));

        return report;
    }

    /// <summary>置き換え型を、バニラの車を上書きする形のまま出す。</summary>
    private static ResourceReport WriteReplace(ConvertOptions options, string name,
        List<string> streams, List<string> metas, bool isMap, Action<string> log)
    {
        var report = new ResourceReport { Name = string.IsNullOrEmpty(name) ? "converted" : name };
        report.OutputPath = PrepareOutput(options, report.Name);

        log(Lang.T($"変換: {(isMap ? "マップ" : "置き換えのまま")} → {report.Name}  ({streams.Count + metas.Count} ファイル)", $"Converting: {(isMap ? "map" : "as a replacement")} → {report.Name}  ({streams.Count + metas.Count} files)"));

        var entries = new List<(string Type, string Path)>();
        foreach (var path in streams)
        {
            var fileName = ModFormats.FixManifestName(Path.GetFileName(path).ToLowerInvariant());
            var data = File.ReadAllBytes(path);
            WriteFile(report.OutputPath, "stream/" + fileName, data);
            report.StreamCount++;
            WarnIfLarge(report, fileName, data);

            // 小物の型の定義（.ytyp）は、置くだけでは読まれない
            if (fileName.EndsWith(".ytyp", StringComparison.Ordinal))
                entries.Add(("DLC_ITYP_REQUEST", "stream/" + fileName));
        }
        foreach (var path in metas)
        {
            var fileName = Path.GetFileName(path).ToLowerInvariant();
            WriteFile(report.OutputPath, "data/" + fileName, File.ReadAllBytes(path));
            entries.Add((ModFormats.FallbackTypes[fileName], "data/" + fileName));
        }

        if (isMap)
        {
            if (streams.All(p => !p.EndsWith(".ytyp", StringComparison.OrdinalIgnoreCase)
                    && !p.EndsWith(".ydr", StringComparison.OrdinalIgnoreCase)))
                report.Warnings.Add(Lang.T("配置だけのマップです（小物のモデルは含みません）。ゲームに無い小物を使っていると、その分は表示されません。", "This map only holds placements (no prop models). Props the game does not have will not be shown."));
        }
        else
        {
            report.Warnings.Add(Lang.T("バニラの同名の車を上書きします。サーバー上のその車すべてに影響します。", "This overrides the vanilla vehicle of the same name. It affects every such vehicle on the server."));
        }
        report.DataFiles.AddRange(entries.OrderBy(e => TypeRank(e.Type)));
        WriteFile(report.OutputPath, "fxmanifest.lua",
            Encoding.UTF8.GetBytes(BuildManifest(report.DataFiles, new List<string>(), false)));

        return report;
    }

    /// <summary>"bati2_hi.yft" / "bati2+hi.ytd" / "bati2.yft" → "bati2"</summary>
    private static string BaseModelOf(string path)
    {
        var stem = Path.GetFileNameWithoutExtension(path).ToLowerInvariant();
        if (stem.EndsWith("_hi", StringComparison.Ordinal) || stem.EndsWith("+hi", StringComparison.Ordinal))
            stem = stem[..^3];
        return stem;
    }

    /// <summary>モデル名に使える形へ寄せる（英数字のみ・末尾の版番号は落とす）。</summary>
    private static string ModelName(string text)
    {
        var s = Regex.Replace((text ?? "").ToLowerInvariant(), "[^a-z0-9]", "").TrimEnd("0123456789".ToCharArray());
        if (s.Length > 0 && char.IsDigit(s[0])) s = "v" + s;
        return s.Length > 16 ? s[..16] : s;
    }

    private static string DisplayName(string text, string fallback)
    {
        var s = Regex.Replace(text ?? "", @"[_\-]+", " ").Trim();
        return s.Length > 0 ? s : fallback;
    }

    // ------------------------------------------------------------------
    // 部品
    // ------------------------------------------------------------------

    private static List<(uint Hash, string Text)> ReadTexts(List<RpfFile> gxt, ResourceReport report)
    {
        // 言語ごとに同じ表が入っている。英語を優先し、無ければ最初の 1 つ
        var pick = gxt.Where(f => f.Path.Contains("american", StringComparison.Ordinal)).ToList();
        if (pick.Count == 0) pick = gxt.Take(1).ToList();

        var result = new Dictionary<uint, string>();
        foreach (var f in pick)
        {
            var parsed = Gxt2.Parse(f.Read(out _));
            if (parsed == null)
            {
                report.Warnings.Add(Lang.T($"表示名の表を読めませんでした: {f.Path}", $"A display-name table could not be read: {f.Path}"));
                continue;
            }
            foreach (var (hash, text) in parsed) result.TryAdd(hash, text);
        }
        return result.OrderBy(kv => kv.Key).Select(kv => (kv.Key, kv.Value)).ToList();
    }

    private static string BuildNamesLua(List<(uint Hash, string Text)> texts)
    {
        var sb = new StringBuilder();
        sb.Append(Lang.T("-- mod の表示名（元の .gxt2 から書き起こしたもの）\n", "-- Display names of the mod (transcribed from its .gxt2)\n"));
        sb.Append("local entries = {\n");
        foreach (var (hash, text) in texts)
            sb.Append($"    [0x{hash:X8}] = \"{EscapeLua(text)}\",\n");
        sb.Append("}\n\n");
        sb.Append("for hash, text in pairs(entries) do\n");
        sb.Append("    AddTextEntryByHash(hash, text)\n");
        sb.Append("end\n");
        return sb.ToString();
    }

    private static string EscapeLua(string s)
    {
        var sb = new StringBuilder(s.Length);
        foreach (var c in s)
        {
            switch (c)
            {
                case '\\': sb.Append("\\\\"); break;
                case '"': sb.Append("\\\""); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': break;
                default:
                    if (c < 0x20) sb.Append(' '); else sb.Append(c);
                    break;
            }
        }
        return sb.ToString();
    }

    public static string BuildManifest(List<(string Type, string Path)> dataFiles, List<string> audioFiles, bool hasNames)
    {
        var files = new List<string>();
        foreach (var d in dataFiles)
        {
            // 音声パックはフォルダ、音声データは拡張子を落とした名前で宣言される
            if (d.Type == "AUDIO_WAVEPACK" || ModFormats.IsAudioDataType(d.Type)) continue;
            if (!files.Contains(d.Path)) files.Add(d.Path);
        }

        foreach (var a in audioFiles.OrderBy(a => a, StringComparer.Ordinal))
        {
            var entry = a.EndsWith(".awc", StringComparison.Ordinal)
                ? a[..(a.LastIndexOf('/') + 1)] + "*.awc"
                : a;
            if (!files.Contains(entry)) files.Add(entry);
        }

        var sb = new StringBuilder();
        sb.Append(Lang.T($"-- kn_exchange {Version} で生成\n", $"-- Generated by kn_exchange {Version}\n"));
        sb.Append("fx_version 'cerulean'\n");
        sb.Append("game 'gta5'\n");

        if (files.Count > 0)
        {
            sb.Append("\nfiles {\n");
            foreach (var f in files) sb.Append($"    '{LuaSingle(f)}',\n");
            sb.Append("}\n");
        }

        if (dataFiles.Count > 0)
        {
            sb.Append('\n');
            foreach (var d in dataFiles) sb.Append($"data_file '{LuaSingle(d.Type)}' '{LuaSingle(d.Path)}'\n");
        }

        if (hasNames) sb.Append("\nclient_script 'names.lua'\n");

        return sb.ToString();
    }

    private static void WarnIfLarge(ResourceReport report, string name, byte[] data)
    {
        var graphics = ModFormats.GraphicsBytes(data);
        if (graphics >= LargeAssetBytes)
            report.Warnings.Add(Lang.T($"{name} はグラフィックメモリを {graphics / 1048576.0:F0} MB 使います。" +
                "FiveM が大きすぎる資産として警告し、読み込みの遅れやテクスチャ抜けの原因になることがあります。", $"{name} uses {graphics / 1048576.0:F0} MB of graphics memory. " +
                "FiveM warns about it as an oversized asset, and it can cause slow loading or missing textures."));
    }

    private static int TypeRank(string type)
    {
        var i = Array.IndexOf(ModFormats.TypeOrder, type);
        return i < 0 ? int.MaxValue : i;
    }

    private static string ParentName(string path)
    {
        var parts = path.Split('/');
        return parts.Length >= 2 ? Sanitize(Path.GetFileNameWithoutExtension(parts[^2])) : null;
    }

    /// <summary>リソース名に使える形へ寄せる（FiveM のリソース名は ASCII が無難）。</summary>
    public static string Sanitize(string name)
    {
        if (string.IsNullOrWhiteSpace(name)) return "";
        var s = Regex.Replace(name.Trim().ToLowerInvariant(), @"[^a-z0-9_\-]+", "_").Trim('_');
        return s.Length > 48 ? s[..48].Trim('_') : s;
    }

    private static string PrepareOutput(ConvertOptions options, string name)
    {
        var path = Path.Combine(Path.GetFullPath(options.OutputDir), name);

        // 既存の出力は黙って上書きしない（手で直した manifest や meta を守る）
        if (Directory.Exists(path) && Directory.EnumerateFileSystemEntries(path).Any() && !options.Force)
            throw new InvalidOperationException(
                Lang.T($"出力先に既にファイルがあります: {path}\n上書きするなら --force を付けてください。", $"The output folder already has files: {path}\nPass --force to overwrite."));

        Directory.CreateDirectory(path);
        return path;
    }

    /// <summary>フォルダを含まない、そのまま置ける名前か（区切り文字・".."・Windows で作れない名前を通さない）。</summary>
    internal static bool IsPlainFileName(string name) =>
        !string.IsNullOrWhiteSpace(name)
        && name.IndexOfAny(InvalidNameChars) < 0
        && name.Trim('.', ' ').Length > 0
        && name[^1] is not ('.' or ' ');

    private static readonly char[] InvalidNameChars =
        Path.GetInvalidFileNameChars().Concat(new[] { '/', '\\', ':', '*', '?', '"', '<', '>', '|' }).Distinct().ToArray();

    /// <summary>manifest の '...' の中へ入れる形にする。</summary>
    private static string LuaSingle(string s) => s.Replace("\\", "\\\\").Replace("'", "\\'");

    private static void WriteFile(string root, string relative, byte[] data)
    {
        var dest = Path.GetFullPath(Path.Combine(root, relative.Replace('/', Path.DirectorySeparatorChar)));
        // 最後の歯止め。どの経路で来た名前でも、出力フォルダの外へは書かない
        if (!dest.StartsWith(Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar) + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase))
            throw new InvalidDataException(Lang.T($"出力フォルダの外を指す名前です: {relative}", $"The name points outside the output folder: {relative}"));
        Directory.CreateDirectory(Path.GetDirectoryName(dest));
        File.WriteAllBytes(dest, data);
    }
}

