using KnExchange.Rpf7;

namespace KnExchange;

/// <summary>
/// 拡張子による振り分けと、data_file 種別の既定表。
///
/// 拡張子リストを展開・走査・変換で別々に持つと食い違いが起き、
/// 「入力に含まれているのに黙って無視される」事故になるため 1 箇所に集約する。
/// </summary>
public static class ModFormats
{
    /// <summary>stream/ へ置くだけで FiveM がストリーミング登録するもの。</summary>
    public static readonly string[] StreamExtensions =
    {
        ".yft", ".ytd", ".ydr", ".ydd", ".ycd", ".ybn",
        ".ymap", ".ytyp", ".ynv", ".ypt", ".yed", ".yld", ".ymt",
        // マップの目録（_manifest.ymf）。内装（MLO）の当たり判定や、どの .ymap がどの .ytyp を要るかを持つ
        ".ymf",
    };

    /// <summary>入れ子で展開する書庫。.oiv の中身は zip。</summary>
    public static readonly string[] ArchiveExtensions = { ".zip", ".rar", ".7z", ".oiv" };

    public static bool IsStream(string name) => StreamExtensions.Contains(Ext(name));
    public static bool IsArchive(string name) => ArchiveExtensions.Contains(Ext(name));
    public static bool IsRpf(string name) => Ext(name) == ".rpf";
    public static bool IsData(string name) => Ext(name) is ".meta" or ".xml" or ".dat";
    public static bool IsAudio(string name) => Ext(name) is ".awc" or ".rel" or ".nametable";

    /// <summary>書庫から取り出す価値のあるファイルか（手順書や画像は展開しない）。</summary>
    public static bool IsRelevant(string name) =>
        IsRpf(name) || IsStream(name) || IsArchive(name) || IsData(name) || IsAudio(name)
        || Ext(name) == ".gxt2";

    /// <summary>マップを構成する種類か（車や ped のモデルを含まない）。</summary>
    public static bool IsMapAsset(string name) =>
        Ext(name) is ".ymap" or ".ytyp" or ".ybn" or ".ydr" or ".ydd" or ".ytd" or ".ynv" or ".ycd" or ".ymf";

    //[ 部品をフォルダで持つ ped ]
    // 着せ替えできる ped は、<モデル名>.yft / .ymt の隣に <モデル名>/ フォルダ（小物は <モデル名>_p/）を
    // 持ち、その中に部品が入る。FiveM の stream/ はフォルダを見ないので、"フォルダ名^ファイル名" と
    // いう名前でこの関係を表す。

    /// <summary>
    /// stream/ に置くときのファイル名。ped の部品フォルダの中なら "フォルダ名^ファイル名"。
    /// </summary>
    /// <param name="path">'/' 区切りのパス</param>
    /// <param name="allPaths">同じ入力に含まれる全ファイル（小文字・'/' 区切り）</param>
    /// <summary>
    /// マップの目録は "_manifest.ymf" という名前でないと読まれない。下線を落とした名前で配る配布物があるので直す。
    /// </summary>
    public static string FixManifestName(string fileName) =>
        fileName.Equals("manifest.ymf", StringComparison.OrdinalIgnoreCase) ? "_manifest.ymf" : fileName;

    public static string StreamName(string path, ISet<string> allPaths)
    {
        var p = path.Replace('\\', '/').ToLowerInvariant();
        var slash = p.LastIndexOf('/');
        var name = FixManifestName(p[(slash + 1)..]);
        if (slash <= 0) return name;

        var dir = p[..slash];
        var dirSlash = dir.LastIndexOf('/');
        var folder = dir[(dirSlash + 1)..];
        var parent = dir[..(dirSlash + 1)];
        if (folder.EndsWith(".rpf", StringComparison.Ordinal)) return name;

        var model = folder.EndsWith("_p", StringComparison.Ordinal) ? folder[..^2] : folder;
        return allPaths.Contains(parent + model + ".yft") || allPaths.Contains(parent + model + ".ymt")
            ? folder + "^" + name
            : name;
    }

    private static string Ext(string name) => Path.GetExtension(name).ToLowerInvariant();

    /// <summary>
    /// content.xml に宣言が無い meta へ当てる種別。
    /// 名前から確実に決まるものだけを載せる（推測で宣言すると読み込み時に落ちるため）。
    /// </summary>
    public static readonly Dictionary<string, string> FallbackTypes = new(StringComparer.OrdinalIgnoreCase)
    {
        ["vehicles.meta"] = "VEHICLE_METADATA_FILE",
        ["carcols.meta"] = "CARCOLS_FILE",
        ["carvariations.meta"] = "VEHICLE_VARIATION_FILE",
        ["handling.meta"] = "HANDLING_FILE",
        ["vehiclelayouts.meta"] = "VEHICLE_LAYOUTS_FILE",
    };

    /// <summary>
    /// data_file の並び順。ここに無い種別は content.xml の順のまま後ろへ回す。
    ///
    /// CARCOLS_FILE を VEHICLE_VARIATION_FILE より後に置くと、ゲーム起動後の初回だけ
    /// 改造キットとサイレン設定が引けない（リソースを読み直すと直るので見落としやすい）。
    /// </summary>
    public static readonly string[] TypeOrder =
    {
        "VEHICLE_LAYOUTS_FILE",
        "HANDLING_FILE",
        "VEHICLE_METADATA_FILE",
        "CARCOLS_FILE",
        "VEHICLE_VARIATION_FILE",
    };

    /// <summary>FiveM の manifest へ書かない種別。</summary>
    public static bool IsSkippedType(string type) =>
        type is "RPF_FILE" or "RPF_FILE_PRE_INSTALL" or "TEXTFILE_METAFILE";

    public static bool IsAudioDataType(string type) =>
        type.StartsWith("AUDIO_", StringComparison.Ordinal) && type != "AUDIO_WAVEPACK";

    //[ RSC7 ヘッダの書き戻し ]
    //
    // rpf に格納されたリソースは、種別とページ構成をエントリ側の SystemFlags / GraphicsFlags が
    // 持っている。本体先頭 16 バイトは読まれないので、書き出したツールによっては RSC7 ヘッダが
    // 残っておらず、16MB 以上のものは実サイズの埋め込みで必ず潰れている。
    // 単体ファイルとして置く stream/ ではこのヘッダが読まれるので、エントリ側から組み直す。

    /// <summary>
    /// RSC7 のフラグが表すページの合計バイト数（展開後にメモリへ載る大きさ）。
    /// 実在パック 615 件で「展開後の長さ = System + Graphics の合計」と一致することを確認済み。
    /// </summary>
    public static long PageBytes(uint flags)
    {
        long pages =
            (((flags >> 27) & 0x1) << 0) + (((flags >> 26) & 0x1) << 1) +
            (((flags >> 25) & 0x1) << 2) + (((flags >> 24) & 0x1) << 3) +
            (((flags >> 17) & 0x7F) << 4) + (((flags >> 11) & 0x3F) << 5) +
            (((flags >> 7) & 0xF) << 6) + (((flags >> 5) & 0x3) << 7) +
            (((flags >> 4) & 0x1) << 8);
        return (0x200L << (int)(flags & 0xF)) * pages;
    }

    /// <summary>
    /// リソースがグラフィックメモリへ載せる大きさ。RSC7 でなければ 0。
    /// FiveM が「大きすぎる資産」として警告するのはファイルの大きさではなくこちら。
    /// </summary>
    public static long GraphicsBytes(byte[] data) =>
        data.Length >= 16 && Rpf7Format.ReadU32(data, 0) == Rpf7Format.Rsc7Magic
            ? PageBytes(Rpf7Format.ReadU32(data, 12))
            : 0;

    /// <summary>
    /// Enhanced（gen9）用の資産か。種類ごとにリソースの版が Legacy と違う
    /// （Legacy: ytd 13 / ydr・ydd 165 / yft 162 / ypt 68）。版だけでなく頂点・シェーダー・テクスチャの
    /// 持ち方も違うので、FiveM（Legacy のゲーム上で動く）は読めない。
    /// </summary>
    public static bool IsGen9(string name, uint version) => Ext(name) switch
    {
        ".ytd" => version == 5,
        ".ydr" or ".ydd" => version == 159,
        ".yft" => version == 171,
        ".ypt" => version == 71,
        _ => false,
    };

    public static uint ResourceVersion(uint systemFlags, uint graphicsFlags) =>
        (((systemFlags >> 28) & 0xF) << 4) | ((graphicsFlags >> 28) & 0xF);

    /// <summary>先頭 16 バイトを RSC7 ヘッダへ戻す。書き換えたら true。</summary>
    public static bool RestoreRsc7Header(byte[] data, uint systemFlags, uint graphicsFlags)
    {
        if (data.Length < 16) return false;

        var version = (((systemFlags >> 28) & 0xF) << 4) | ((graphicsFlags >> 28) & 0xF);

        if (Rpf7Format.ReadU32(data, 0) == Rpf7Format.Rsc7Magic
            && Rpf7Format.ReadU32(data, 4) == version
            && Rpf7Format.ReadU32(data, 8) == systemFlags
            && Rpf7Format.ReadU32(data, 12) == graphicsFlags)
            return false;

        Rpf7Format.WriteU32(data, 0, Rpf7Format.Rsc7Magic);
        Rpf7Format.WriteU32(data, 4, version);
        Rpf7Format.WriteU32(data, 8, systemFlags);
        Rpf7Format.WriteU32(data, 12, graphicsFlags);
        return true;
    }
}

