using KnExchange.Rpf7;

namespace KnExchange;

/// <summary>変換せずに、入力の中身と content.xml の宣言を並べる。CLI と画面の両方が使う。</summary>
public static class ModInspector
{
    public static void Inspect(string path, Action<string> log)
    {
        using var input = InputUnpacker.Open(path, log);
        var rpfs = Directory.EnumerateFiles(input.RootPath, "*.rpf", SearchOption.AllDirectories).ToList();

        if (rpfs.Count == 0)
        {
            log(Lang.T("rpf はありません。含まれるファイル:", "There is no rpf. Files inside:"));
            foreach (var f in Directory.EnumerateFiles(input.RootPath, "*", SearchOption.AllDirectories))
                log($"  {Path.GetRelativePath(input.RootPath, f)}  ({new FileInfo(f).Length:N0})");
            return;
        }

        foreach (var rpf in rpfs)
        {
            log("");
            log($"== {Path.GetRelativePath(input.RootPath, rpf)} ==");

            Rpf7Archive archive;
            try
            {
                archive = Rpf7Archive.Open(rpf);
            }
            catch (Exception ex) when (ex is NotSupportedException or InvalidDataException or EndOfStreamException)
            {
                log(Lang.T($"  読めません: {ex.Message}", $"  unreadable: {ex.Message}"));
                continue;
            }

            var files = RpfTree.Flatten(archive);
            foreach (var f in files)
            {
                var kind = f.Entry is Rpf7ResourceFileEntry ? "R" : "B";
                log($"  {kind} {f.Size,12:N0}  {f.Path}");
            }

            var content = files.FirstOrDefault(f => f.Path == "content.xml");
            var items = content != null ? ContentXml.Parse(content.Read(out _)) : null;
            if (items == null) continue;

            log(Lang.T("  -- content.xml の宣言 --", "  -- declared in content.xml --"));
            foreach (var item in items)
                log($"  {item.Type,-28} {item.Path}");
        }
    }

    /// <summary>変換結果 1 件ぶんの要約を書き出す。</summary>
    public static void Describe(ResourceReport r, Action<string> log)
    {
        log("");
        log($"== {r.Name} ==");
        log(Lang.T($"  出力先      : {r.OutputPath}", $"  output      : {r.OutputPath}"));
        log(Lang.T($"  stream      : {r.StreamCount} 件（ヘッダを書き戻したもの {r.HeadersRestored} 件）", $"  stream      : {r.StreamCount} file(s) ({r.HeadersRestored} with the header restored)"));
        log(Lang.T($"  data_file   : {r.DataFiles.Count} 件", $"  data_file   : {r.DataFiles.Count}"));
        foreach (var (type, path) in r.DataFiles)
            log($"    {type,-28} {path}");
        if (r.TextEntries > 0)
            log(Lang.T($"  表示名      : {r.TextEntries} 件（names.lua）", $"  names       : {r.TextEntries} (names.lua)"));
        if (r.Skipped.Count > 0)
            log(Lang.T($"  対象外      : {r.Skipped.Count} 件（{string.Join(", ", r.Skipped.Take(5))}{(r.Skipped.Count > 5 ? " ..." : "")}）", $"  skipped     : {r.Skipped.Count} ({string.Join(", ", r.Skipped.Take(5))}{(r.Skipped.Count > 5 ? " ..." : "")})"));
        foreach (var w in r.Warnings)
            log(Lang.T($"  [注意] {w}", $"  [note] {w}"));
        log($"  server.cfg  : ensure {r.Name}");
    }
}

