using System.Text;
using System.Xml;
using System.Xml.Linq;

namespace KnExchange;

/// <summary>
/// ped の定義（peds.meta）を作る。
///
/// gta5-mods の「Add-On Ped」は、モデル一式だけを配り、定義は AddonPeds などの
/// 別ツールに作らせる前提のものが多い。FiveM ではその定義を peds.meta として同梱する。
/// </summary>
public static class PedBuilder
{
    public sealed class Ped
    {
        public string Name { get; set; }
        public bool Female { get; set; }

        /// <summary>部品をフォルダで持つ種類（着せ替えできる ped）か。</summary>
        public bool Streamed { get; set; }

        public bool HasProps { get; set; }

        /// <summary>バニラの定義を写す元（置き換え型を別名にするとき）。無ければ既定の定義を使う。</summary>
        public XElement Source { get; set; }
        public string SourceName { get; set; }
    }

    /// <summary>バニラの ped と同じ命名か（置き換え型の見分けに使う）。</summary>
    public static bool LooksVanilla(string name) =>
        System.Text.RegularExpressions.Regex.IsMatch(name,
            @"^(a_[cfm]_|g_[fm]_|s_[fm]_|u_[fm]_|ig_|cs_|csb_|mp_[fmgs]_|hc_|player_(zero|one|two)$)");

    /// <summary>バニラの peds.meta から、その名前の定義を引く。</summary>
    public static XElement FindVanilla(string pedsMetaPath, string name) =>
        XDocument.Load(pedsMetaPath).Descendants("InitDatas").Elements("Item")
            .FirstOrDefault(i => string.Equals(((string)i.Element("Name"))?.Trim(), name, StringComparison.OrdinalIgnoreCase));

    public static HashSet<string> ReadNames(string pedsMetaPath) =>
        XDocument.Load(pedsMetaPath).Descendants("InitDatas").Elements("Item")
            .Select(i => ((string)i.Element("Name") ?? "").Trim().ToLowerInvariant())
            .Where(n => n.Length > 0)
            .ToHashSet();

    public static byte[] Build(IEnumerable<Ped> peds)
    {
        var root = new XElement("CPedModelInfo__InitDataList",
            new XElement("InitDatas", peds.Select(BuildItem)));

        using var ms = new MemoryStream();
        var settings = new XmlWriterSettings
        {
            Indent = true,
            Encoding = new UTF8Encoding(encoderShouldEmitUTF8Identifier: false),
        };
        using (var writer = XmlWriter.Create(ms, settings))
            new XDocument(new XDeclaration("1.0", "UTF-8", null), root).Save(writer);
        return ms.ToArray();
    }

    private static XElement BuildItem(Ped ped)
    {
        if (ped.Source != null)
        {
            var copy = new XElement(ped.Source);
            copy.SetElementValue("Name", ped.Name);

            var props = copy.Element("PropsName");
            if (props != null && string.Equals(props.Value.Trim(), ped.SourceName + "_p", StringComparison.OrdinalIgnoreCase))
                props.Value = ped.Name + "_p";
            return copy;
        }

        //[ 既定の定義 ]
        // Cfx.re フォーラムの手引き「[How-to] Stream add-on peds」が示す例と同じ項目・同じ値。
        // 書いていない項目はゲームの既定値になる。
        //
        // 姿勢の照合（PoseMatcherName）は女性でも Male を使う。ここに既存でない名前を書くと
        // 新しい枠が要り、枠が足りずにゲームが落ちる（PoseMatcherStore Pool Full）。
        var f = ped.Female;
        XElement Text(string name, string value) => new(name, value);

        var item = new XElement("Item", Text("Name", ped.Name));
        if (ped.HasProps) item.Add(Text("PropsName", ped.Name + "_p"));

        item.Add(
            Text("ClipDictionaryName", f ? "move_f@generic" : "move_m@generic"),
            Text("ExpressionSetName", f ? "expr_set_ambient_female" : "expr_set_ambient_male"),
            Text("Pedtype", f ? "CIVFEMALE" : "CIVMALE"),
            Text("MovementClipSet", f ? "move_f@generic" : "move_m@generic"),
            Text("StrafeClipSet", "move_ped_strafing"),
            Text("MovementToStrafeClipSet", "move_ped_to_strafe"),
            Text("InjuredStrafeClipSet", "move_strafe_injured"),
            Text("FullBodyDamageClipSet", "dam_ko"),
            Text("AdditiveDamageClipSet", "dam_ad"),
            Text("DefaultGestureClipSet", f ? "ANIM_GROUP_GESTURE_F_GENERIC" : "ANIM_GROUP_GESTURE_M_GENERIC"),
            Text("FacialClipsetGroupName", f ? "facial_clipset_group_gen_female" : "facial_clipset_group_gen_male"),
            Text("DefaultVisemeClipSet", f ? "ANIM_GROUP_VISEMES_F_LO" : "ANIM_GROUP_VISEMES_M_LO"),
            Text("PoseMatcherName", "Male"),
            Text("PoseMatcherProneName", "Male_prone"),
            Text("GetupSetHash", "NMBS_SLOW_GETUPS"),
            Text("CreatureMetadataName", "ambientPed_upperWrinkles"),
            Text("DecisionMakerName", "DEFAULT"),
            Text("MotionTaskDataSetName", "STANDARD_PED"),
            Text("DefaultTaskDataSetName", "STANDARD_PED"),
            Text("PedCapsuleName", f ? "STANDARD_FEMALE" : "STANDARD_MALE"),
            Text("RelationshipGroup", "CIVMALE"),
            Text("NavCapabilitiesName", "STANDARD_PED"),
            Text("PerceptionInfo", "DEFAULT_PERCEPTION"),
            Text("DefaultBrawlingStyle", "BS_AI"),
            Text("DefaultUnarmedWeapon", "WEAPON_UNARMED"),
            Text("Personality", "SERVICEMALES"),
            Text("CombatInfo", "DEFAULT"),
            Text("VfxInfoName", "VFXPEDINFO_HUMAN_GENERIC"),
            Text("AmbientClipsForFlee", "FLEE"),
            Text("AbilityType", "SAT_NONE"),
            Text("ThermalBehaviour", "TB_WARM"),
            Text("SuperlodType", "SLOD_HUMAN"),
            Text("ScenarioPopStreamingSlot", "SCENARIO_POP_STREAMING_NORMAL"),
            Text("DefaultSpawningPreference", "DSP_NORMAL"),
            new XElement("IsStreamedGfx", new XAttribute("value", ped.Streamed ? "true" : "false")));

        return item;
    }
}

