using System.IO.Compression;

namespace KnExchange.Rpf7;

/// <summary>
/// RPF7 アーカイブの読み取り。入れ子アーカイブも再帰的に辿る。
///
/// **ファイル全体をメモリに載せない。** mods/ には数 GB の rpf が置かれていることがあり
/// （実例: 2.6GB の車両 mod）、走査のたびに読み込むと現実的な時間で終わらない。
/// ヘッダだけをシークして読み、本体は必要になったときだけ読む。
///
/// 暗号化アーカイブ（AES / NG）は GTA5 のキーが要るため扱わない。
/// 本ツールはキーを一切持たないので、明確なメッセージで拒否する。
/// </summary>
public sealed class Rpf7Archive
{
    /// <summary>アーカイブ名。最上位はファイル名、入れ子は親エントリの名前。</summary>
    public string Name { get; }

    /// <summary>ディスク上の実ファイル。入れ子でも最上位のパスを指す。</summary>
    public string PhysicalPath { get; }

    /// <summary>実ファイル先頭からこのアーカイブ先頭までのバイト数。最上位は 0。</summary>
    public long StartPos { get; }

    /// <summary>このアーカイブのバイト数。</summary>
    public long Length { get; }

    public uint Encryption { get; private set; }

    public Rpf7DirectoryEntry Root { get; private set; }

    /// <summary>このアーカイブ直下の全エントリ（入れ子アーカイブの中身は含まない）。</summary>
    public List<Rpf7Entry> AllEntries { get; } = new();

    /// <summary>入れ子アーカイブ。</summary>
    public List<Rpf7Archive> Children { get; } = new();

    /// <summary>
    /// 入れ子を辿る深さの上限。
    /// 壊れた（あるいは細工された）ファイルで入れ子が延々と続く形になっていても、
    /// スタックを食い潰さずに止まるようにするための保険。
    /// 実際の構造は pack &gt; dlc &gt; streaming の 3 段しかない。
    /// </summary>
    private const int MaxNestingDepth = 16;

    private readonly int _depth;

    private Rpf7Archive(string name, string physicalPath, long startPos, long length, int depth = 0)
    {
        Name = name;
        PhysicalPath = physicalPath;
        StartPos = startPos;
        Length = length;
        _depth = depth;
    }

    public string GetPhysicalFilePath() => PhysicalPath;

    /// <summary>診断表示用に暗号化方式を人が読める形で返す。</summary>
    public static string DescribeEncryption(Rpf7Archive archive) =>
        Rpf7Format.DescribeEncryption(archive.Encryption);

    /// <summary>ファイルを開いて構造全体（入れ子を含む）を読み取る。</summary>
    public static Rpf7Archive Open(string path)
    {
        var info = new FileInfo(path);
        if (!info.Exists) throw new FileNotFoundException(Lang.T($"ファイルがありません: {path}", $"The file does not exist: {path}"), path);

        var archive = new Rpf7Archive(Path.GetFileName(path), path, 0, info.Length);
        using var fs = File.OpenRead(path);
        archive.ReadStructure(fs);
        return archive;
    }

    /// <summary>アーカイブ本体とその入れ子を再帰的に列挙する。</summary>
    public IEnumerable<Rpf7Archive> Walk()
    {
        yield return this;
        foreach (var child in Children)
            foreach (var d in child.Walk())
                yield return d;
    }

    /// <summary>名前でアーカイブを探す（入れ子を含む）。</summary>
    public Rpf7Archive FindArchive(string name) =>
        Walk().FirstOrDefault(a => string.Equals(a.Name, name, StringComparison.OrdinalIgnoreCase));

    /// <summary>直下のファイルを名前で引く。</summary>
    public Rpf7FileEntry FindRootFile(string nameLower) =>
        Root?.Files.FirstOrDefault(f => string.Equals(f.NameLower, nameLower, StringComparison.Ordinal));

    /// <summary>
    /// 格納されているバイト列を**そのまま**読み出す（展開しない）。
    /// リソースはこれがディスク上の .ydr 表現そのものになるので、元ファイルと SHA256 が一致する。
    /// </summary>
    public byte[] ReadRaw(Rpf7FileEntry entry)
    {
        using var fs = File.OpenRead(PhysicalPath);
        return ReadRaw(fs, entry);
    }

    /// <summary>開いてあるストリームから格納バイト列をそのまま読み出す。</summary>
    public byte[] ReadRaw(Stream stream, Rpf7FileEntry entry)
    {
        var length = entry switch
        {
            Rpf7ResourceFileEntry r => r.StoredLength,
            Rpf7BinaryFileEntry b => b.StoredLength,
            _ => entry.FileSize,
        };

        var offset = StartPos + (long)entry.FileOffset * Rpf7Format.SectorSize;
        return ReadExactly(stream, offset, length, entry.Name);
    }

    /// <summary>
    /// ファイルの中身を取り出す。バイナリで圧縮されているものは展開する。
    /// リソースは圧縮されていないので <see cref="ReadRaw(Rpf7FileEntry)"/> と同じ結果になる。
    /// </summary>
    public byte[] ExtractFile(Rpf7FileEntry entry)
    {
        var raw = ReadRaw(entry);

        if (entry is Rpf7BinaryFileEntry { IsStoredRaw: false } bin)
            return Inflate(raw, bin.UncompressedSize, entry.Name);

        return raw;
    }

    // ------------------------------------------------------------------
    // 構造の読み取り
    // ------------------------------------------------------------------

    private void ReadStructure(Stream stream)
    {
        var header = ReadExactly(stream, StartPos, Rpf7Format.HeaderSize, Name);

        var magic = Rpf7Format.ReadU32(header, 0);
        if (magic != Rpf7Format.Magic)
            throw new InvalidDataException(Lang.T($"RPF7 アーカイブではありません: {Name}", $"Not an RPF7 archive: {Name}"));

        var entryCount = Rpf7Format.ReadU32(header, 4);
        var namesLength = Rpf7Format.ReadU32(header, 8);
        Encryption = Rpf7Format.ReadU32(header, 12);

        if (Encryption != Rpf7Format.EncryptionOpen && Encryption != Rpf7Format.EncryptionNone)
            throw new NotSupportedException(
                Lang.T($"暗号化アーカイブ（{Rpf7Format.DescribeEncryption(Encryption)}）は読めません。" +
                "復号には GTA5 のキーが必要で、本ツールは保持していません。", $"Encrypted archives ({Rpf7Format.DescribeEncryption(Encryption)}) cannot be read. " +
                "Decrypting needs the GTA5 keys, which this tool does not carry."));

        if (entryCount == 0) return;

        // エントリ数と名前長は壊れたファイルだと巨大な値になりうる。読む前に上限を見る
        var tableBytes = (long)entryCount * Rpf7Format.EntrySize;
        if (tableBytes + namesLength + Rpf7Format.HeaderSize > Length)
            throw new InvalidDataException(
                Lang.T($"ヘッダがアーカイブサイズを超えています（壊れている可能性があります）: {Name}", $"The header is larger than the archive (it may be damaged): {Name}"));

        var entries = ReadExactly(stream, StartPos + Rpf7Format.HeaderSize, (uint)tableBytes, Name);
        var names = ReadExactly(stream, StartPos + Rpf7Format.HeaderSize + tableBytes, namesLength, Name);

        // --- エントリを素の形で読む ---
        var raw = new (ushort NameOffset, uint Size, uint Offset, uint A, uint B)[entryCount];
        for (var i = 0; i < entryCount; i++)
        {
            var o = i * Rpf7Format.EntrySize;
            raw[i] = (
                Rpf7Format.ReadU16(entries, o),
                Rpf7Format.ReadU24(entries, o + 2),
                Rpf7Format.ReadU24(entries, o + 5),
                Rpf7Format.ReadU32(entries, o + 8),
                Rpf7Format.ReadU32(entries, o + 12));
        }

        // --- 木を組み立てる ---
        // エントリ 0 が必ずルート。ディレクトリは「最初の子の番号 + 子の数」で子を指す。
        var built = new Rpf7Entry[entryCount];
        var childRange = new (uint Index, uint Count)[entryCount];

        for (var i = 0; i < entryCount; i++)
        {
            var (nameOffset, size, offset, a, b) = raw[i];
            var name = ReadName(names, nameOffset);

            if (offset == Rpf7Format.DirectoryMarker)
            {
                built[i] = new Rpf7DirectoryEntry();
                childRange[i] = (a, b);
            }
            else if ((offset & Rpf7Format.ResourceFlag) != 0)
            {
                built[i] = new Rpf7ResourceFileEntry
                {
                    FileOffset = offset & ~Rpf7Format.ResourceFlag,
                    FileSize = size,
                    SystemFlags = a,
                    GraphicsFlags = b,
                };
            }
            else
            {
                built[i] = new Rpf7BinaryFileEntry
                {
                    FileOffset = offset,
                    FileSize = size,
                    UncompressedSize = a,
                    EncryptedFlag = b,
                };
            }

            built[i].Name = name;
            built[i].NameLower = name.ToLowerInvariant();
            AllEntries.Add(built[i]);
        }

        for (var i = 0; i < entryCount; i++)
        {
            if (built[i] is not Rpf7DirectoryEntry dir) continue;

            var (index, count) = childRange[i];
            for (uint c = 0; c < count; c++)
            {
                var childIndex = index + c;
                // 壊れたアーカイブで範囲外を指していても落とさない
                if (childIndex >= entryCount) break;

                switch (built[childIndex])
                {
                    case Rpf7DirectoryEntry d: dir.Directories.Add(d); break;
                    case Rpf7FileEntry f: dir.Files.Add(f); break;
                }
            }
        }

        Root = built[0] as Rpf7DirectoryEntry;

        // --- 16MB 以上のリソースは実サイズを本体先頭から復元する ---
        foreach (var res in AllEntries.OfType<Rpf7ResourceFileEntry>())
        {
            if (!res.IsLarge) continue;

            var offset = StartPos + (long)res.FileOffset * Rpf7Format.SectorSize;
            var head = ReadExactly(stream, offset, 16, res.Name);
            res.LargeSize = Rpf7Format.ReadLargeResourceSize(head);

            if (res.LargeSize < Rpf7Format.MaxU24)
                throw new InvalidDataException(
                    Lang.T($"{res.Name}: 16MB 以上のはずのリソースから妥当なサイズを復元できませんでした。", $"{res.Name}: could not recover a valid size for a resource that should be 16 MB or larger."));
        }

        // --- 入れ子アーカイブ ---
        // 無圧縮で格納されたバイナリの先頭が RPF7 なら、それは入れ子アーカイブ。
        if (_depth >= MaxNestingDepth) return;

        foreach (var entry in AllEntries.OfType<Rpf7BinaryFileEntry>())
        {
            if (!entry.IsStoredRaw || entry.StoredLength < Rpf7Format.HeaderSize) continue;

            var offset = StartPos + (long)entry.FileOffset * Rpf7Format.SectorSize;

            //[ 自分自身を指す入れ子を弾く ]
            // 壊れたファイルで格納位置が 0 になっていると、子が親と同じ位置を指し、
            // 同じ構造を延々と読み続けてスタックが尽きる。
            if (offset <= StartPos) continue;

            var peek = ReadExactly(stream, offset, 4, entry.Name);
            if (Rpf7Format.ReadU32(peek, 0) != Rpf7Format.Magic) continue;

            var child = new Rpf7Archive(entry.Name, PhysicalPath, offset, entry.StoredLength, _depth + 1);
            child.ReadStructure(stream);
            Children.Add(child);
        }
    }

    private static string ReadName(byte[] names, int offset)
    {
        if (offset < 0 || offset >= names.Length) return "";

        var end = offset;
        while (end < names.Length && names[end] != 0) end++;

        return System.Text.Encoding.UTF8.GetString(names, offset, end - offset);
    }

    private static byte[] ReadExactly(Stream stream, long offset, uint length, string what)
    {
        // 壊れたエントリの長さ（最大 4GB）をそのまま確保しない。ファイルに収まらないなら読む前に止める
        if (offset < 0 || offset + length > stream.Length)
            throw new EndOfStreamException(
                Lang.T($"{what}: オフセット {offset} から {length} バイト読めませんでした。", $"{what}: could not read {length} bytes from offset {offset}."));

        var buffer = new byte[length];
        stream.Position = offset;

        var read = 0;
        while (read < buffer.Length)
        {
            var n = stream.Read(buffer, read, buffer.Length - read);
            if (n == 0)
                throw new EndOfStreamException(
                    Lang.T($"{what}: オフセット {offset} から {length} バイト読めませんでした。", $"{what}: could not read {length} bytes from offset {offset}."));
            read += n;
        }
        return buffer;
    }

    private static byte[] Inflate(byte[] compressed, uint expected, string what)
    {
        try
        {
            using var input = new MemoryStream(compressed);
            // ヘッダ無しの raw deflate。ZLibStream ではなく DeflateStream を使う
            using var deflate = new DeflateStream(input, CompressionMode.Decompress);
            using var output = new MemoryStream(expected > 0 ? (int)expected : 0);
            deflate.CopyTo(output);
            return output.ToArray();
        }
        catch (Exception ex)
        {
            throw new InvalidDataException(Lang.T($"{what}: 展開に失敗しました。", $"{what}: decompression failed."), ex);
        }
    }
}

