namespace KnExchange.Rpf7;

/// <summary>RPF7 アーカイブ内のエントリ（ディレクトリまたはファイル）。</summary>
public abstract class Rpf7Entry
{
    /// <summary>名前ブロックに格納されていた名前。ルートは空文字列。</summary>
    public string Name { get; internal set; } = "";

    /// <summary>小文字化した名前。RPF 内の名前は元から小文字だが、比較を確実にするため持つ。</summary>
    public string NameLower { get; internal set; } = "";

    public override string ToString() => Name;
}

/// <summary>ディレクトリエントリ。</summary>
public sealed class Rpf7DirectoryEntry : Rpf7Entry
{
    public List<Rpf7DirectoryEntry> Directories { get; } = new();
    public List<Rpf7FileEntry> Files { get; } = new();
}

/// <summary>ファイルエントリ。</summary>
public abstract class Rpf7FileEntry : Rpf7Entry
{
    /// <summary>アーカイブ先頭からの格納位置（512 バイトセクタ単位）。</summary>
    public uint FileOffset { get; internal set; }

    /// <summary>
    /// アーカイブに格納されているバイト数。
    /// バイナリなら圧縮後のサイズ（0 なら無圧縮でそのまま格納）、リソースならファイル全体のサイズ。
    /// </summary>
    public uint FileSize { get; internal set; }
}

/// <summary>
/// バイナリファイル（RSC7 ヘッダを持たないもの）。
/// 既定では raw deflate で圧縮して格納される。入れ子アーカイブなど、
/// ゲーム側がその場で読む必要があるものは無圧縮（<see cref="Rpf7FileEntry.FileSize"/> = 0）で格納される。
/// </summary>
public sealed class Rpf7BinaryFileEntry : Rpf7FileEntry
{
    /// <summary>展開後のサイズ。無圧縮格納のときは格納バイト数そのもの。</summary>
    public uint UncompressedSize { get; internal set; }

    /// <summary>暗号化フラグ。無暗号アーカイブでは 0。</summary>
    public uint EncryptedFlag { get; internal set; }

    /// <summary>無圧縮でそのまま格納されているか。</summary>
    public bool IsStoredRaw => FileSize == 0;

    /// <summary>実際にアーカイブ上を占めるバイト数。</summary>
    public uint StoredLength => IsStoredRaw ? UncompressedSize : FileSize;
}

/// <summary>
/// リソースファイル（RSC7 ヘッダを持つ .ydr / .ytd / .yft / .ycd / .ytyp 等）。
/// 常に無圧縮のまま格納され、SystemFlags / GraphicsFlags は RSC7 ヘッダの値がそのまま入る。
/// </summary>
public sealed class Rpf7ResourceFileEntry : Rpf7FileEntry
{
    public uint SystemFlags { get; internal set; }
    public uint GraphicsFlags { get; internal set; }

    /// <summary>
    /// 16MB 以上のリソースの実サイズ。
    ///
    /// エントリのサイズ欄は 24bit しかないため、16MB 以上になると 0xFFFFFF で飽和し、
    /// 実サイズは**格納バイト列の先頭 16 バイト**へ次のように分けて埋め込まれる:
    ///   長さ = b[7] | b[14]&lt;&lt;8 | b[5]&lt;&lt;16 | b[2]&lt;&lt;24
    ///
    /// 実在する大型 mod（2.6GB の道路 mod）で確認済み。復元した長さから求めた
    /// 次セクタ位置が、実際の次ファイルの位置と完全に一致することを確認した。
    /// </summary>
    public uint LargeSize { get; internal set; }

    /// <summary>サイズ欄が飽和していて、実サイズを本体先頭から復元したか。</summary>
    public bool IsLarge => FileSize >= Rpf7Format.MaxU24;

    /// <summary>実際にアーカイブ上を占めるバイト数。</summary>
    public uint StoredLength => IsLarge ? LargeSize : FileSize;
}

