const GTA_CRS = L.extend({}, L.CRS.Simple, {
  projection: L.Projection.LonLat,
  scale: (zoom) => Math.pow(2, zoom),
  zoom: (scale) => Math.log(scale) / Math.LN2,
  transformation: new L.Transformation(0.02072, 117.3, -0.0205, 172.8),
  infinite: true,
});

function toLatLng(x, y) {
  return L.latLng(y, x);
}

function toGame(latlng) {
  return { x: latlng.lng, y: latlng.lat };
}

const TILE_SIZE = 256;
const MAP_SIZE = 8192;
const NATIVE_ZOOM = 5;

const map = L.map('map', {
  crs: GTA_CRS,
  minZoom: 2,
  maxZoom: 6,
  zoomControl: false,
  preferCanvas: true,
});

const worldBounds = L.latLngBounds(
  map.unproject([0, MAP_SIZE], NATIVE_ZOOM),
  map.unproject([MAP_SIZE, 0], NATIVE_ZOOM),
);

const styles = [
  { name: 'Atlas', url: 'https://assets.fivedock.dev/maps/styleatlas/{z}/{x}/{y}.jpg', sea: '#0fa8d2' },
  { name: 'Satellite', url: 'https://assets.fivedock.dev/maps/stylesatelite/{z}/{x}/{y}.jpg', sea: '#153e6a' },
  { name: 'Grid', url: 'https://assets.fivedock.dev/maps/stylegrid/{z}/{x}/{y}.png', sea: '#8f8f8f' },
];

const tileLayers = {};
for (const style of styles) {
  tileLayers[style.name] = L.tileLayer(style.url, {
    tileSize: TILE_SIZE,
    minZoom: 0,
    maxZoom: 6,
    maxNativeZoom: NATIVE_ZOOM,
    bounds: worldBounds,
    attribution: 'Map © Rockstar Games',
  });
}

function applyStyle(name) {
  const style = styles.find((s) => s.name === name) ?? styles[0];
  map.getContainer().style.background = style.sea;
  localStorage.setItem('mapStyle', style.name);
  return style;
}

tileLayers[applyStyle(localStorage.getItem('mapStyle')).name].addTo(map);
const layersControl = L.control.layers(tileLayers, null, { collapsed: false }).addTo(map);
map.on('baselayerchange', (event) => applyStyle(event.name));

map.setMaxBounds(worldBounds.pad(0.1));
map.setView(toLatLng(0, 0), 3);

const blips = [
  { label: 'Mission Row PD', x: 441.0, y: -982.0, color: '#3b82f6' },
  { label: 'Pillbox Hill Medical', x: 298.6, y: -584.5, color: '#ef4444' },
  { label: 'LSIA', x: -1037.0, y: -2737.0, color: '#f59e0b' },
];

for (const blip of blips) {
  L.circleMarker(toLatLng(blip.x, blip.y), {
    radius: 6,
    color: '#ffffff',
    weight: 2,
    fillColor: blip.color,
    fillOpacity: 1,
  })
    .bindTooltip(blip.label)
    .addTo(map);
}

const mapElement = document.getElementById('map');
let player = null;
let followPlayer = true;

window.addEventListener('message', (event) => {
  const data = event.data;

  if (data.action === 'open') {
    mapElement.classList.add('open');
    map.invalidateSize();
    layersControl.expand();
    followPlayer = true;
  }

  if (data.action === 'close') {
    mapElement.classList.remove('open');
  }

  if (data.action === 'player') {
    const position = toLatLng(data.x, data.y);
    if (player) {
      player.setLatLng(position);
    } else {
      player = L.circleMarker(position, {
        radius: 7,
        color: '#ffffff',
        weight: 2,
        fillColor: '#22c55e',
        fillOpacity: 1,
      }).addTo(map);
    }
    if (followPlayer) map.panTo(position, { animate: false });
  }
});

map.on('dragstart', () => {
  followPlayer = false;
});

const route = [
  [441.0, -982.0],
  [402.0, -860.0],
  [298.6, -584.5],
];

L.polyline(
  route.map(([x, y]) => toLatLng(x, y)),
  { color: '#22c55e', weight: 4, opacity: 0.9 },
).addTo(map);

L.circle(toLatLng(441.0, -982.0), {
  radius: 80,
  color: '#3b82f6',
  fillOpacity: 0.15,
}).addTo(map);

function post(name, body) {
  return fetch(`https://${GetParentResourceName()}/${name}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json; charset=UTF-8' },
    body: JSON.stringify(body),
  });
}

map.on('click', (event) => {
  post('mapClick', toGame(event.latlng));
});

document.addEventListener('keydown', (event) => {
  if (event.key === 'Escape') post('close', {});
});

