namespace KnExchange.Rpf7;

/// <summary>
/// RPF7 アーカイブ形式の定数と、読み書きで共有する小さなヘルパー。
///
/// この実装は **GTA5 の実ファイルと本ツールの生成物をバイト単位で解析して起こした**もので、
/// 第三者のコードは一切含まない。仕様の根拠は以下のとおり:
///
/// アーカイブ先頭 16 バイト:
///   +0  u32  マジック 0x52504637（ディスク上は "7FPR"）
///   +4  u32  エントリ数
///   +8  u32  名前ブロックの長さ（16 バイト境界に切り上げ済み）
///   +12 u32  暗号化方式。OPEN = 0x4E45504F（ディスク上は "OPEN"）
///
/// 続いてエントリが 16 バイト固定長で並び、その後ろに名前ブロック（NUL 区切り）が続く。
///
/// エントリ 16 バイトの内訳:
///   +0  u16  名前ブロック内オフセット
///   +2  u24  格納サイズ
///   +5  u24  格納位置（512 バイトセクタ単位）＋種別ビット
///   +8  u32  種別により意味が変わる
///   +12 u32  種別により意味が変わる
///
/// 種別の判別は +5 の u24 で行う:
///   0x7FFFFF          … ディレクトリ。+8 = 最初の子のエントリ番号、+12 = 子の数
///   0x800000 ビット有 … リソース。+8 = SystemFlags、+12 = GraphicsFlags
///                        （どちらも RSC7 ヘッダの +8 / +12 をそのまま転記したもの）
///   それ以外          … バイナリ。+8 = 展開後サイズ、+12 = 暗号化フラグ
///                        格納サイズ 0 は「無圧縮でそのまま格納」を意味する
///
/// 圧縮は **ヘッダ無しの raw deflate**。ファイル本体は必ず 512 バイト境界から始まる。
/// </summary>
public static class Rpf7Format
{
    /// <summary>アーカイブ先頭のマジック。ディスク上のバイト列は "7FPR"。</summary>
    public const uint Magic = 0x52504637;

    /// <summary>無暗号アーカイブ。ディスク上のバイト列は "OPEN"。</summary>
    public const uint EncryptionOpen = 0x4E45504F;

    public const uint EncryptionNone = 0x00000000;
    public const uint EncryptionAes  = 0x0FFFFFF9;
    public const uint EncryptionNg   = 0x0FEFFFFF;

    /// <summary>リソースファイルの先頭マジック 'RSC7'。</summary>
    public const uint Rsc7Magic = 0x37435352;

    public const int SectorSize = 512;
    public const int EntrySize = 16;
    public const int HeaderSize = 16;

    /// <summary>+5 の u24 がこの値ならディレクトリ。</summary>
    public const uint DirectoryMarker = 0x7FFFFF;

    /// <summary>+5 の u24 にこのビットが立っていればリソース。</summary>
    public const uint ResourceFlag = 0x800000;

    /// <summary>u24 に収まる最大値。ファイルサイズがこれ以上だと別の持ち方になる。</summary>
    public const uint MaxU24 = 0xFFFFFF;

    /// <summary>バイト数を 512 バイトセクタ数へ切り上げる。</summary>
    public static long SectorsFor(long byteCount) =>
        (byteCount + SectorSize - 1) / SectorSize;

    /// <summary>名前ブロックの長さは 16 バイト境界へ切り上げて格納される。</summary>
    public static int PadNamesLength(int actual) => (actual + 15) / 16 * 16;

    public static bool IsResource(ReadOnlySpan<byte> data) =>
        data.Length >= 16 && ReadU32(data, 0) == Rsc7Magic;

    public static bool IsArchive(ReadOnlySpan<byte> data) =>
        data.Length >= 16 && ReadU32(data, 0) == Magic;

    public static uint ReadU32(ReadOnlySpan<byte> b, int offset) =>
        (uint)(b[offset] | (b[offset + 1] << 8) | (b[offset + 2] << 16) | (b[offset + 3] << 24));

    public static ushort ReadU16(ReadOnlySpan<byte> b, int offset) =>
        (ushort)(b[offset] | (b[offset + 1] << 8));

    public static uint ReadU24(ReadOnlySpan<byte> b, int offset) =>
        (uint)(b[offset] | (b[offset + 1] << 8) | (b[offset + 2] << 16));

    public static void WriteU32(Span<byte> b, int offset, uint v)
    {
        b[offset]     = (byte)(v & 0xFF);
        b[offset + 1] = (byte)((v >> 8) & 0xFF);
        b[offset + 2] = (byte)((v >> 16) & 0xFF);
        b[offset + 3] = (byte)((v >> 24) & 0xFF);
    }

    public static void WriteU16(Span<byte> b, int offset, ushort v)
    {
        b[offset]     = (byte)(v & 0xFF);
        b[offset + 1] = (byte)((v >> 8) & 0xFF);
    }

    public static void WriteU24(Span<byte> b, int offset, uint v)
    {
        b[offset]     = (byte)(v & 0xFF);
        b[offset + 1] = (byte)((v >> 8) & 0xFF);
        b[offset + 2] = (byte)((v >> 16) & 0xFF);
    }

    //[ 16MB 以上のリソースのサイズ ]
    //
    // エントリのサイズ欄は u24 なので 16MB 以上を表せない。この場合サイズ欄は 0xFFFFFF で
    // 飽和し、実サイズは**格納バイト列の先頭 16 バイト**の 4 箇所へ分けて埋め込まれる。
    //
    // 実在する 2.6GB の道路 mod（16MB 超リソース 33 件）で確認した。復元した長さから
    // 求めた次セクタ位置が、実際の次ファイルの位置と完全に一致する。
    // 例: 21,434,030 バイト → 402857 + 41864 = 444721（実際の次ファイルと一致）
    //
    // この領域は RPF に格納されたリソースでは読まれない。リソースの種別とページ構成は
    // エントリ側の SystemFlags / GraphicsFlags が持っているため、本体先頭の RSC7 ヘッダは
    // 冗長で、上書きしても差し支えない（上記 mod は実際に上書きされた状態で動作している）。

    /// <summary>格納バイト列の先頭からリソースの実サイズを復元する。</summary>
    public static uint ReadLargeResourceSize(ReadOnlySpan<byte> stored) =>
        (uint)(stored[7] | (stored[14] << 8) | (stored[5] << 16) | (stored[2] << 24));

    /// <summary>格納バイト列の先頭へリソースの実サイズを書き込む。</summary>
    public static void WriteLargeResourceSize(Span<byte> stored, uint length)
    {
        stored[7]  = (byte)((length >> 0) & 0xFF);
        stored[14] = (byte)((length >> 8) & 0xFF);
        stored[5]  = (byte)((length >> 16) & 0xFF);
        stored[2]  = (byte)((length >> 24) & 0xFF);
    }

    public static string DescribeEncryption(uint value) => value switch
    {
        EncryptionOpen => "OPEN",
        EncryptionNone => "NONE",
        EncryptionAes  => "AES",
        EncryptionNg   => "NG",
        _ => $"0x{value:X8}",
    };
}

