using System.Xml.Linq;
using KnExchange.Rpf7;

namespace KnExchange;

/// <summary>rpf 内の 1 ファイル。入れ子アーカイブをまたいだ通しのパスを持つ。</summary>
public sealed class RpfFile
{
    /// <summary>最上位からのパス（小文字・"/" 区切り）。入れ子は "x64/vehicles.rpf/foo.yft" の形。</summary>
    public string Path { get; init; }
    public string Name { get; init; }
    public Rpf7Archive Archive { get; init; }
    public Rpf7FileEntry Entry { get; init; }

    /// <summary>直近の入れ子アーカイブの名前（拡張子なし）。最上位直下なら null。</summary>
    public string ContainerName { get; init; }

    public long Size => Entry switch
    {
        Rpf7ResourceFileEntry r => r.StoredLength,
        Rpf7BinaryFileEntry b => b.UncompressedSize,
        _ => Entry.FileSize,
    };

    /// <summary>単体ファイルとして置ける形で取り出す。</summary>
    public byte[] Read(out bool headerRestored)
    {
        var data = Archive.ExtractFile(Entry);
        headerRestored = Entry is Rpf7ResourceFileEntry res
            && ModFormats.RestoreRsc7Header(data, res.SystemFlags, res.GraphicsFlags);
        return data;
    }
}

/// <summary>rpf を入れ子ごと平らに並べる。</summary>
public static class RpfTree
{
    public static List<RpfFile> Flatten(Rpf7Archive root)
    {
        var result = new List<RpfFile>();
        Visit(root, root.Root, "", null, result);
        return result;
    }

    private static void Visit(Rpf7Archive archive, Rpf7DirectoryEntry dir, string prefix,
        string container, List<RpfFile> result)
    {
        if (dir == null) return;

        foreach (var file in dir.Files)
        {
            var path = prefix + file.NameLower;

            // 入れ子アーカイブは格納位置で突き合わせる（同名の rpf が別の場所にあっても取り違えない）
            var start = archive.StartPos + (long)file.FileOffset * Rpf7Format.SectorSize;
            var child = archive.Children.FirstOrDefault(c => c.StartPos == start);
            if (child != null)
            {
                Visit(child, child.Root, path + "/",
                    System.IO.Path.GetFileNameWithoutExtension(file.NameLower), result);
                continue;
            }

            result.Add(new RpfFile
            {
                Path = path,
                Name = file.NameLower,
                Archive = archive,
                Entry = file,
                ContainerName = container,
            });
        }

        foreach (var sub in dir.Directories)
            Visit(archive, sub, prefix + sub.NameLower + "/", container, result);
    }
}

/// <summary>content.xml の dataFiles 宣言 1 件。</summary>
public sealed record ContentItem(string Path, string Type);

public static class ContentXml
{
    /// <summary>
    /// dataFiles を宣言順に読む。壊れていれば null（呼び出し側は名前からの既定表へ回る）。
    /// </summary>
    public static List<ContentItem> Parse(byte[] xml)
    {
        try
        {
            using var ms = new MemoryStream(xml);
            var doc = XDocument.Load(ms);

            return doc.Descendants("dataFiles").Elements("Item")
                .Select(i => new ContentItem(
                    NormalizePath((string)i.Element("filename")),
                    ((string)i.Element("fileType") ?? "").Trim()))
                .Where(i => i.Path.Length > 0 && i.Type.Length > 0)
                .ToList();
        }
        catch (Exception)
        {
            return null;
        }
    }

    /// <summary>"dlc_foo:/%PLATFORM%/data/x.meta" → "x64/data/x.meta"</summary>
    public static string NormalizePath(string filename)
    {
        if (string.IsNullOrWhiteSpace(filename)) return "";

        var p = filename.Trim().Replace('\\', '/').ToLowerInvariant();

        var device = p.IndexOf(":/", StringComparison.Ordinal);
        if (device >= 0) p = p[(device + 2)..];

        return p.Replace("%platform%", "x64").TrimStart('/');
    }

    /// <summary>setup2.xml の deviceName。読めなければ null。</summary>
    public static string ReadDeviceName(byte[] xml)
    {
        try
        {
            using var ms = new MemoryStream(xml);
            return ((string)XDocument.Load(ms).Descendants("deviceName").FirstOrDefault())?.Trim();
        }
        catch (Exception)
        {
            return null;
        }
    }
}

/// <summary>
/// .gxt2（表示名の表）を読む。
///
/// FiveM は gxt2 を data_file として読めないので、車名などを出すには
/// 中身を AddTextEntryByHash へ流すスクリプトに直す必要がある。
///
/// 形式: "2TXG" / 件数 / (ハッシュ, 文字列の位置) × 件数 / "2TXG" / 終端位置 / NUL 終端の UTF-8
/// </summary>
public static class Gxt2
{
    private const uint Magic = 0x47585432; // ディスク上は "2TXG"

    public static List<(uint Hash, string Text)> Parse(byte[] data)
    {
        if (data.Length < 8 || Rpf7Format.ReadU32(data, 0) != Magic) return null;

        var count = Rpf7Format.ReadU32(data, 4);
        if (8 + (long)count * 8 > data.Length) return null;

        var result = new List<(uint, string)>();
        for (var i = 0; i < count; i++)
        {
            var hash = Rpf7Format.ReadU32(data, 8 + i * 8);
            var offset = Rpf7Format.ReadU32(data, 12 + i * 8);
            if (offset >= data.Length) return null;

            var end = (int)offset;
            while (end < data.Length && data[end] != 0) end++;

            result.Add((hash, System.Text.Encoding.UTF8.GetString(data, (int)offset, end - (int)offset)));
        }
        return result;
    }
}

