using System.IO;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;

namespace KnExchange.Gui;

/// <summary>
/// アプリのアイコン（角丸の四角 + 行き来する 2 本の矢印）。外部の画像を持たずに描く。
/// 配色に依らず常にダーク版。描いた結果は assets/kn_exchange.ico に置いてある。
/// </summary>
public static class AppIcon
{
    private static readonly int[] Sizes = { 16, 24, 32, 48, 64, 128, 256 };

    public static void Save(string path)
    {
        var images = Sizes.Select(Png).ToList();

        using var file = File.Create(path);
        using var w = new BinaryWriter(file);
        w.Write((ushort)0);
        w.Write((ushort)1);
        w.Write((ushort)images.Count);

        var offset = 6 + 16 * images.Count;
        for (var i = 0; i < images.Count; i++)
        {
            w.Write((byte)(Sizes[i] == 256 ? 0 : Sizes[i]));
            w.Write((byte)(Sizes[i] == 256 ? 0 : Sizes[i]));
            w.Write((byte)0);
            w.Write((byte)0);
            w.Write((ushort)1);
            w.Write((ushort)32);
            w.Write((uint)images[i].Length);
            w.Write((uint)offset);
            offset += images[i].Length;
        }

        foreach (var image in images) w.Write(image);
    }

    private static byte[] Png(int size)
    {
        double s = size;
        var visual = new DrawingVisual();
        using (var dc = visual.RenderOpen())
        {
            dc.DrawRoundedRectangle(new SolidColorBrush(Palette.Get("Surface2")), null, new Rect(0, 0, s, s), s * 0.24, s * 0.24);

            var pen = new Pen(new SolidColorBrush(Palette.Get("Accent")), Math.Max(1.5, s * 0.09))
            {
                StartLineCap = PenLineCap.Round, EndLineCap = PenLineCap.Round, LineJoin = PenLineJoin.Round,
            };

            // 上: 右向き、下: 左向き
            Arrow(dc, pen, s, 0.36, 0.24, 0.76);
            Arrow(dc, pen, s, 0.64, 0.76, 0.24);
        }

        var bitmap = new RenderTargetBitmap(size, size, 96, 96, PixelFormats.Pbgra32);
        bitmap.Render(visual);
        var encoder = new PngBitmapEncoder();
        encoder.Frames.Add(BitmapFrame.Create(bitmap));
        using var ms = new MemoryStream();
        encoder.Save(ms);
        return ms.ToArray();
    }

    private static void Arrow(DrawingContext dc, Pen pen, double s, double y, double from, double to)
    {
        var head = 0.13 * Math.Sign(from - to);
        dc.DrawLine(pen, new Point(s * from, s * y), new Point(s * to, s * y));

        var geometry = new StreamGeometry();
        using (var g = geometry.Open())
        {
            g.BeginFigure(new Point(s * (to + head), s * (y - 0.13)), false, false);
            g.LineTo(new Point(s * to, s * y), true, true);
            g.LineTo(new Point(s * (to + head), s * (y + 0.13)), true, true);
        }
        dc.DrawGeometry(null, pen, geometry);
    }
}

