export const MAP_STYLES = [
  { name: 'Atlas', url: 'https://assets.fivedock.dev/maps/styleatlas/{z}/{x}/{y}.jpg', sea: '#0fa8d2' },
  { name: 'Satellite', url: 'https://assets.fivedock.dev/maps/stylesatelite/{z}/{x}/{y}.jpg', sea: '#153e6a' },
  { name: 'Grid', url: 'https://assets.fivedock.dev/maps/stylegrid/{z}/{x}/{y}.png', sea: '#8f8f8f' },
];

export function savedStyle() {
  return MAP_STYLES.find((style) => style.name === localStorage.getItem('mapStyle')) ?? MAP_STYLES[0];
}

export function saveStyle(name) {
  const style = MAP_STYLES.find((s) => s.name === name) ?? MAP_STYLES[0];
  localStorage.setItem('mapStyle', style.name);
  return style;
}

export const TILE_SIZE = 256;
export const MAP_SIZE = 8192;
export const NATIVE_ZOOM = 5;

export const GTA_CRS = L.extend({}, L.CRS.Simple, {
  projection: L.Projection.LonLat,
  scale: (zoom) => 2 ** zoom,
  zoom: (scale) => Math.log2(scale),
  transformation: new L.Transformation(0.02072, 117.3, -0.0205, 172.8),
  infinite: true,
});

export function toLatLng(x, y) {
  return L.latLng(y, x);
}

export function toGame(latlng) {
  return { x: latlng.lng, y: latlng.lat };
}

const unproject = (x, y) => GTA_CRS.pointToLatLng(L.point(x, y), NATIVE_ZOOM);

export const WORLD_BOUNDS = L.latLngBounds(unproject(0, MAP_SIZE), unproject(MAP_SIZE, 0));

