using System.Windows;
using System.Windows.Controls;
using System.Windows.Documents;

namespace KnExchange.Gui;

/// <summary>
/// XAML の部品に文言の名前を付ける。言語を切り替えたら Refresh() で入れ直す。
///   Loc.Key  … 表示する文字（TextBlock / Run / ボタン類）
///   Loc.Hint … 入力欄が空の時に薄く見せる文字（TextBox の Tag）
/// </summary>
public static class Loc
{
    private static readonly List<(WeakReference<DependencyObject> Target, string Key, bool Hint)> Items = new();

    public static readonly DependencyProperty KeyProperty = DependencyProperty.RegisterAttached(
        "Key", typeof(string), typeof(Loc), new PropertyMetadata(null, (d, e) => Register(d, (string)e.NewValue, false)));

    public static readonly DependencyProperty HintProperty = DependencyProperty.RegisterAttached(
        "Hint", typeof(string), typeof(Loc), new PropertyMetadata(null, (d, e) => Register(d, (string)e.NewValue, true)));

    public static void SetKey(DependencyObject d, string value) => d.SetValue(KeyProperty, value);
    public static string GetKey(DependencyObject d) => (string)d.GetValue(KeyProperty);
    public static void SetHint(DependencyObject d, string value) => d.SetValue(HintProperty, value);
    public static string GetHint(DependencyObject d) => (string)d.GetValue(HintProperty);

    private static void Register(DependencyObject target, string key, bool hint)
    {
        if (string.IsNullOrEmpty(key)) return;
        Items.Add((new WeakReference<DependencyObject>(target), key, hint));
        Apply(target, key, hint);
    }

    public static void Refresh()
    {
        Items.RemoveAll(i => !i.Target.TryGetTarget(out _));
        foreach (var (target, key, hint) in Items)
            if (target.TryGetTarget(out var d))
                Apply(d, key, hint);
    }

    private static void Apply(DependencyObject target, string key, bool hint)
    {
        var text = Strings.T(key);
        switch (target)
        {
            case TextBox box when hint: box.Tag = text; break;
            case TextBlock block: block.Text = text; break;
            case Run run: run.Text = text; break;
            case ContentControl control: control.Content = text; break;
        }
    }
}

