namespace KnExchange.Gui;

/// <summary>
/// 変換そのものは KnExchange.Core に任せ、ここは値を集めて渡し、結果を並べるだけにする。
/// 見た目は Theme.xaml と Palette.cs（kn_dlp と同じ配色）。
/// </summary>
public partial class MainWindow : Window
{
    private readonly Settings _settings;
    private readonly bool _persist;
    private bool _busy;
    private bool _ready;

    public MainWindow(bool persist, string language, string theme)
    {
        _persist = persist;
        _settings = persist ? Settings.Load() : new Settings();
        if (theme != null) _settings.Theme = theme;

        Strings.Language = language ?? _settings.Language
            ?? (CultureInfo.CurrentUICulture.TwoLetterISOLanguageName == "ja" ? "ja" : "en");
        Lang.Japanese = Strings.Language == "ja";
        Palette.Apply(Application.Current.Resources, _settings.Theme ?? "system");

        InitializeComponent();

        FitToScreen();
        Icon = BitmapFrame.Create(new Uri("pack://application:,,,/kn_exchange.ico"));
        OutputBox.Text = _settings.OutputDir ?? System.IO.Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments), "kn_exchange");
        VanillaBox.Text = _settings.Vanilla ?? Environment.GetEnvironmentVariable("KN_EXCHANGE_VANILLA") ?? "";
        ForceBox.IsChecked = _settings.Force;
        (_settings.Gender == "female" ? GenderFemale : GenderMale).IsChecked = true;
        (Strings.Language == "ja" ? LangJa : LangEn).IsChecked = true;
        (_settings.Theme switch { "dark" => ThemeDark, "light" => ThemeLight, _ => ThemeSystem }).IsChecked = true;

        SourceInitialized += (_, _) => Palette.ApplyTitleBar(this);
        DragEnter += OnDrag;
        DragOver += OnDrag;
        DragLeave += (_, _) => HighlightInput(false);
        Drop += OnDrop;
        Closing += (_, _) => SaveSettings();

        _ready = true;
        ApplyLanguage();
        SetStatus(T("ready"));
    }

    /// <summary>
    /// 画面に収まる大きさにして中央へ置く。既定の大きさのままだと、表示倍率 150% のノート PC などで
    /// 画面より大きくなり、タイトルバーが画面の上へ出て動かせなくなる。
    /// </summary>
    private void FitToScreen()
    {
        var area = SystemParameters.WorkArea;
        Width = Math.Min(Width, area.Width);
        Height = Math.Min(Height, area.Height);
        MinWidth = Math.Min(MinWidth, Width);
        MinHeight = Math.Min(MinHeight, Height);
        Left = area.Left + (area.Width - Width) / 2;
        Top = area.Top + (area.Height - Height) / 2;
    }

    private void ApplyLanguage()
    {
        Lang.Japanese = Strings.Language == "ja";
        Loc.Refresh();
        Title = $"kn_exchange {ModConverter.Version} — {T("subtitle")}";
        VersionText.Text = $"v{ModConverter.Version}";
        AboutVersion.Text = $"kn_exchange {ModConverter.Version}  ·  MIT License";
    }

    // ---- ページと設定 ----

    private void OnNav(object sender, RoutedEventArgs e)
    {
        if (!_ready) return;
        var settings = NavSettings.IsChecked == true;
        ConvertPage.Visibility = settings ? Visibility.Collapsed : Visibility.Visible;
        SettingsPage.Visibility = settings ? Visibility.Visible : Visibility.Collapsed;
    }

    private void OnLanguage(object sender, RoutedEventArgs e)
    {
        if (!_ready) return;
        Strings.Language = LangJa.IsChecked == true ? "ja" : "en";
        ApplyLanguage();
        if (!_busy) SetStatus(T("ready"));
        SaveSettings();
    }

    private void OnTheme(object sender, RoutedEventArgs e)
    {
        if (!_ready) return;
        _settings.Theme = ThemeDark.IsChecked == true ? "dark" : ThemeLight.IsChecked == true ? "light" : "system";
        Palette.Apply(Application.Current.Resources, _settings.Theme);
        Palette.ApplyTitleBar(this);
        SaveSettings();
    }

    // ---- 入力の受け取り ----

    private void OnDrag(object sender, DragEventArgs e)
    {
        var ok = !_busy && e.Data.GetDataPresent(DataFormats.FileDrop);
        e.Effects = ok ? DragDropEffects.Copy : DragDropEffects.None;
        e.Handled = true;
        HighlightInput(ok);
    }

    private void OnDrop(object sender, DragEventArgs e)
    {
        HighlightInput(false);
        if (_busy || e.Data.GetData(DataFormats.FileDrop) is not string[] { Length: > 0 } paths) return;

        InputBox.Text = paths[0];
        NavConvert.IsChecked = true;
    }

    private void OnInputFocus(object sender, KeyboardFocusChangedEventArgs e) => HighlightInput(InputBox.IsKeyboardFocused);

    private void HighlightInput(bool on) =>
        InputBar.SetResourceReference(Border.BorderBrushProperty, on ? "Accent" : "Border");

    private void OnPickFile(object sender, RoutedEventArgs e)
    {
        var dialog = new OpenFileDialog { Title = T("pick.file"), Filter = T("pick.filter") };
        if (dialog.ShowDialog(this) == true)
            InputBox.Text = dialog.FileName;
    }

    private void OnPickFolder(object sender, RoutedEventArgs e) => PickDirectory(InputBox, "pick.folder");
    private void OnPickOutput(object sender, RoutedEventArgs e) => PickDirectory(OutputBox, "pick.output");
    private void OnPickVanilla(object sender, RoutedEventArgs e) => PickDirectory(VanillaBox, "pick.vanilla");

    private void PickDirectory(TextBox target, string titleKey)
    {
        var dialog = new OpenFolderDialog { Title = T(titleKey) };
        var current = Clean(target.Text);
        if (current != null && System.IO.Directory.Exists(current))
            dialog.InitialDirectory = current;
        if (dialog.ShowDialog(this) == true)
            target.Text = dialog.FolderName;
    }

    // ---- 実行 ----

    private ConvertOptions ReadOptions() => new()
    {
        Input = Clean(InputBox.Text),
        OutputDir = Clean(OutputBox.Text),
        Name = Clean(NameBox.Text),
        Variant = Clean(VariantBox.Text),
        Force = ForceBox.IsChecked == true,
        Vanilla = Clean(VanillaBox.Text),
        Replace = ReplaceBox.IsChecked == true,
        BaseModel = Clean(BaseBox.Text),
        Gender = GenderFemale.IsChecked == true ? "female" : "male",
    };

    /// <summary>エクスプローラーの「パスのコピー」は引用符で囲むので外す。空欄は未指定として扱う。</summary>
    private static string Clean(string text)
    {
        var value = text?.Trim().Trim('"').Trim();
        return string.IsNullOrEmpty(value) ? null : value;
    }

    private async void OnConvert(object sender, RoutedEventArgs e) => await RunAsync(inspect: false);
    private async void OnInspect(object sender, RoutedEventArgs e) => await RunAsync(inspect: true);

    /// <summary>変換は時間が掛かるので画面のスレッドでは走らせない。</summary>
    private async Task<bool> RunAsync(bool inspect)
    {
        if (_busy) return false;

        var options = ReadOptions();
        LogBox.Clear();
        Results.Children.Clear();
        ResultsEmpty.Visibility = Visibility.Collapsed;

        if (options.Input == null)
            return Fail(new ArgumentException(T("no.input")));
        if (!inspect && options.OutputDir == null)
            return Fail(new ArgumentException(T("no.output")));

        SaveSettings();
        SetBusy(true);

        try
        {
            if (inspect)
            {
                await Task.Run(() => ModInspector.Inspect(options.Input, Log));
                Results.Children.Add(MessageCard("chip.inspect", "Info", T("inspect.done"), null));
                SetStatus(T("inspect.done"));
                return true;
            }

            var reports = await Task.Run(() => ModConverter.Convert(options, Log));
            foreach (var r in reports)
            {
                ModInspector.Describe(r, Log);
                Results.Children.Add(ReportCard(r));
            }

            SetStatus(string.Format(T("done"), reports.Count));
            return true;
        }
        catch (Exception ex)
        {
            return Fail(ex);
        }
        finally
        {
            SetBusy(false);
        }
    }

    private bool Fail(Exception ex)
    {
        // 想定している失敗は文面だけ、それ以外は種類も出す（報告を受けた時に手掛かりになる）
        var expected = ex is InvalidOperationException or ArgumentException or System.IO.FileNotFoundException
            or NotSupportedException or System.IO.InvalidDataException or System.IO.IOException or UnauthorizedAccessException;
        var message = expected ? ex.Message : $"{ex.GetType().Name}: {ex.Message}";
        var hints = HintOptions.Where(o => ex.Message.Contains(o, StringComparison.Ordinal)).Select(o => T("hint." + o)).ToList();

        Log("");
        Log(T("error") + message);
        foreach (var hint in hints) Log(hint);

        Results.Children.Add(MessageCard("chip.error", "Danger", message, hints));
        SetStatus(T("failed"));
        return false;
    }

    private void SetBusy(bool busy)
    {
        _busy = busy;
        // 言語は変換の途中で変えさせない（記録が 2 つの言語で混ざる）
        ConvertButton.IsEnabled = InspectButton.IsEnabled = LangJa.IsEnabled = LangEn.IsEnabled = !busy;
        Progress.IsIndeterminate = busy;
        Progress.Visibility = busy ? Visibility.Visible : Visibility.Hidden;
        if (busy) SetStatus(T("working"));
    }

    private void SetStatus(string text) => StatusText.Text = text;

    private void Log(string message)
    {
        if (!Dispatcher.CheckAccess())
        {
            Dispatcher.BeginInvoke(() => Log(message));
            return;
        }

        var text = (message ?? "").Replace("\r\n", "\n");
        LogBox.AppendText(text.Replace("\n", "\r\n") + "\r\n");
        LogBox.ScrollToEnd();

        // 進み具合として、いま何をしているかを下のバーにも出す
        var line = text.Split('\n')[0].Trim();
        if (_busy && line.Length > 0) SetStatus(line);
    }

    // ---- 結果のカード ----

    private static T Res<T>(string key) => (T)Application.Current.FindResource(key);

    private static TextBlock Text(string text, string colour = null, string style = null, double size = 0)
    {
        var block = new TextBlock { Text = text, TextWrapping = TextWrapping.Wrap };
        if (style != null) block.Style = Res<Style>(style);
        if (colour != null) block.SetResourceReference(TextBlock.ForegroundProperty, colour);
        if (size > 0) block.FontSize = size;
        return block;
    }

    private static Border Chip(string textKey, string colour)
    {
        var text = Text(T(textKey), colour, size: 12);
        return new Border { Style = Res<Style>("Chip"), Child = text, Margin = new Thickness(0, 0, 12, 0) };
    }

    private Border MessageCard(string chipKey, string colour, string message, List<string> hints)
    {
        var body = new StackPanel();
        body.Children.Add(Text(message));
        foreach (var hint in hints ?? new List<string>())
        {
            var line = Text(hint, "Accent");
            line.Margin = new Thickness(0, 6, 0, 0);
            body.Children.Add(line);
        }

        var row = new DockPanel();
        var chip = Chip(chipKey, colour);
        chip.VerticalAlignment = VerticalAlignment.Top;
        DockPanel.SetDock(chip, Dock.Left);
        row.Children.Add(chip);
        row.Children.Add(body);

        var card = new Border { Style = Res<Style>("Card"), Child = row, Margin = new Thickness(0, 0, 0, 10) };
        if (colour == "Danger") card.SetResourceReference(Border.BorderBrushProperty, "Danger");
        return card;
    }

    private Border ReportCard(ResourceReport r)
    {
        var panel = new StackPanel();

        // 1 行目: 状態・名前・フォルダを開く
        var head = new DockPanel();
        var open = new Button { Content = T("open.folder"), Style = Res<Style>("Ghost") };
        open.Click += (_, _) => OpenFolder(r.OutputPath);
        DockPanel.SetDock(open, Dock.Right);
        head.Children.Add(open);
        var chip = Chip("chip.done", "Ok");
        DockPanel.SetDock(chip, Dock.Left);
        head.Children.Add(chip);
        var name = Text(r.Name, size: 16.5);
        name.FontWeight = FontWeights.SemiBold;
        name.VerticalAlignment = VerticalAlignment.Center;
        head.Children.Add(name);
        panel.Children.Add(head);

        var summary = string.Format(T("summary"), r.StreamCount, r.DataFiles.Count);
        if (r.Warnings.Count > 0) summary += "  ·  " + string.Format(T("notes"), r.Warnings.Count);
        var sub = Text(summary + "\n" + r.OutputPath, "Muted");
        sub.Margin = new Thickness(0, 8, 0, 0);
        panel.Children.Add(sub);

        // server.cfg へ足す行
        var ensure = $"ensure {r.Name}";
        var copy = new Button { Content = T("copy"), Style = Res<Style>("Ghost") };
        copy.Click += (_, _) => Copy(ensure, copy);
        DockPanel.SetDock(copy, Dock.Right);
        var line = new TextBlock { Text = ensure, FontFamily = Res<FontFamily>("MonoFont"), VerticalAlignment = VerticalAlignment.Center };
        TextOptions.SetTextFormattingMode(line, TextFormattingMode.Ideal);
        var ensureRow = new DockPanel();
        ensureRow.Children.Add(copy);
        ensureRow.Children.Add(line);
        var ensureBox = new Border { CornerRadius = new CornerRadius(8), Padding = new Thickness(12, 3, 4, 3), Margin = new Thickness(0, 12, 0, 0), Child = ensureRow };
        ensureBox.SetResourceReference(Border.BackgroundProperty, "Surface2");
        panel.Children.Add(ensureBox);

        // 注意
        foreach (var w in r.Warnings)
        {
            var row = new DockPanel { Margin = new Thickness(0, 9, 0, 0) };
            var dot = new Border { Width = 6, Height = 6, CornerRadius = new CornerRadius(3), Margin = new Thickness(2, 7, 10, 0), VerticalAlignment = VerticalAlignment.Top };
            dot.SetResourceReference(Border.BackgroundProperty, "Warn");
            DockPanel.SetDock(dot, Dock.Left);
            row.Children.Add(dot);
            row.Children.Add(Text(w, "Muted"));
            panel.Children.Add(row);
        }

        return new Border { Style = Res<Style>("Card"), Child = panel, Margin = new Thickness(0, 0, 0, 10) };
    }

    private void Copy(string text, Button button)
    {
        try
        {
            Clipboard.SetText(text);
            button.Content = T("copied");
        }
        catch (System.Runtime.InteropServices.COMException)
        {
            // クリップボードを他のアプリが掴んでいる時。もう一度押せば通る
        }
    }

    private void OnCopyLog(object sender, RoutedEventArgs e)
    {
        if (LogBox.Text.Length > 0) Copy(LogBox.Text, CopyLog);
    }

    private static void OpenFolder(string path)
    {
        if (path == null || !System.IO.Directory.Exists(path)) return;

        // 引数は配列で渡す（空白や記号を含むパスをそのまま開く）
        var info = new ProcessStartInfo("explorer.exe") { UseShellExecute = false };
        info.ArgumentList.Add(path);
        Process.Start(info)?.Dispose();
    }

    private void SaveSettings()
    {
        if (!_persist) return;

        _settings.Language = Strings.Language;
        _settings.OutputDir = Clean(OutputBox.Text);
        _settings.Vanilla = Clean(VanillaBox.Text);
        _settings.Gender = GenderFemale.IsChecked == true ? "female" : "male";
        _settings.Force = ForceBox.IsChecked == true;
        _settings.Save();
    }

    // ---- 自動確認 ----

    /// <summary>ボタンを押した時と同じ経路で 1 回動かし、画面の写しとログを残す。入力が "-" なら何もせず写すだけ。</summary>
    public async Task<bool> RunSmokeAsync(string input, string output, string png, string page)
    {
        var ok = true;
        if (input != "-")
        {
            InputBox.Text = input;
            OutputBox.Text = output;
            ForceBox.IsChecked = true;
            ok = await RunAsync(inspect: false);
        }

        if (page == "settings") NavSettings.IsChecked = true;
        await Task.Delay(400);
        if (page == "results") PageScroll.ScrollToVerticalOffset(330);
        await Task.Delay(200);

        var root = (FrameworkElement)Content;
        var dpi = VisualTreeHelper.GetDpi(this);
        var bitmap = new RenderTargetBitmap(
            (int)(root.ActualWidth * dpi.DpiScaleX), (int)(root.ActualHeight * dpi.DpiScaleY),
            dpi.PixelsPerInchX, dpi.PixelsPerInchY, PixelFormats.Pbgra32);
        var visual = new DrawingVisual();
        using (var dc = visual.RenderOpen())
        {
            dc.DrawRectangle(Background, null, new Rect(0, 0, root.ActualWidth, root.ActualHeight));
            dc.DrawRectangle(new VisualBrush(root), null, new Rect(0, 0, root.ActualWidth, root.ActualHeight));
        }
        bitmap.Render(visual);

        var encoder = new PngBitmapEncoder();
        encoder.Frames.Add(BitmapFrame.Create(bitmap));
        using (var file = System.IO.File.Create(png))
            encoder.Save(file);
        System.IO.File.WriteAllText(png + ".log", LogBox.Text);
        return ok;
    }
}

