using System.Runtime.InteropServices;
using System.Windows;
using System.Windows.Interop;
using System.Windows.Media;
using Microsoft.Win32;

namespace KnExchange.Gui;

/// <summary>配色。色はここ以外に直書きしない（kn_dlp と同じ値）。</summary>
public static class Palette
{
    private static readonly Dictionary<string, string> Dark = new()
    {
        ["Bg"] = "#0b0d12", ["Side"] = "#0f1218", ["Surface"] = "#141821", ["Surface2"] = "#1a1f2a",
        ["Surface3"] = "#222836", ["Border"] = "#262d3b", ["Text"] = "#e7eaf0", ["Muted"] = "#8a93a6",
        ["Faint"] = "#5c6477", ["Accent"] = "#22d3ee", ["AccentHover"] = "#67e8f9", ["AccentPress"] = "#0891b2",
        ["OnAccent"] = "#04141a", ["Selection"] = "#0891b2", ["Ok"] = "#34d399", ["Warn"] = "#fbbf24",
        ["Danger"] = "#f87171", ["Info"] = "#818cf8",
    };

    private static readonly Dictionary<string, string> Light = new()
    {
        ["Bg"] = "#f4f6f9", ["Side"] = "#eaeef3", ["Surface"] = "#ffffff", ["Surface2"] = "#f5f7fa",
        ["Surface3"] = "#e5e9ef", ["Border"] = "#d5dbe4", ["Text"] = "#161a22", ["Muted"] = "#5a6375",
        ["Faint"] = "#8b93a3", ["Accent"] = "#0891b2", ["AccentHover"] = "#06b6d4", ["AccentPress"] = "#0e7490",
        ["OnAccent"] = "#ffffff", ["Selection"] = "#a5e9f5", ["Ok"] = "#059669", ["Warn"] = "#b45309",
        ["Danger"] = "#dc2626", ["Info"] = "#4f46e5",
    };

    public static bool IsDark { get; private set; } = true;

    public static Color Get(string name, bool dark = true) =>
        (Color)ColorConverter.ConvertFromString((dark ? Dark : Light)[name]);

    /// <summary>setting は system / dark / light。system は Windows のアプリの配色に合わせる。</summary>
    public static void Apply(ResourceDictionary resources, string setting)
    {
        IsDark = setting switch
        {
            "dark" => true,
            "light" => false,
            _ => SystemIsDark(),
        };

        foreach (var (name, value) in IsDark ? Dark : Light)
        {
            var brush = new SolidColorBrush((Color)ColorConverter.ConvertFromString(value));
            brush.Freeze();
            resources[name] = brush;
        }
    }

    /// <summary>読めなければダーク。</summary>
    private static bool SystemIsDark()
    {
        try
        {
            using var key = Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Themes\Personalize");
            return key?.GetValue("AppsUseLightTheme") is not int light || light == 0;
        }
        catch (Exception ex) when (ex is System.Security.SecurityException or UnauthorizedAccessException or IOException)
        {
            return true;
        }
    }

    [DllImport("dwmapi.dll")]
    private static extern int DwmSetWindowAttribute(IntPtr hwnd, int attribute, ref int value, int size);

    /// <summary>タイトルバーを配色に合わせる（Windows 10 20H1 以降。効かない版では何も起きない）。</summary>
    public static void ApplyTitleBar(Window window)
    {
        var handle = new WindowInteropHelper(window).Handle;
        if (handle == IntPtr.Zero) return;

        var dark = IsDark ? 1 : 0;
        const int UseImmersiveDarkMode = 20;
        _ = DwmSetWindowAttribute(handle, UseImmersiveDarkMode, ref dark, sizeof(int));
    }
}

