using System.Windows;

namespace KnExchange.Gui;

internal static class Program
{
    [STAThread]
    private static int Main(string[] args)
    {
        // アイコンを描き直す（絵を変えた時に 1 回）:  kn_exchange_gui --make-icon <ico>
        if (args.Length == 2 && args[0] == "--make-icon")
        {
            AppIcon.Save(args[1]);
            return 0;
        }

        var app = new Application { ShutdownMode = ShutdownMode.OnMainWindowClose };
        app.Resources.MergedDictionaries.Add(new ResourceDictionary
        {
            Source = new Uri("/kn_exchange_gui;component/Theme.xaml", UriKind.Relative),
        });

        // 自動確認用: 画面を組み立て、同じ経路で変換し、画面の写しとログを残して終わる
        //   kn_exchange_gui --smoke <入力|-> <出力先> <png> [ja|en] [dark|light] [top|results|settings]
        if (args.Length >= 4 && args[0] == "--smoke")
        {
            string Arg(int i) => args.Length > i ? args[i] : null;
            var window = new MainWindow(persist: false, language: Arg(4), theme: Arg(5) ?? "dark");
            var ok = false;
            window.ContentRendered += async (_, _) =>
            {
                ok = await window.RunSmokeAsync(args[1], args[2], args[3], Arg(6) ?? "top");
                window.Close();
            };
            app.Run(window);
            return ok ? 0 : 1;
        }

        app.Run(new MainWindow(persist: true, language: null, theme: null));
        return 0;
    }
}

