using System.Text.Json;

namespace KnExchange.Gui;

/// <summary>画面で選んだ値の控え。%APPDATA%\kn_exchange\settings.json に置く。</summary>
public sealed class Settings
{
    public string Language { get; set; }
    /// <summary>system / dark / light。</summary>
    public string Theme { get; set; }
    public string OutputDir { get; set; }
    public string Vanilla { get; set; }
    public string Gender { get; set; }
    public bool Force { get; set; }

    private static string FilePath => Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "kn_exchange", "settings.json");

    /// <summary>読めなければ既定値で始める（壊れた設定で起動できなくなるのを避ける）。</summary>
    public static Settings Load()
    {
        try
        {
            if (File.Exists(FilePath))
                return JsonSerializer.Deserialize<Settings>(File.ReadAllText(FilePath)) ?? new Settings();
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or JsonException)
        {
        }

        return new Settings();
    }

    public void Save()
    {
        try
        {
            Directory.CreateDirectory(Path.GetDirectoryName(FilePath));
            File.WriteAllText(FilePath, JsonSerializer.Serialize(this, new JsonSerializerOptions { WriteIndented = true }));
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
        }
    }
}

