    Console.WriteLine("[細工された名前]");
    {
        var bad = new Rpf7Builder();
        bad.Root.AddFile("..X..Xevil.meta", Encoding.ASCII.GetBytes("<escaped />"));
        bad.Root.AddFile("..X..Xevil.rel", Encoding.ASCII.GetBytes("escaped"));
        bad.Root.AddFile("handling.meta", Encoding.ASCII.GetBytes("<CHandlingDataMgr />"));
        var bytes = bad.Build();
        // 組み立て側は区切り文字を受け付けないので、できあがった名前表を書き換える
        var marker = Encoding.ASCII.GetBytes("..X..Xevil");
        var patched = 0;
        for (var i = 0; i + marker.Length <= bytes.Length; i++)
        {
            if (!bytes.AsSpan(i, marker.Length).SequenceEqual(marker)) continue;
            bytes[i + 2] = (byte)'\\';
            bytes[i + 5] = (byte)'\\';
            patched++;
        }
