        var badRpf = Path.Combine(badDir, "dlc.rpf");
        File.WriteAllBytes(badRpf, bytes);
        var badOut = Path.Combine(work, "trav", "out", "a", "b");
        var badReports = ModConverter.Convert(new ConvertOptions { Input = badRpf, OutputDir = badOut }, _ => { });
        var escaped = Directory.GetFiles(Path.Combine(work, "trav"), "evil.*", SearchOption.AllDirectories);
        Check(patched == 2, $"名前表を書き換えられた（{patched} 箇所）");
        Check(escaped.Length == 0, $"区切り文字を含む名前は取り出さない（{string.Join(", ", escaped)}）");
        Check(badReports.Count == 1 && badReports[0].Warnings.Count(w => w.Contains("evil")) == 2, "取り出さなかった名前を注意に出す");
        Check(File.Exists(Path.Combine(badReports[0].OutputPath, "data", "handling.meta")), "同じ rpf の普通のファイルは取り出す");
    }
}
finally
{
    try { Directory.Delete(work, recursive: true); } catch { }
}

Console.WriteLine();
Console.WriteLine(failed == 0 ? "ALL PASS" : $"{failed} 件 FAIL");
return failed == 0 ? 0 : 1;

static byte[] BuildGxt2(params (uint Hash, string Text)[] entries)
{
    using var ms = new MemoryStream();
    using var w = new BinaryWriter(ms);

    var strings = entries.Select(e => Encoding.UTF8.GetBytes(e.Text + "\0")).ToArray();
    var offset = 8 + entries.Length * 8 + 8;

    w.Write(0x47585432u);
    w.Write((uint)entries.Length);
    for (var i = 0; i < entries.Length; i++)
    {
        w.Write(entries[i].Hash);
        w.Write((uint)offset);
        offset += strings[i].Length;
    }
    w.Write(0x47585432u);
    w.Write((uint)offset);
    foreach (var s in strings) w.Write(s);

    return ms.ToArray();
}

