using System.IO.Compression;

namespace KnExchange.Rpf7;

/// <summary>
/// RPF7 アーカイブを組み立てる。
///
/// **すべてメモリ上で 1 パスで作る。** 出来上がったバイト列を返すだけで、
/// 途中経過をディスクへ書かない。
///
/// これは意図した設計で、既知の事故を構造的に潰すためのもの:
/// アーカイブを作ってから中身を足していく方式（増分拡張）だと、
/// 入れ子の親エントリに「実体より大きいサイズ」が記録されることがあり、
/// FiveM は入れ子ヘッダを直接読むので動いてしまう一方、
/// OpenIV は RPF_INVALID_ENTRY_3 で開けなくなる。
/// 先に全要素を確定させてから書けば、この状態は原理的に発生しない。
///
/// 生成される並びは次のとおり（実ファイルの解析で確認した規則）:
///   - エントリはディレクトリごとに名前の昇順。子は連続した番号に並ぶ（幅優先）
///   - 名前ブロックはエントリ番号順。長さは 16 バイト境界へ切り上げ
///   - 本体は **追加した順** に、512 バイト境界から詰めて配置する
/// </summary>
public sealed class Rpf7Builder
{
    /// <summary>組み立て中のディレクトリ。</summary>
    public sealed class DirectoryNode
    {
        internal DirectoryNode(string name) => Name = name;

        public string Name { get; }
        internal List<DirectoryNode> Directories { get; } = new();
        internal List<FileNode> Files { get; } = new();

        /// <summary>サブディレクトリを追加する。</summary>
        public DirectoryNode AddDirectory(string name)
        {
            Validate(name);
            if (Directories.Any(d => Same(d.Name, name)) || Files.Any(f => Same(f.Name, name)))
                throw new InvalidOperationException($"同名の項目が既にあります: {name}");

            var node = new DirectoryNode(name);
            Directories.Add(node);
            return node;
        }

        /// <summary>ファイルを追加する。格納方法は中身から自動で決まる。</summary>
        public void AddFile(string name, byte[] data)
        {
            Validate(name);
            ArgumentNullException.ThrowIfNull(data);
            if (Directories.Any(d => Same(d.Name, name)) || Files.Any(f => Same(f.Name, name)))
                throw new InvalidOperationException($"同名の項目が既にあります: {name}");

            Files.Add(new FileNode(name, data));
        }

        private static bool Same(string a, string b) =>
            string.Equals(a, b, StringComparison.OrdinalIgnoreCase);

        private static void Validate(string name)
        {
            if (string.IsNullOrWhiteSpace(name))
                throw new ArgumentException("名前が空です。", nameof(name));

            // 名前は NUL 区切りで格納されるので NUL は入れられない。
            // '/' はパス区切りとして解釈されるため名前には使えない。
            if (name.Contains('\0') || name.Contains('/') || name.Contains('\\'))
                throw new ArgumentException($"名前に使えない文字が含まれています: {name}", nameof(name));
        }
    }

    internal sealed class FileNode
    {
        public FileNode(string name, byte[] data) { Name = name; Data = data; }
        public string Name { get; }
        public byte[] Data { get; }

        // Build() 中に確定する
        public byte[] Stored = Array.Empty<byte>();
        public bool IsResource;
        public uint A;              // リソース = SystemFlags / バイナリ = 展開後サイズ
        public uint B;              // リソース = GraphicsFlags / バイナリ = 暗号化フラグ
        public uint StoredSizeField;  // エントリの u24。0 は「無圧縮でそのまま格納」
        public bool IsLargeResource;  // 16MB 以上でサイズ欄を飽和させたもの
        public long Sector;
    }

    public DirectoryNode Root { get; } = new("");

    /// <summary>
    /// 直近の <see cref="Build"/> で、16MB 以上のためサイズ欄を飽和させて格納したリソース名。
    ///
    /// この形式は**実機で動くことを確認できていない**（読み取り側の解釈は実在する mod で
    /// 裏付けが取れているが、書き込んだものをゲームが読めるかは未検証）。
    /// 呼び出し側はこれを見て利用者へ注意を出すこと。
    /// </summary>
    public List<string> LargeResources { get; } = new();

    /// <summary>アーカイブを組み立ててバイト列で返す。</summary>
    public byte[] Build()
    {
        // --- 1. 各ファイルの格納形式を決める ---
        var filesInOrder = new List<FileNode>();
        CollectFiles(Root, filesInOrder);

        LargeResources.Clear();
        foreach (var file in filesInOrder)
        {
            Prepare(file);
            if (file.IsLargeResource) LargeResources.Add(file.Name);
        }

        // --- 2. エントリの並びを決める（幅優先・各階層は名前の昇順） ---
        var entries = new List<object>();   // DirectoryNode か FileNode
        var childRange = new Dictionary<DirectoryNode, (int Index, int Count)>();

        entries.Add(Root);
        var queue = new Queue<DirectoryNode>();
        queue.Enqueue(Root);

        while (queue.Count > 0)
        {
            var dir = queue.Dequeue();

            //[ 並べ替えは Ordinal（大文字小文字を区別する）で行う ]
            // ゲーム側は小文字の名前で引くため、RPF 内の名前は小文字であることが前提。
            // 呼び出し側（AssetSet / SkinPackBuilder）は既に小文字へ正規化している。
            // 大文字が混ざると並び順が変わるので、混ぜないこと。
            var children = dir.Directories.Cast<object>()
                .Concat(dir.Files)
                .OrderBy(NameOf, StringComparer.Ordinal)
                .ToList();

            childRange[dir] = (entries.Count, children.Count);
            entries.AddRange(children);

            foreach (var child in children)
                if (child is DirectoryNode sub) queue.Enqueue(sub);
        }

        // --- 3. 名前ブロック ---
        // ルートは空文字列。先頭の NUL 1 バイトがその実体になる。
        var names = new MemoryStream();
        var nameOffsets = new Dictionary<object, int>();

        foreach (var entry in entries)
        {
            nameOffsets[entry] = (int)names.Position;
            var bytes = System.Text.Encoding.UTF8.GetBytes(NameOf(entry));
            names.Write(bytes, 0, bytes.Length);
            names.WriteByte(0);
        }

        var namesActual = (int)names.Length;
        var namesLength = Rpf7Format.PadNamesLength(namesActual);

        if (namesActual > ushort.MaxValue)
            throw new InvalidOperationException(
                "名前ブロックが 64KB を超えました。エントリ名のオフセットは 16bit しかありません。");

        // --- 4. 本体の配置（追加した順に、セクタ境界へ詰める） ---
        var headerBytes = Rpf7Format.HeaderSize + entries.Count * Rpf7Format.EntrySize + namesLength;
        var nextSector = Rpf7Format.SectorsFor(headerBytes);

        foreach (var file in filesInOrder)
        {
            file.Sector = nextSector;
            nextSector += Rpf7Format.SectorsFor(file.Stored.Length);

            if (file.Sector > Rpf7Format.DirectoryMarker)
                throw new InvalidOperationException(
                    $"アーカイブが大きすぎます（{file.Name} の格納位置がセクタ番号の上限を超えました）。");
        }

        var total = nextSector * Rpf7Format.SectorSize;
        if (total > int.MaxValue)
            throw new InvalidOperationException("アーカイブが 2GB を超えました。");

        // --- 5. 書き出し ---
        var output = new byte[total];
        var span = output.AsSpan();

        Rpf7Format.WriteU32(span, 0, Rpf7Format.Magic);
        Rpf7Format.WriteU32(span, 4, (uint)entries.Count);
        Rpf7Format.WriteU32(span, 8, (uint)namesLength);
        Rpf7Format.WriteU32(span, 12, Rpf7Format.EncryptionOpen);

        for (var i = 0; i < entries.Count; i++)
        {
            var entry = entries[i];
            var o = Rpf7Format.HeaderSize + i * Rpf7Format.EntrySize;

            Rpf7Format.WriteU16(span, o, (ushort)nameOffsets[entry]);

            if (entry is DirectoryNode dir)
            {
                var (index, count) = childRange[dir];
                Rpf7Format.WriteU24(span, o + 2, 0);
                Rpf7Format.WriteU24(span, o + 5, Rpf7Format.DirectoryMarker);
                Rpf7Format.WriteU32(span, o + 8, (uint)index);
                Rpf7Format.WriteU32(span, o + 12, (uint)count);
            }
            else
            {
                var file = (FileNode)entry;
                var offsetField = (uint)file.Sector;
                if (file.IsResource) offsetField |= Rpf7Format.ResourceFlag;

                Rpf7Format.WriteU24(span, o + 2, file.StoredSizeField);
                Rpf7Format.WriteU24(span, o + 5, offsetField);
                Rpf7Format.WriteU32(span, o + 8, file.A);
                Rpf7Format.WriteU32(span, o + 12, file.B);
            }
        }

        names.GetBuffer().AsSpan(0, namesActual)
            .CopyTo(span[(Rpf7Format.HeaderSize + entries.Count * Rpf7Format.EntrySize)..]);

        foreach (var file in filesInOrder)
            file.Stored.CopyTo(span[(int)(file.Sector * Rpf7Format.SectorSize)..]);

        return output;
    }

    private static string NameOf(object entry) => entry switch
    {
        DirectoryNode d => d.Name,
        FileNode f => f.Name,
        _ => throw new InvalidOperationException(),
    };

    private static void CollectFiles(DirectoryNode dir, List<FileNode> into)
    {
        // 追加した順に本体を並べたいので、宣言順のまま辿る（名前順に並べ替えない）
        into.AddRange(dir.Files);
        foreach (var sub in dir.Directories)
            CollectFiles(sub, into);
    }

    /// <summary>ファイルの格納形式を決め、格納するバイト列を用意する。</summary>
    private static void Prepare(FileNode file)
    {
        var data = file.Data;

        if (Rpf7Format.IsResource(data))
        {
            //[ リソース（RSC7） ]
            // 無圧縮でそのまま格納し、SystemFlags / GraphicsFlags は
            // RSC7 ヘッダの +8 / +12 をそのまま転記する（実ファイルの解析で確認済み）。
            file.IsResource = true;
            file.A = Rpf7Format.ReadU32(data, 8);
            file.B = Rpf7Format.ReadU32(data, 12);

            if ((uint)data.Length < Rpf7Format.MaxU24)
            {
                file.Stored = data;
                file.StoredSizeField = (uint)data.Length;
                return;
            }

            //[ 16MB 以上 ]
            // サイズ欄を飽和させ、実サイズは格納バイト列の先頭へ埋め込む。
            // 元の配列は呼び出し側のものなので、書き換える前に複製する。
            var stored = (byte[])data.Clone();
            Rpf7Format.WriteLargeResourceSize(stored, (uint)data.Length);

            file.Stored = stored;
            file.StoredSizeField = Rpf7Format.MaxU24;
            file.IsLargeResource = true;
            return;
        }

        file.IsResource = false;
        file.B = 0;   // 暗号化フラグ。無暗号アーカイブでは常に 0

        //[ 入れ子アーカイブ ]
        // 圧縮してはいけない。ゲームは入れ子のヘッダをその場で読むため、
        // 展開が要る形で入れると読めない。無圧縮格納は u24 を 0 にして表す。
        if (Rpf7Format.IsArchive(data) ||
            file.Name.EndsWith(".rpf", StringComparison.OrdinalIgnoreCase))
        {
            StoreRaw(file, data);
            return;
        }

        //[ 通常のバイナリ ]
        var compressed = Deflate(data);

        // 圧縮しても u24 に収まらない、または縮まないなら無圧縮で格納する
        if ((uint)compressed.Length >= Rpf7Format.MaxU24 || compressed.Length >= data.Length)
        {
            StoreRaw(file, data);
            return;
        }

        file.Stored = compressed;
        file.StoredSizeField = (uint)compressed.Length;
        file.A = (uint)data.Length;
    }

    private static void StoreRaw(FileNode file, byte[] data)
    {
        file.Stored = data;
        file.StoredSizeField = 0;      // 0 = 無圧縮でそのまま格納
        file.A = (uint)data.Length;
    }

    private static byte[] Deflate(byte[] data)
    {
        using var output = new MemoryStream();
        // ヘッダ無しの raw deflate。ZLibStream ではなく DeflateStream を使う
        using (var deflate = new DeflateStream(output, CompressionLevel.Optimal, leaveOpen: true))
            deflate.Write(data, 0, data.Length);

        return output.ToArray();
    }
}
